BEGIN;
WITH p AS (SELECT value AS r FROM jsonb_array_elements($ap$[{"id": "371a6ab5-3701-4f57-9f67-a6e2620d90b5", "term": "UF8", "definition": "UF8 is an eight-fader DAW control surface made by Solid State Logic, whose name is a trademark of that company. It provides eight 100mm motorised, touch-sensitive faders, a V-Pot rotary encoder per channel, colour LCD channel displays, soft keys and transport controls, and communicates with a DAW over the industry-standard Mackie Control (MCU) and HUI protocols. It connects via USB-C, is set up through the SSL 360 software, supports multiple switchable DAW layers, and up to four units can be linked.", "plain_english": "The UF8 is a mixing controller for music software. It has eight motorised sliders and a small screen above each one. You use it to mix, play and stop your project by hand. Solid State Logic makes it. You can join up to four together for more sliders.", "purpose_function": "It exists to give tactile, multi-channel control of an in-the-box mix, so an engineer can move eight faders, tweak pan and plug-in values on V-Pots, and drive transport without the mouse. Motorised faders keep the physical controls matched to the on-screen automation.", "practical_application": "A mixing engineer uses the UF8 to ride eight track faders at once, switch DAW layers for different projects, and link extra UF8 units to build a wider bank of motorised faders.", "category": "Control Surface", "difficulty": "intermediate", "achievement_id": "285a21d4-9d43-4c4a-a93b-64bce7ca7d7d", "cross": [], "related_terms": ["UF1", "UC1", "SSL 360", "Motorised Fader", "V-Pot", "Mackie Control (MCU)"], "common_mistakes": ["Assuming the UF8 is an audio interface; it sends control data over USB and has no audio inputs or outputs.", "Forgetting to load or select the correct DAW profile/layer in SSL 360, so faders and keys map wrongly.", "Confusing the UF8 (DAW control surface) with the UC1 (plug-in controller).", "Expecting Pro Tools to use MCU; Pro Tools is driven by the HUI protocol while most other DAWs use Mackie Control."], "scenario_contexts": ["Riding eight channel faders during a live automation pass in a mix.", "Switching DAW layers on the UF8 to move between different session profiles.", "Linking two or more UF8 units to control 16 or more channels at once.", "Using a V-Pot per channel to set pan or a selected plug-in parameter."], "formula_symbolic": "", "formula_words": ""}, {"id": "9d60b552-3f29-4fc0-b7f6-e0728b129717", "term": "Allen & Heath", "definition": "Allen & Heath is a British professional-audio manufacturer, part of the Audiotonix group, that designs and builds analogue and digital mixing consoles and related signal-processing hardware. Founded in the United Kingdom in the late 1960s and based in Cornwall, England, its ranges include the dLive, Avantis, SQ, Qu and CQ digital mixers, MixWizard analogue mixers, Xone DJ mixers and AHM audio-matrix processors. The name is a proprietary trademark; the products themselves are conventional audio mixing consoles and processors.", "plain_english": "Allen & Heath is a British company that makes audio mixers. A mixer is the desk used to blend and control many sound sources at once. The brand name belongs to the company, but the gear does a standard mixing job. You meet their consoles in clubs, theatres, churches and touring shows.", "purpose_function": "The brand identifies mixing consoles and audio processors designed and built by Allen & Heath. It exists so buyers can recognise one maker's product line, feature set, workflow and support within the wider pro-audio market.", "practical_application": "A technician patches and operates an Allen & Heath console, such as an SQ or dLive, at live gigs, in installed AV systems or in houses of worship. Knowing the brand's menu layout and naming helps recall settings and troubleshoot faster.", "category": "Manufacturer", "difficulty": "intermediate", "achievement_id": "681cb58c-4a8b-470d-b37c-f9d1ca124c01", "cross": [], "related_terms": ["Mixing console", "Digital mixer", "Analogue mixer", "Audiotonix", "DiGiCo"], "common_mistakes": ["Assuming 'Allen & Heath' names a single product rather than a manufacturer with several distinct console ranges.", "Confusing similarly named ranges, such as treating SQ, Qu and CQ mixers as identical.", "Thinking Allen & Heath is a fully independent company; it operates as a brand within the Audiotonix group.", "Believing the brand only makes analogue gear, when it produces both analogue and digital mixers."], "scenario_contexts": ["A front-of-house engineer mixes a band on an Allen & Heath dLive system at a music festival.", "An AV integrator configures an AHM audio-matrix processor for a multi-room conference centre.", "A worship-team volunteer runs weekend services on an Allen & Heath SQ or Qu digital mixer.", "A club DJ performs using an Allen & Heath Xone mixer."], "formula_symbolic": "", "formula_words": ""}, {"id": "14dea277-1c63-4fab-9a6d-3f4947b3e343", "term": "Audio and Control over Ethernet", "definition": "Audio and Control over Ethernet (ACE) is an Allen & Heath proprietary audio-over-Ethernet transport that carries 64 bidirectional channels of 24-bit, 48 kHz audio, together with TCP/IP control data, over a single Cat5 cable. Introduced in 2009 with the iLive system, it bridges a MixRack (the DSP processing engine) to its remote control surface, and can link other consoles through an M-ACE option card.", "plain_english": "ACE stands for Audio and Control over Ethernet. It is Allen & Heath's own way to send audio over a network cable. One Cat5 cable carries 64 channels each way, plus the mixer's control data. Allen & Heath first used it in their iLive mixers in 2009.", "purpose_function": "It exists to send many audio channels and a console's control data down one standard Ethernet cable, replacing bulky analogue multicore snakes between a mixer's processing rack and its surface.", "practical_application": "A technician links an iLive MixRack to its control surface with one Cat5 ACE cable, or fits an M-ACE card to bridge an iLive system to another networked device.", "category": "Audio Network Protocol", "difficulty": "intermediate", "achievement_id": "979cbad6-bdb7-4504-a978-245950a62fed", "cross": [], "related_terms": ["gigaACE", "dSNAKE", "SLink", "DX Protocol", "Allen & Heath", "Redundancy"], "common_mistakes": ["Confusing ACE with the open Dante or AES67 standards; ACE is an Allen & Heath proprietary transport", "Assuming ACE runs over an ordinary office network; it needs a dedicated point-to-point Cat5 link", "Thinking ACE carries only audio; it also carries the console's control data"], "scenario_contexts": ["Linking an iLive MixRack to its remote surface over one Cat5 cable", "Fitting an M-ACE card to connect an iLive system to a network", "Running a long ACE cable to place the mixing surface far from the stage rack"], "formula_symbolic": "", "formula_words": ""}, {"id": "747af829-bd8e-4959-8e8f-31b8d6b97461", "term": "DX Protocol", "definition": "DX is an Allen & Heath proprietary audio-over-Ethernet transport that carries 32x32 channels of 96 kHz audio per connection over shielded (STP) Cat5 cable up to 100 m, with a latency of about 8 samples. Presented as an evolution of dSNAKE, it links DX-series remote expanders (such as the DX168, DX012 and DX32) and the DX Hub to compatible consoles through an SLink or gigaACE port.", "plain_english": "DX is Allen & Heath's own way to connect stage boxes to a mixer over a network cable. Each DX cable carries 32 channels in and 32 out at high quality. It links Allen & Heath's DX stage boxes and expanders to the console. It grew out of their older dSNAKE system.", "purpose_function": "It exists to distribute remote inputs and outputs to DX stage boxes over one shielded Cat5 cable, so I/O can sit near the stage instead of being wired straight to the console.", "practical_application": "A technician connects a DX168 stage box or a DX Hub to a console's SLink port with one shielded Cat5 cable, gaining 32 remote inputs and outputs at 96 kHz.", "category": "Audio Network Protocol", "difficulty": "intermediate", "achievement_id": "979cbad6-bdb7-4504-a978-245950a62fed", "cross": [], "related_terms": ["GX Protocol", "SLink", "gigaACE", "dSNAKE", "DX Hub", "DX168"], "common_mistakes": ["Confusing DX with Dante or AES67; DX is an Allen & Heath proprietary transport, not an open standard", "Using unshielded Cat5; DX requires STP (shielded) Cat5 up to 100 m", "Exceeding a DX port's limit of one DX32 or two DX168/DX164-W/DX012 expanders"], "scenario_contexts": ["Connecting a DX168 stage box to an SQ or Avantis console over one cable", "Feeding a DX Hub that fans out to several DX expanders around a stage", "Adding 96 kHz remote I/O to a dLive system through a DX-capable port"], "formula_symbolic": "", "formula_words": ""}, {"id": "669f270b-224a-475d-baae-82761a536220", "term": "GX Protocol", "definition": "GX is an Allen & Heath proprietary audio-over-Ethernet transport that carries 128x128 channels of 96 kHz audio per connection over shielded (STP) Cat5e cable up to 100 m. It connects the GX4816 remote expander rack to compatible consoles and shares the same 128-channel format as the gigaACE protocol; a single GX connection can additionally cascade DX32 and DX168/DX164-W/DX012 expanders.", "plain_english": "GX is Allen & Heath's own way to connect its large GX4816 expander rack to a mixer. One network cable carries 128 channels in and 128 out at high quality. It uses the same channel format as their gigaACE system. Extra DX stage boxes can branch off the same link.", "purpose_function": "It exists to link the high-capacity GX4816 expander to a console over one Cat5e cable, adding many remote inputs and outputs and letting smaller DX expanders cascade from it.", "practical_application": "A technician connects a GX4816 rack to a console's gigaACE or SLink port with one shielded Cat5e cable, gaining 128 channels each way plus room to cascade DX expanders.", "category": "Audio Network Protocol", "difficulty": "intermediate", "achievement_id": "979cbad6-bdb7-4504-a978-245950a62fed", "cross": [], "related_terms": ["DX Protocol", "gigaACE", "SLink", "GX4816", "DX Hub", "Allen & Heath"], "common_mistakes": ["Confusing GX with an open standard; it is an Allen & Heath proprietary transport", "Assuming GX and DX are the same; GX carries 128x128 channels while DX carries 32x32", "Using unshielded cable; GX requires STP Cat5e up to 100 m"], "scenario_contexts": ["Connecting a GX4816 expander to a dLive or Avantis system", "Building a large stage rack that cascades DX expanders off one GX link", "Adding high channel-count 96 kHz I/O through a gigaACE port"], "formula_symbolic": "", "formula_words": ""}, {"id": "1bed78ff-e103-4b64-a581-074b45ab1c24", "term": "SLink", "definition": "SLink is an Allen & Heath proprietary multi-protocol I/O port, not a protocol in itself, found on SQ, Avantis and AHM mixers (and as an option card). It automatically detects the connected device and switches between dSNAKE (48 kHz), DX, and GX/gigaACE (96 kHz) modes, and includes built-in sample-rate conversion so 48 kHz expanders work seamlessly with a 96 kHz mixing core.", "plain_english": "SLink is a smart socket made by Allen & Heath. It is a port, not a protocol of its own. It senses what you plug in and picks the right connection type automatically. This lets one socket work with older 48 kHz gear and newer 96 kHz gear.", "purpose_function": "It exists to give one physical port that runs several Allen & Heath digital connection types, so users can attach old or new stage boxes without changing cards or matching sample rates by hand.", "practical_application": "A technician plugs a dSNAKE, DX, GX or gigaACE device into an SQ or Avantis SLink port, and the port auto-selects the correct mode and converts sample rates as needed.", "category": "Audio Network Port", "difficulty": "intermediate", "achievement_id": "979cbad6-bdb7-4504-a978-245950a62fed", "cross": [], "related_terms": ["dSNAKE", "DX Protocol", "GX Protocol", "gigaACE", "Allen & Heath", "Sample Rate Conversion"], "common_mistakes": ["Calling SLink a protocol; it is an auto-sensing port that runs several protocols", "Using unshielded cable; SLink connections need STP Cat5e up to 100 m", "Assuming every SLink device runs at 96 kHz; dSNAKE gear runs at 48 kHz and is sample-rate converted"], "scenario_contexts": ["Connecting an older AR2412 dSNAKE rack to a new SQ console's SLink port", "Linking a DX168 or GX4816 expander to an Avantis over SLink", "Adding a second SLink port to an SQ or AHM with the SLink option card"], "formula_symbolic": "", "formula_words": ""}, {"id": "16e5ef06-7430-484a-a9f1-c364fbf630fe", "term": "dSNAKE", "definition": "dSNAKE is an Allen & Heath proprietary digital snake transport that carries up to 64 channels of 24-bit, 48 kHz audio in each direction over a single 100 Mbps Cat5 cable, with about 4 samples of latency. Used on the Qu and GLD consoles, it connects AudioRack stage boxes and expanders such as the AR2412, AB168 and AR84.", "plain_english": "dSNAKE is Allen & Heath's own digital snake. A snake replaces a thick bundle of audio cables with one thin one. dSNAKE sends up to 64 channels each way down one Cat5 network cable. Allen & Heath uses it on its Qu and GLD mixers to reach stage boxes.", "purpose_function": "It exists to replace a heavy analogue multicore between stage and console with one lightweight Cat5 cable, carrying many channels of remote mic and line signals digitally.", "practical_application": "A technician runs one Cat5 cable from a Qu or GLD console to an AR2412 stage box on stage, gaining remote inputs and outputs with recallable preamp control.", "category": "Audio Network Protocol", "difficulty": "intermediate", "achievement_id": "979cbad6-bdb7-4504-a978-245950a62fed", "cross": [], "related_terms": ["DX Protocol", "SLink", "Audio and Control over Ethernet", "gigaACE", "AR2412", "Allen & Heath"], "common_mistakes": ["Confusing dSNAKE with Dante; dSNAKE is an Allen & Heath proprietary transport, not an open standard", "Expecting 96 kHz; dSNAKE runs at 48 kHz with up to 64 channels each way", "Trying to run dSNAKE through office network switches; it is a point-to-point Cat5 link"], "scenario_contexts": ["Running one Cat5 cable from a GLD console to an AR2412 stage box", "Daisy-chaining an AB168 expander from a Qu console's stage rack", "Replacing a heavy analogue multicore on a small live show"], "formula_symbolic": "", "formula_words": ""}, {"id": "7698e3f2-b156-48bb-a094-6d3d4374a7a1", "term": "gigaACE", "definition": "gigaACE is an Allen & Heath proprietary Gigabit audio-over-Ethernet transport that carries 128 bidirectional channels of 96 kHz audio over Cat5e cable (1000Base-T), with about 5 samples of latency, and supports dual-cable redundancy with no audio dropout. Used on dLive, Avantis, SQ and the AHM matrix processor, it also carries control data and enables GX4816 and DX Hub expansion.", "plain_english": "gigaACE is Allen & Heath's fast audio network for its bigger mixers. One Cat5e cable carries 128 channels in and 128 out at high quality. You can run a second cable as a backup, so audio keeps flowing if one fails. Allen & Heath uses it on dLive, Avantis and SQ systems.", "purpose_function": "It exists as a high-capacity, low-latency backbone that links console surfaces to their processing racks and expanders over one Gigabit Ethernet cable, with optional redundancy for critical shows.", "practical_application": "A technician links a dLive surface to its MixRack over gigaACE, often running two cables so a redundant link takes over instantly if one cable fails.", "category": "Audio Network Protocol", "difficulty": "intermediate", "achievement_id": "979cbad6-bdb7-4504-a978-245950a62fed", "cross": [], "related_terms": ["GX Protocol", "DX Protocol", "SLink", "Audio and Control over Ethernet", "Allen & Heath", "Redundancy"], "common_mistakes": ["Confusing gigaACE with Dante or AES67; it is an Allen & Heath proprietary transport", "Assuming Fast Ethernet works; gigaACE needs a Gigabit (1000Base-T) Cat5e link", "Believing a single cable is fault-tolerant; redundancy requires a second gigaACE cable"], "scenario_contexts": ["Linking a dLive S Class surface to its MixRack with a redundant dual-cable gigaACE run", "Connecting a GX4816 expander to an Avantis over gigaACE", "Networking an AHM matrix processor for a fixed installation"], "formula_symbolic": "", "formula_words": ""}, {"id": "a0d2ed4d-1156-41c5-a48e-4e2fba6c8e40", "term": "Avantis", "definition": "Avantis is a proprietary digital live-sound mixing console made by Allen & Heath, built on the XCVI FPGA processing core running at 96 kHz with a 96-bit accumulator and 0.7 ms latency. The standard model offers 64 input channels and 42 configurable mix buses (expandable to 96 channels and 56 mixes with the dPack license) across dual 15.6-inch touchscreens with 24 motorized faders. It sits between the SQ and dLive families and shares the dLive-derived XCVI engine.", "plain_english": "Avantis is a digital mixing desk made by Allen & Heath. A mixing desk blends many microphones and instruments into the sound you hear. Avantis uses two touchscreens and moving faders to control the mix. It handles 64 channels and is used at live shows.", "purpose_function": "It provides a mid-sized, high-resolution digital mixing platform that brings dLive-class processing to a smaller, more affordable console. It exists to give engineers powerful live mixing without the size or cost of a full dLive system.", "practical_application": "A front-of-house or monitor engineer uses an Avantis surface at a concert or house of worship to mix inputs, route buses, and run effects. Technicians pair it with a compatible AudioRack or GX expander for stage inputs.", "category": "Digital mixing console", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["dLive", "SQ", "Avantis Solo", "Avantis dPack", "Continuity UI", "Avantis Director"], "common_mistakes": ["Assuming Avantis uses the same processing engine as SQ; it actually uses the dLive-derived XCVI core.", "Believing the full 96 channels and 56 mixes are available by default; the extra capacity needs the dPack license.", "Confusing the Avantis surface with a MixRack; Avantis is a console that connects to separate stage-box I/O."], "scenario_contexts": ["Mixing front-of-house for a touring band at a mid-sized theatre.", "Running monitor mixes for a multi-band festival stage.", "Serving as the main console in a house-of-worship install with remote stage racks."], "formula_symbolic": "", "formula_words": ""}, {"id": "e04e5c41-4aee-42b1-ab3c-d1043e2e5b30", "term": "Avantis Director", "definition": "Avantis Director is a free Windows and macOS application from Allen & Heath that provides offline editing and online remote control of an Avantis console over a TCP/IP network connection. Offline it builds and edits show files and system settings; online it mirrors and controls the live mixer from a laptop.", "plain_english": "Avantis Director is free software for a Windows or Mac computer. It works with the Avantis mixing desk. You can build a show on the computer before the event, with no desk connected. At the show, it connects over a network and controls the real desk from anywhere in the room.", "purpose_function": "It lets engineers prepare shows in advance and control the console remotely, so they are not tied to the physical mix position. This speeds setup and allows tuning the sound from out in the audience.", "practical_application": "An engineer edits channel names, scenes, and routing on a laptop at home, then loads the file into the Avantis at the venue. During soundcheck they walk the room with the laptop to adjust monitors and EQ.", "category": "Remote control software", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Avantis", "dLive Director", "MixPad", "OneMix", "Continuity UI"], "common_mistakes": ["Thinking Director streams audio; it is a control and editing app only, not a monitoring tool.", "Assuming offline edits appear on the desk automatically; the show file must be transferred or synced to the console.", "Confusing Director (desktop control/editor) with MixPad (mobile control app)."], "scenario_contexts": ["Programming scenes and channel lists at home before a corporate event.", "Remotely tuning the PA from the middle of the venue during soundcheck.", "Training a new operator on the software without needing the console present."], "formula_symbolic": "", "formula_words": ""}, {"id": "17f324fd-94d8-4dcd-b8d9-f3d8784c9d34", "term": "Avantis Solo", "definition": "Avantis Solo is a compact single-screen variant of the Allen & Heath Avantis console, with one 15.6-inch touchscreen, 12 faders across 6 layers, and 18 assignable SoftKeys. It runs the same XCVI FPGA core at 96 kHz and offers the same 64 input channels and 42 mix buses (96/56 with dPack) as the dual-screen Avantis.", "plain_english": "Avantis Solo is a smaller version of the Avantis mixing desk. It has one touchscreen instead of two, and 12 faders instead of 24. Inside, it is just as powerful as the bigger Avantis. It suits smaller stages or tight spaces.", "purpose_function": "It gives the full Avantis processing power in a smaller, lighter, lower-cost surface for users who do not need two screens or 24 faders. It exists to broaden the Avantis platform to compact rigs.", "practical_application": "A technician chooses Avantis Solo for a club, a smaller house of worship, or a portable rig where desk space and weight matter but full processing is still needed.", "category": "Digital mixing console", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Avantis", "Avantis dPack", "Continuity UI", "SQ", "dLive"], "common_mistakes": ["Assuming the Solo is weaker inside; it shares the same XCVI core and channel count as the standard Avantis.", "Expecting 24 faders; the Solo has 12 faders over 6 layers.", "Thinking dPack is included; the 96-channel/56-mix expansion still requires the dPack license."], "scenario_contexts": ["Mixing a small club show where desk footprint is limited.", "Serving as a compact monitor console beside a larger front-of-house desk.", "Providing a portable, single-screen mixer for a touring support act."], "formula_symbolic": "", "formula_words": ""}, {"id": "d3336223-451e-4ae6-a677-5c592c42fd8a", "term": "Avantis dPack", "definition": "Avantis dPack is a paid software feature-unlock license from Allen & Heath that expands an Avantis or Avantis Solo from 64 input channels and 42 mixes to 96 channels and 56 mixes, and adds dLive-derived DSP. The added processing includes the DEEP compressor and preamp emulations, the NEQ12 EQ, 24 instances of the Dyn8 multiband/dynamic-EQ processor, and extra RackExtra FX.", "plain_english": "Avantis dPack is a paid upgrade key for the Avantis mixing desk. It unlocks more channels and more mix outputs. It also adds extra sound-shaping tools borrowed from the bigger dLive system. You buy it as a license, not as new hardware.", "purpose_function": "It lets owners grow an Avantis when a show needs more channels, buses, or high-end processing, without buying a new console. It exists as an optional software upgrade path for the platform.", "practical_application": "A technician activates dPack on an Avantis for a large festival needing more than 64 inputs, or to use the DEEP emulations and Dyn8 dynamic EQ on key channels.", "category": "DSP upgrade license", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Avantis", "Avantis Solo", "dLive", "Dyn8", "DEEP"], "common_mistakes": ["Thinking dPack is a hardware card; it is a software license that unlocks existing capability.", "Assuming it must be bought at purchase; it can be added later to an existing console.", "Believing the extra channels and processing are free defaults on Avantis."], "scenario_contexts": ["Unlocking 96 channels for a large multi-band festival input list.", "Adding DEEP compressor emulations for studio-style processing on vocals.", "Enabling Dyn8 dynamic EQ across a drum kit to control resonances."], "formula_symbolic": "", "formula_words": ""}, {"id": "7ec50832-668d-4990-968c-42e053f21908", "term": "CQ", "definition": "CQ is a family of ultra-compact 96 kHz digital mixers from Allen & Heath, comprising the desktop CQ-12T and CQ-18T (with a 7-inch touchscreen) and the rack/stage-box CQ-20B. All models have built-in dual-band Wi-Fi and assistive features such as Gain Assistant, Feedback Assistant, and FX Assist, and are controlled by the CQ MixPad and CQ4You apps.", "plain_english": "CQ is a line of small digital mixers from Allen & Heath. They are made for gigging bands, small venues, and streaming. Each one has built-in Wi-Fi so you can mix from a phone or tablet. Smart helper tools set gain and fight feedback for you.", "purpose_function": "The CQ range provides simple, portable digital mixing with helper tools that make setup fast for non-expert users. It exists to serve small live, rehearsal, streaming, and AV setups.", "practical_application": "A technician sets up a CQ-18T for a pub gig, uses Gain Assistant to set input levels quickly, and mixes wirelessly from a tablet while the band plays.", "category": "Digital mixing console", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["CQ-MixPad", "CQ4You", "Qu", "SQ", "Custom Control"], "common_mistakes": ["Confusing CQ with the larger Qu or SQ ranges; CQ is the smallest, most compact family.", "Assuming CQ needs an external Wi-Fi router; the mixers have Wi-Fi built in.", "Treating Gain and Feedback Assistant as automatic mixing; they assist setup but do not replace an engineer's judgement."], "scenario_contexts": ["Mixing a gigging band from a tablet at a small pub or club.", "Running audio for a corporate presentation or house of worship AV setup.", "Capturing a multitrack recording or livestream from a rehearsal space."], "formula_symbolic": "", "formula_words": ""}, {"id": "f299f360-4127-44b5-809b-dc8449b05703", "term": "CQ-MixPad", "definition": "CQ MixPad is Allen & Heath's free remote-mixing app for the CQ series, running on iOS, Android, Windows, and macOS and connecting over Wi-Fi. It gives full control of the CQ mixer, from mixing to firmware updates, and allows two devices to connect at once with independent control.", "plain_english": "CQ MixPad is a free app for the Allen & Heath CQ mixers. It runs on phones, tablets, and computers. It connects over Wi-Fi and gives you full control of the mixer. Two people can each use it at the same time.", "purpose_function": "It lets an engineer control the whole CQ mixer wirelessly from anywhere in the room, which is useful because some CQ models have no faders of their own. It exists to provide flexible, portable control of the console.", "practical_application": "A technician mixes a CQ-20B stage box entirely from a laptop or tablet running CQ MixPad, walking the room to check coverage while a bandmate tweaks monitors on a second device.", "category": "Remote control app", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["CQ", "CQ4You", "MixPad", "SQ MixPad", "Custom Control"], "common_mistakes": ["Confusing CQ MixPad (full engineer control) with CQ4You (personal monitor mixing only).", "Assuming it is iOS-only; it also runs on Android, Windows, and macOS.", "Expecting the app to receive audio for monitoring; it is a control app, not an audio feed."], "scenario_contexts": ["Controlling a faderless CQ-20B entirely from a tablet.", "Walking the venue to fine-tune the PA during a live show.", "Running a CQ firmware update from a connected laptop."], "formula_symbolic": "", "formula_words": ""}, {"id": "1f12463e-a540-40c1-b9c3-171bfdb79b27", "term": "CQ4You", "definition": "CQ4You is Allen & Heath's free personal monitor-mixing app for the CQ series, available on iOS and Android. It lets each performer control their own monitor mix from a phone, freeing the engineer to focus on the front-of-house sound.", "plain_english": "CQ4You is a free app for performers using an Allen & Heath CQ mixer. Each musician uses it to set their own monitor sound. That is the sound they hear on stage. This lets the engineer focus on the audience mix instead.", "purpose_function": "It hands personal monitor control to the musicians so the engineer does not have to adjust every stage mix by hand. It exists to speed up monitor setup and give performers control of what they hear.", "practical_application": "At soundcheck, each band member opens CQ4You on their phone and dials in their own wedge or in-ear mix while the engineer sets the front-of-house sound.", "category": "Personal monitor app", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["CQ", "CQ-MixPad", "OneMix", "Qu-You", "SQ4You"], "common_mistakes": ["Confusing CQ4You (musicians' personal monitors) with CQ MixPad (full engineer control).", "Thinking one performer can change another's monitor mix; each user controls only their own mix within the access the engineer allows.", "Assuming it runs on desktop computers; it is a smartphone app for iOS and Android."], "scenario_contexts": ["Band members setting their own in-ear mixes during soundcheck.", "A singer adjusting more vocal in their monitor mid-set from their phone.", "Freeing the engineer to focus on front-of-house while performers self-manage monitors."], "formula_symbolic": "", "formula_words": ""}, {"id": "06522dec-e8fe-4203-92fe-95c27188d125", "term": "Continuity UI", "definition": "Continuity UI is Allen & Heath's name for the Avantis control interface, which links the physical faders and rotaries with the touchscreens so hardware and screen controls behave as one workflow. Touching a fader or rotary brings the related channel processing to the screen, and each screen adds Touch & Turn plus assignable Soft Rotary controls.", "plain_english": "Continuity UI is the way the Avantis mixing desk is laid out. It links the physical knobs and faders to the touchscreens. When you touch a control, the screen shows the matching settings. This keeps mixing fast and easy to follow.", "purpose_function": "It exists to make mixing quicker by keeping hardware and touchscreen controls tied together, so an engineer reaches settings with fewer menu steps. The goal is an intuitive, fast workflow.", "practical_application": "On an Avantis, an engineer touches a channel fader and the screen instantly shows that channel's EQ and dynamics, and they assign frequently used parameters to the Soft Rotaries for quick access.", "category": "Console user interface", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Avantis", "Avantis Solo", "SuperStrip", "Soft Rotary", "Touch & Turn"], "common_mistakes": ["Treating Continuity UI as a separate app; it is the built-in interface design of the Avantis surface.", "Assuming it works only on the touchscreen; the concept links the physical controls and the screen together.", "Confusing it with SuperStrip, which is one channel-processing control block within the workflow."], "scenario_contexts": ["Quickly reaching a channel's EQ by touching its fader during a live mix.", "Assigning key parameters to Soft Rotaries for fast hands-on control.", "Training a new operator on the linked hardware-and-screen Avantis workflow."], "formula_symbolic": "", "formula_words": ""}, {"id": "31d15d36-3398-4cfc-bfd7-009dc50b4a6a", "term": "Custom Control", "definition": "Custom Control is Allen & Heath's cross-platform control app for building bespoke, simplified control interfaces over AHM processors, dLive, and Avantis systems. It exposes levels, mutes, sends, preset recall, source selection, and metering, runs on iOS and Android or on A&H CC-7/CC-10 touch panels, and supports kiosk or bring-your-own-device use with user profiles and password protection.", "plain_english": "Custom Control is an Allen & Heath app for installed sound systems. An installer builds a simple, custom control screen for a room. Everyday users then tap it to change volume, mute, or pick a music source. It works on phones, tablets, or wall-mounted A&H touch panels.", "purpose_function": "It gives non-technical users a safe, simplified way to operate an A&H audio system without touching the full mixer. It exists for installs like bars, hotels, and conference rooms where end users need only basic control.", "practical_application": "An integrator designs a control page for a hotel function room, then deploys it on a wall-mounted CC-10 so staff can recall presets and set zone levels without a mixing engineer.", "category": "Installed-sound control app", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Custom Control Editor", "AHM", "dLive", "Avantis", "Qu-Control"], "common_mistakes": ["Thinking Custom Control is a full mixing app; it exposes only the simplified controls an installer chooses to publish.", "Assuming it works with any A&H mixer; it targets AHM, dLive, and Avantis systems.", "Confusing the Custom Control app (runtime) with the Custom Control Editor (the design software)."], "scenario_contexts": ["Wall-panel volume and source control in a hotel or bar zone.", "Preset recall and paging in a conference or corporate room.", "Simple, locked-down operation for venue staff with no audio training."], "formula_symbolic": "", "formula_words": ""}, {"id": "73f22173-d72a-4e7b-864f-bbd9be99ec41", "term": "Custom Control Editor", "definition": "Custom Control Editor is Allen & Heath's design software used to build the layouts run by the Custom Control app. Integrators lay out screens and control widgets graphically, then upload the finished configuration to the AHM processor, Avantis, or dLive MixRack for deployment.", "plain_english": "Custom Control Editor is the software an installer uses to design a control screen. You drag buttons and sliders onto a page to build the layout. Then you upload that layout to the audio system. Everyday users run it later in the Custom Control app.", "purpose_function": "It exists to let integrators design and program the simplified control panels that end users will operate, separating the design step from everyday use. This keeps setup in expert hands.", "practical_application": "An installer builds a page of source buttons and zone faders in Custom Control Editor, uploads it to an AHM processor, and hands staff a locked tablet running the Custom Control app.", "category": "Control design software", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Custom Control", "AHM", "dLive MixRack", "Avantis", "Qu-Control"], "common_mistakes": ["Confusing the Editor (design tool) with the Custom Control app (the runtime end users touch).", "Assuming end users edit layouts; the Editor is meant for the integrator, not the operator.", "Forgetting that a layout must be uploaded to the processor or MixRack before it works."], "scenario_contexts": ["Designing a hotel zone-control panel before an install goes live.", "Updating a conference-room control layout and re-uploading it to the AHM.", "Preparing a locked, simplified interface for untrained venue staff."], "formula_symbolic": "", "formula_words": ""}, {"id": "cf36c309-1374-4b99-9b9b-1eeaa934c60c", "term": "MixPad", "definition": "MixPad is Allen & Heath's family name for its full remote-control mixing apps, with a version tied to each console range (for example SQ MixPad, CQ MixPad, dLive MixPad, and Qu MixPad). The apps run on tablets, phones, and computers, connect to the mixer over a Wi-Fi or wired network, and provide engineer-level control plus offline show preparation.", "plain_english": "MixPad is the name Allen & Heath gives its full mixing apps. Each mixer range has its own MixPad version. The app runs on a tablet, phone, or computer. It connects over the network and lets an engineer control the whole desk from anywhere in the room.", "purpose_function": "MixPad apps give engineers complete wireless control of the console away from the mix position, and let them build shows offline in advance. They exist to add mobility and preparation to A&H mixers.", "practical_application": "An engineer runs the matching MixPad app on a tablet to mix from the audience, then later edits scenes and channel lists offline at home before the next show.", "category": "Remote control app", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["CQ-MixPad", "SQ MixPad", "dLive MixPad", "OneMix", "Avantis Director"], "common_mistakes": ["Thinking one MixPad app works with every A&H mixer; each console family has its own MixPad version.", "Confusing MixPad (full engineer control) with OneMix or the 4You apps (personal monitor mixing).", "Assuming MixPad streams audio; it is a control and editing app, not an audio monitor."], "scenario_contexts": ["Mixing front-of-house from a tablet out in the venue.", "Setting monitor mixes on stage next to the performers.", "Preparing scenes and channel lists offline before load-in."], "formula_symbolic": "", "formula_words": ""}, {"id": "efd8bacd-d90c-4feb-9f46-01072027c1a1", "term": "OneMix", "definition": "OneMix is Allen & Heath's personal monitoring app that lets a single performer control only their own monitor or in-ear mix from a mobile device. Multiple instances run at once, each isolated so one musician cannot affect another's monitor mix or the front-of-house output; it is offered for systems such as dLive and Avantis and originated on the earlier iLive range.", "plain_english": "OneMix is an Allen & Heath app for performers. Each musician uses it to control just their own stage or in-ear sound. It cannot change anyone else's mix or the main audience mix. The engineer decides how much control each person gets.", "purpose_function": "It gives each performer safe, limited control of their own monitor mix, so the engineer does not adjust every mix by hand. It exists to speed monitoring and let musicians hear exactly what they want.", "practical_application": "Each band member opens OneMix on an iPad and sets their own in-ear balance during soundcheck, while the engineer keeps full control of the console and front-of-house.", "category": "Personal monitor app", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["MixPad", "CQ4You", "Qu-You", "dLive", "Avantis"], "common_mistakes": ["Confusing OneMix (one performer, one mix) with MixPad (full engineer control of the whole desk).", "Assuming a performer can change other monitor mixes; each OneMix session is isolated to that user.", "Thinking it gives unlimited control; the engineer sets how much each performer can adjust."], "scenario_contexts": ["A musician setting their own in-ear mix during soundcheck.", "Several performers each controlling their own monitors at once during a show.", "A drummer trimming their wedge mix without touching the main console."], "formula_symbolic": "", "formula_words": ""}, {"id": "eefa6499-0e65-4162-800a-fc0f34a5cad9", "term": "Qu", "definition": "Qu is Allen & Heath's range of compact digital mixing consoles, with classic models Qu-16, Qu-24, Qu-32, and the faderless Qu-Pac and Qu-SB. Classic Qu mixers use 24-bit, 48 kHz processing with AnaLOGIQ digitally controlled preamps, motorized faders, and a touchscreen, and are controlled or extended by apps such as Qu-Pad, Qu-You, and Qu-Control.", "plain_english": "Qu is a line of digital mixing desks from Allen & Heath. The desk versions have moving faders and a touchscreen. Two versions, the Qu-Pac and Qu-SB, have no faders and are controlled from an app. Qu desks are popular for live bands, clubs, and installs.", "purpose_function": "The Qu range provides affordable digital mixing with recallable preamps, effects, and app control for small-to-mid live and install work. It exists as A&H's mainstream compact digital console line.", "practical_application": "A technician mixes a club band on a Qu-24, using its motorized faders and touchscreen, and connects a Qu-Pad iPad app to adjust monitors from the stage.", "category": "Digital mixing console", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Qu-Control", "SQ", "CQ", "Avantis", "MixPad"], "common_mistakes": ["Assuming all Qu models process at 96 kHz; the classic Qu mixers run at 48 kHz, 24-bit.", "Thinking every Qu has faders; the Qu-Pac and Qu-SB are faderless and app-controlled.", "Confusing Qu with the larger SQ or dLive ranges."], "scenario_contexts": ["Mixing a live band at a club on a Qu-24 console.", "Using a faderless Qu-SB as a compact, app-controlled mixer in an install.", "Recording a multitrack of a rehearsal to a USB drive from a Qu-16."], "formula_symbolic": "", "formula_words": ""}, {"id": "e2bb670a-3d6a-40b3-a375-7d22695ffd34", "term": "Qu-Control", "definition": "Qu-Control is Allen & Heath's installer-oriented iOS app that gives a simplified end-user control interface for Qu mixers. An installer configures up to five screens with up to fifteen control widgets each for tasks like source selection, master or zone level, scene recall, and mic paging; it is password-protected and connects over Wi-Fi to the mixer's network port.", "plain_english": "Qu-Control is an Allen & Heath app for installed Qu mixers. An installer builds a few simple screens with buttons and sliders. Everyday staff then tap them to pick a music source, set volume, or recall a preset. A password stops users from reaching the full mixer.", "purpose_function": "It exists to let non-technical operators run an installed Qu system safely, exposing only the simple controls the installer chooses. Complex setup stays with experienced users on the console or Qu-Pad.", "practical_application": "An installer builds a Qu-Control screen for a hotel bar so staff can choose a music source and set the level from an iPad, without access to routing or processing.", "category": "Installed-sound control app", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Qu", "Qu-Pad", "Custom Control", "SQ Control", "MixPad"], "common_mistakes": ["Confusing Qu-Control (simplified installer app) with Qu-Pad (full engineer control app).", "Assuming end users build the screens; the installer configures them and locks the app.", "Expecting it to work without a network; it needs Wi-Fi from a router connected to the mixer's network port."], "scenario_contexts": ["Background-music source and level control for a hotel lobby or bar.", "Simple scene recall and mic paging in a conference room.", "Locked, staff-friendly control of an installed Qu system with no audio training."], "formula_symbolic": "", "formula_words": ""}, {"id": "8f08fa48-331c-4509-9363-f98ba13d6785", "term": "Qu-Drive", "definition": "Qu-Drive is Allen & Heath's built-in USB recording and playback system on its Qu series digital mixers. It records multitrack audio directly to a connected USB drive (18 tracks at 48 kHz, 24-bit on the Qu-16: 16 input channels plus a stereo pair) as well as a separate stereo mix, with no computer required. Playback returns from the same USB drive to the console.", "plain_english": "Qu-Drive is a recorder built into Allen & Heath Qu mixing desks. It saves the show straight to a USB stick or drive. You do not need a laptop. It can record many channels at once, or just a stereo mix.", "purpose_function": "It lets an engineer record and play back a live show directly from the mixer, so no external recorder or computer is needed. Allen & Heath owns the Qu-Drive name; the underlying method is onboard USB multitrack recording.", "practical_application": "A technician plugs a formatted USB drive into a Qu console to capture a full multitrack recording of a gig for later mixing, or a stereo board mix as a quick reference of the night.", "category": "Onboard recording", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Qu", "SQ-Drive", "SuperStrip", "Qu-You", "Multitrack recording"], "common_mistakes": ["Assuming any USB drive works; Allen & Heath requires a drive formatted and fast enough for the track count", "Confusing the two-track stereo recording with the full multitrack recording", "Expecting Qu-Drive to record at 96 kHz; the Qu console runs at 48 kHz"], "scenario_contexts": ["Recording a band's live set as multitrack for a later studio mix", "Capturing a stereo board mix as a rough reference of the show", "Playing back walk-in music or backing tracks from USB before doors open"], "formula_symbolic": "", "formula_words": ""}, {"id": "5ed846e8-2baa-417f-a7c3-6382d0598139", "term": "Qu-You", "definition": "Qu-You is Allen & Heath's personal monitor mixing app for the Qu series. It runs on Apple iOS devices and lets each performer control their own monitor (aux) mix over Wi-Fi. It sends control data only and does not stream audio to the device.", "plain_english": "Qu-You is an app for Allen & Heath Qu mixers. It lets a musician set their own stage monitor sound. Each player can turn their own parts up or down. This frees the engineer to mix the main speakers.", "purpose_function": "It moves personal monitor control to the performers, freeing the engineer to focus on the front-of-house mix. Allen & Heath owns the Qu-You name; the underlying method is remote wireless control of aux monitor sends.", "practical_application": "A drummer uses Qu-You on an iPhone to raise their own vocal in the wedge monitor without asking the engineer.", "category": "Personal monitor app", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Qu", "SQ4You", "dLive OneMix", "SQ MixPad", "Monitor mix"], "common_mistakes": ["Expecting the app to play audio on the phone; it only sends control data to the mixer", "Assuming it runs on Android; Qu-You is iOS only", "Confusing Qu-You (performer monitors) with Qu-Pad or MixPad (full engineer control)"], "scenario_contexts": ["A guitarist adjusting their own in-ear monitor mix during soundcheck", "Several band members each controlling their own wedge mix on stage", "A worship team where each musician manages their own monitors on tablets"], "formula_symbolic": "", "formula_words": ""}, {"id": "60b8c3ef-6dca-454f-871b-9ad758015e30", "term": "SQ", "definition": "SQ is Allen & Heath's series of compact 96 kHz digital mixing consoles for live sound, AV and installation. All models share the XCVI FPGA processing core, run at 96 kHz with under 0.7 ms latency, and provide 48 processing channels. The range includes the SQ-5, SQ-6, SQ-7 and rackmount SQ-Rack, plus the enhanced SQ+ models.", "plain_english": "SQ is a family of digital mixing desks made by Allen & Heath. They mix live music, speech and AV sound. They all use the same fast processing chip inside. Bigger models add more faders and inputs, but the audio engine is the same.", "purpose_function": "It provides a scalable digital console platform where every model shares one audio engine, so shows and settings transfer between the different sizes. Allen & Heath owns the SQ name.", "practical_application": "An engineer chooses an SQ-5 for a small venue and an SQ-7 for a larger stage, then moves the same show file between them.", "category": "Digital mixer", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["dLive", "Qu", "SuperStrip", "SQ-Drive", "SQ MixPad"], "common_mistakes": ["Assuming a bigger SQ sounds better; all models share the same XCVI core and 96 kHz engine", "Confusing SQ (the console family) with SQ MixPad (its control app)", "Thinking the physical fader count equals the number of channels the desk can process"], "scenario_contexts": ["Mixing front-of-house for a live band in a club or theatre", "A fixed install in a house of worship or conference room", "Running monitors from stage with the same console family used at front of house"], "formula_symbolic": "", "formula_words": ""}, {"id": "6eadd3e3-86b0-4857-8b15-3b858e6cd803", "term": "SQ MixPad", "definition": "SQ MixPad is Allen & Heath's remote-control and editor application for the SQ series. Its online mode gives an engineer wireless control of the main mixing functions of an SQ console over a network, and its offline mode lets them build and edit shows away from the desk. It runs on iOS, Android, Windows and macOS.", "plain_english": "SQ MixPad is an app that controls an Allen & Heath SQ mixer. The engineer can mix from anywhere in the room using a tablet or laptop. An offline mode lets them set up a show before the gig. It works on phones, tablets and computers.", "purpose_function": "It lets the engineer mix remotely from within the room and prepare shows offline, extending the console beyond the physical mix position. Allen & Heath owns the SQ MixPad name.", "practical_application": "An engineer walks the room with an iPad running SQ MixPad to tune monitor mixes from the stage, or preps scenes on a laptop the night before a show.", "category": "Remote control app", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SQ", "SQ4You", "dLive MixPad", "SQ-Drive", "SuperStrip"], "common_mistakes": ["Assuming it is iPad-only; SQ MixPad also runs on Android, Windows and macOS", "Confusing SQ MixPad (full engineer control) with SQ4You (single-performer monitors)", "Forgetting the console and the device must share the same network to connect"], "scenario_contexts": ["Tuning the PA from the middle of the audience on a tablet", "Setting up monitor mixes while standing on stage next to a performer", "Preparing a show file offline before arriving at the venue"], "formula_symbolic": "", "formula_words": ""}, {"id": "23c94326-19ae-4d94-9e05-59340b0da311", "term": "SQ-Drive", "definition": "SQ-Drive is Allen & Heath's built-in USB recording and playback system on the SQ series. It records multitrack audio directly to a USB drive (16 channels at 96 kHz or 32 channels at 48 kHz) or a stereo mix of the performance, with no external software or computer required.", "plain_english": "SQ-Drive records sound straight to a USB drive from an SQ mixer. No computer is needed. It can capture many channels at once, or just a stereo mix of the show.", "purpose_function": "It captures live shows directly on the console for archiving, virtual soundcheck or later mixing. Allen & Heath owns the SQ-Drive name; the underlying method is onboard USB multitrack recording.", "practical_application": "An engineer records every input to SQ-Drive during a gig, then plays those tracks back the next day to rehearse the mix without the band present.", "category": "Onboard recording", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SQ", "Qu-Drive", "SuperStrip", "SQ MixPad", "Multitrack recording"], "common_mistakes": ["Forgetting the track count halves at 96 kHz (16 channels) versus 48 kHz (32 channels)", "Using a USB drive that is too slow or wrongly formatted for the track count", "Confusing the multitrack recording with the separate stereo recording"], "scenario_contexts": ["Capturing a multitrack recording of a concert for a later studio mix", "Recording a rehearsal to run a virtual soundcheck the next day", "Making a quick stereo record of a talk or performance for archive"], "formula_symbolic": "", "formula_words": ""}, {"id": "a8437db6-c2f1-416a-9c24-90b5258854a4", "term": "SQ4You", "definition": "SQ4You is Allen & Heath's free personal monitor mixing app for the SQ series. It runs on iOS and Android and lets each performer control their own monitor mix over Wi-Fi. Several performers can connect at once (up to seven when no engineer MixPad session is running).", "plain_english": "SQ4You is a free app for Allen & Heath SQ mixers. It lets a musician build their own stage monitor mix. Each player adjusts what they hear on their own phone or tablet. This lets the engineer focus on the main sound.", "purpose_function": "It hands personal monitor control to the performers, freeing the engineer to concentrate on the front-of-house mix. Allen & Heath owns the SQ4You name.", "practical_application": "Each member of a band opens SQ4You on their phone to set their own in-ear monitor mix during soundcheck.", "category": "Personal monitor app", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SQ", "Qu-You", "dLive OneMix", "SQ MixPad", "Monitor mix"], "common_mistakes": ["Confusing SQ4You (single-performer monitors) with SQ MixPad (full engineer control)", "Expecting the app to stream audio to the device; it only sends control data", "Assuming unlimited connections; the number of simultaneous SQ4You and MixPad sessions is limited"], "scenario_contexts": ["A band on in-ear monitors each mixing their own ears", "A worship team managing personal monitors on tablets", "Musicians tweaking their own wedge mixes during a busy soundcheck"], "formula_symbolic": "", "formula_words": ""}, {"id": "9c32d0c4-b316-4353-9465-7f1c0842b021", "term": "SuperStrip", "definition": "SuperStrip is Allen & Heath's name for a dedicated single-function channel-strip control section, found on its Qu series (and earlier GLD) consoles. It is a row of physical controls, one per function, that always act on the currently selected channel: preamp gain, high-pass filter, gate, 4-band parametric EQ, compressor, graphic EQ and pan. It gives hands-on processing without menu diving.", "plain_english": "SuperStrip is a set of real knobs on Allen & Heath Qu mixers. Each knob does one job, like gain, EQ or compression. You pick a channel, then shape it with your hands. You do not have to dig through menus.", "purpose_function": "It speeds up channel processing by giving one physical control per function for the selected channel. Allen & Heath owns the SuperStrip name; the underlying method is a dedicated single-knob-per-function channel strip, a long-standing console design idea.", "practical_application": "During a busy soundcheck, an engineer selects a vocal channel and reaches straight for the SuperStrip gate and compressor knobs instead of tapping through the touchscreen.", "category": "Control feature", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Qu", "Qu-Drive", "SQ", "Parametric EQ", "Compressor"], "common_mistakes": ["Assuming the SQ series has a SuperStrip; the SQ uses a touchscreen with assignable encoders instead", "Thinking the controls affect all channels at once; they only act on the selected channel", "Overlooking that the strip follows channel selection, so its settings change when you pick a different channel"], "scenario_contexts": ["Quickly gating and compressing a drum channel during a live set", "Dialling high-pass and EQ on a vocal channel by feel during a show", "Teaching a trainee channel processing using physical, labelled controls"], "formula_symbolic": "", "formula_words": ""}, {"id": "67512cb7-2a9f-4597-a278-0bc2f6471905", "term": "dLive", "definition": "dLive is Allen & Heath's flagship digital mixing system, built as a separated two-box architecture: a MixRack DSP engine and a control Surface, linked over the gigaACE protocol. It runs on the 96 kHz XCVI FPGA core with 128 input channels, 64 mix outputs, a configurable 64-bus design and 0.7 ms analogue-to-analogue latency.", "plain_english": "dLive is Allen & Heath's top digital mixing system. It comes in two parts. One box does the audio processing and sits near the stage. The other is the control surface the engineer touches. A single cable links them.", "purpose_function": "Splitting the system into a processing rack and a control surface lets the engine sit near the stage while the operator mixes from anywhere, cutting long analogue cable runs. Allen & Heath owns the dLive name.", "practical_application": "A touring engineer places a dLive MixRack backstage near the stage boxes and controls it from a dLive Surface at front of house over one cable.", "category": "Digital mixing system", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["dLive MixRack", "dLive Surface", "dLive Director", "dLive MixPad", "SQ"], "common_mistakes": ["Thinking dLive is a single console; it is a MixRack engine plus a separate control Surface", "Assuming the Surface does the audio processing; the MixRack holds the DSP core", "Confusing dLive (the flagship system) with the smaller SQ or Qu consoles"], "scenario_contexts": ["Large touring productions and festivals", "Broadcast and theatre installs needing high channel counts", "Front-of-house and monitor mixing from separate surfaces on one MixRack"], "formula_symbolic": "", "formula_words": ""}, {"id": "ec4fdfbb-22e1-49b1-8263-8583b82db45a", "term": "dLive Director", "definition": "dLive Director is Allen & Heath's free editor and remote-control software for the dLive system, running on macOS and Windows. It provides full online control of a networked dLive system and an offline mode to build and edit shows on a computer away from the hardware.", "plain_english": "dLive Director is free software for Allen & Heath dLive systems. It runs on a Mac or Windows computer. Online, it controls a live dLive system over a network. Offline, it lets you build and edit a show before the gig.", "purpose_function": "It lets engineers control a dLive system from a laptop and prepare complete shows offline, and it can even run a system with no physical surface. Allen & Heath owns the dLive Director name.", "practical_application": "An engineer builds and names all channels and scenes in dLive Director at home, then loads that show onto the console at the venue.", "category": "Remote control app", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["dLive", "dLive MixRack", "dLive MixPad", "dLive Surface", "dLive OneMix"], "common_mistakes": ["Assuming Director needs the hardware connected; its offline mode works on the computer alone", "Confusing dLive Director (full computer editor/control) with dLive MixPad (iPad control)", "Forgetting the computer must be on the same network as the MixRack for online control"], "scenario_contexts": ["Programming a full show offline before load-in", "Controlling a surfaceless MixRack from a laptop", "Editing channel names, patching and scenes on a computer during prep"], "formula_symbolic": "", "formula_words": ""}, {"id": "327b56a3-1fae-4523-8c6b-047ac387264c", "term": "dLive MixPad", "definition": "dLive MixPad is Allen & Heath's iPad control app for the dLive system. It gives an engineer wireless control of the dLive mix over a Wi-Fi network, so they can mix from anywhere in the venue, including running a MixRack with no physical surface.", "plain_english": "dLive MixPad is an iPad app for Allen & Heath dLive systems. It lets the engineer mix over Wi-Fi from anywhere in the room. It can even run the system when no control desk is present.", "purpose_function": "It frees the engineer from the mix position and can control a surfaceless MixRack directly. Allen & Heath owns the dLive MixPad name.", "practical_application": "An engineer walks the room with an iPad running dLive MixPad to check coverage and set monitor mixes from the stage.", "category": "Remote control app", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["dLive", "dLive MixRack", "dLive Director", "dLive OneMix", "SQ MixPad"], "common_mistakes": ["Confusing dLive MixPad (full engineer control) with dLive OneMix (single-performer monitors)", "Assuming it replaces the MixRack; it only controls the engine, which still does the processing", "Forgetting the iPad and MixRack must share the same Wi-Fi network"], "scenario_contexts": ["Mixing front-of-house from within the audience on an iPad", "Setting monitor mixes while standing on stage", "Operating a compact surfaceless dLive rig from a tablet"], "formula_symbolic": "", "formula_words": ""}, {"id": "80e4b53b-39dd-4133-b0fc-399cb5f7e58a", "term": "dLive MixRack", "definition": "The dLive MixRack is the DSP engine of a dLive system: the unit that holds the 96 kHz XCVI processing core and local audio I/O and performs all mixing and processing. It links to one or more control Surfaces over gigaACE, or can run 'surfaceless', controlled only by software such as dLive Director or MixPad. Models include the S-Class DM0/DM32/DM48/DM64 and C-Class CDM32/CDM48/CDM64.", "plain_english": "The MixRack is the brain of an Allen & Heath dLive system. It does all the audio work and holds the inputs and outputs. It usually sits near the stage. A control surface or an app tells it what to do.", "purpose_function": "It separates the audio processing and I/O from the control surface, so the engine can live near the stage while the operator mixes elsewhere. Allen & Heath owns the name; the method is a separated DSP-engine plus remote control-surface architecture.", "practical_application": "A technician racks a dLive MixRack backstage close to the stage boxes, then runs a single gigaACE cable to the control Surface at front of house.", "category": "DSP engine", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["dLive", "dLive Surface", "dLive Director", "dLive MixPad", "gigaACE"], "common_mistakes": ["Thinking the control Surface does the processing; the MixRack holds the DSP core", "Assuming a MixRack always needs a Surface; it can run surfaceless from software", "Confusing S-Class and C-Class MixRacks, which differ in I/O, redundancy and surface support"], "scenario_contexts": ["Placing the processing engine near the stage to shorten cable runs", "Running a surfaceless install controlled only by Director software", "Sharing one MixRack between front-of-house and monitor surfaces"], "formula_symbolic": "", "formula_words": ""}, {"id": "65ff9787-2ec8-4f89-8b0a-ec05a75ea698", "term": "dLive OneMix", "definition": "dLive OneMix is Allen & Heath's personal monitor mixing app for the dLive system. It locks a performer to a single monitor (aux) mix on an iPad, so each musician can adjust their own monitor over Wi-Fi without affecting other mixes or the main output.", "plain_english": "dLive OneMix is an iPad app for Allen & Heath dLive systems. It gives one musician control of just their own monitor mix. They can adjust what they hear on stage. They cannot change anyone else's sound or the main mix.", "purpose_function": "It safely hands one performer control of their own monitor mix, freeing the engineer while preventing changes to other mixes. Allen & Heath owns the OneMix name.", "practical_application": "A singer uses dLive OneMix on an iPad to raise their own vocal and lower the guitar in their in-ear mix during the show.", "category": "Personal monitor app", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["dLive", "Qu-You", "SQ4You", "dLive MixPad", "Monitor mix"], "common_mistakes": ["Confusing dLive OneMix (one performer, one mix) with dLive MixPad (full engineer control)", "Expecting to control more than one mix; OneMix locks to a single aux mix", "Assuming it can affect the main output; it is restricted to the performer's own monitor"], "scenario_contexts": ["A vocalist mixing their own in-ear monitor on stage", "Each band member locked to their own monitor on separate iPads", "A house of worship giving musicians safe control of only their own mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "31578de8-bf41-4c74-b12f-f916c07e753f", "term": "dLive Surface", "definition": "A dLive Surface is the physical control interface of a dLive system: the console with faders, touchscreens and assignable encoders that an operator uses to control the separate MixRack DSP engine. It connects to the MixRack over gigaACE. Models include the S-Class S3000/S5000/S7000 and C-Class C1500/C2500/C3500, and up to four Surfaces can control one MixRack.", "plain_english": "The Surface is the control desk of an Allen & Heath dLive system. It has the faders, screens and knobs the engineer touches. It does not process the audio itself. It sends commands to the MixRack over one cable.", "purpose_function": "It gives the operator hands-on control while the MixRack does the processing, letting the desk sit far from the stage. Allen & Heath owns the name; the method is a control surface separated from the DSP engine.", "practical_application": "An engineer mixes a show from a dLive S5000 Surface at front of house while the MixRack it controls stays backstage.", "category": "Control surface", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["dLive", "dLive MixRack", "dLive Director", "dLive MixPad", "gigaACE"], "common_mistakes": ["Thinking the Surface processes the audio; the MixRack holds the DSP core", "Assuming one MixRack takes only one Surface; up to four Surfaces can share it", "Confusing S-Class and C-Class Surfaces, which differ in faders, screens and redundancy"], "scenario_contexts": ["Front-of-house mixing from a control desk far from the stage", "A second Surface used for monitors on the same MixRack", "Choosing a compact C-Class Surface for a theatre or corporate AV install"], "formula_symbolic": "", "formula_words": ""}, {"id": "39217262-b07e-4b75-a9ff-dcad591f4cf9", "term": "Complete Channel", "definition": "On Allen & Heath CQ series digital mixers, a Complete Channel is an input-channel processing mode that exposes the full set of channel processing blocks — high-pass filter, gate, parametric EQ, compressor and delay — as individually adjustable parameters. It is the deeper counterpart to the CQ 'Quick Channel' mode, which controls a whole channel of processing through simplified controls; a channel can be converted between the two at any time with no change to the audio. Complete Channel is a feature of mixers made by Allen & Heath.", "plain_english": "A CQ mixer channel can run in two modes. Complete Channel is the full, detailed mode. It shows every processing tool on the channel, like the EQ, gate and compressor. You get all of their controls to adjust. You pick this mode when you want to fine-tune a sound. Allen & Heath makes these mixers.", "purpose_function": "It exists to give the engineer full, granular control over every processing parameter on an input channel, for situations where the simplified Quick Channel controls are not detailed enough.", "practical_application": "An engineer switches a vocal or instrument input to Complete Channel during soundcheck to adjust individual EQ bands, compressor threshold and gate settings precisely.", "category": "Channel Processing", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["Quick Channel", "Parametric EQ", "Gate (Noise Gate)", "Compressor", "High-Pass Filter", "Channel Strip"], "common_mistakes": ["Assuming converting between Quick Channel and Complete Channel changes or interrupts the audio; the conversion is seamless.", "Thinking Complete Channel adds extra processing blocks; it exposes the same channel processing in full detail rather than adding new tools.", "Reaching for Complete Channel's full parameter set when a fast Quick Channel adjustment would handle a simple source."], "scenario_contexts": ["Fine-tuning a lead vocal's EQ and compression during a soundcheck on a CQ mixer.", "Converting a Quick Channel to a Complete Channel to dial in a gate on a noisy guitar amp mic.", "Setting a precise high-pass filter and parametric EQ on a kick drum channel."], "formula_symbolic": "", "formula_words": ""}, {"id": "452ce132-f571-409d-9ce9-c35f3bff7a30", "term": "DCA Spill", "definition": "DCA Spill is a workflow feature on Allen & Heath digital mixers that temporarily lays out the individual member channels of a DCA (Digitally Controlled Amplifier) group across the physical fader strips when that DCA is selected, overriding the current fader layout. A DCA controls the level and mute of many assigned channels from one master fader without carrying or summing their audio, so spilling reveals those members for direct individual control; member order and layout are configurable. The feature is implemented on mixers made by Allen & Heath, and 'spill' is a general console-workflow concept used by several manufacturers.", "plain_english": "A DCA is one fader that controls the volume of a whole group of channels. DCA stands for Digitally Controlled Amplifier. Spilling that DCA spreads its member channels out across the mixer's faders. Now you can grab and adjust each channel on its own. Then you can go back to the group fader. Allen & Heath mixers offer this.", "purpose_function": "It lets an engineer jump from controlling a group as a whole to adjusting its individual members instantly, without navigating to a different fader layer or bank.", "practical_application": "An engineer presses a 'Drums' DCA to spill kick, snare, toms and overheads onto the faders, tweaks one drum, then exits the spill back to the normal layout.", "category": "DCA & Grouping", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["DCA (Digitally Controlled Amplifier)", "Mute Group", "Fader Layer", "Custom Layer", "Audio Group"], "common_mistakes": ["Confusing a DCA with an audio group or subgroup; a DCA controls level and mute only and carries no audio.", "Expecting a DCA fader to have its own processing or metering of a summed signal; it has neither.", "Forgetting to exit the spill and then editing the wrong bank of channels."], "scenario_contexts": ["Spilling a 'Vocals' DCA to rebalance individual singers mid-show.", "Quickly accessing all drum channels from one DCA during a live set.", "Adjusting a single band member's channel without leaving the group view."], "formula_symbolic": "", "formula_words": ""}, {"id": "9b49790a-11e7-4b99-8c47-d3e354513a29", "term": "FX Assist", "definition": "FX Assist is an Allen & Heath CQ series feature that automatically shapes an effect (FX) and dynamically responds to the input signal so the effect supports the mix rather than overwhelming it. It is one of the CQ 'assistant' tools aimed at speeding up mixing for less experienced users and is available on selected CQ units. FX Assist is a feature of mixers made by Allen & Heath.", "plain_english": "FX Assist is a helper on Allen & Heath CQ mixers. It sets up an effect, like reverb, for you. It also adjusts the effect as your input signal changes. The goal is to stop the effect from burying the mix. This helps beginners get a good sound fast.", "purpose_function": "It exists to make effects easier to use for non-expert operators by automatically tuning the effect and reacting to the incoming audio in real time.", "practical_application": "A musician mixing their own band enables FX Assist on a vocal reverb so the effect pulls back during loud passages and sits well without manual tweaking.", "category": "Mix Assistant", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["Gain Assistant", "Feedback Assistant", "Quick Channel", "Reverb", "Effects (FX)"], "common_mistakes": ["Assuming FX Assist is available on every CQ mixer; it is offered on selected units.", "Expecting it to replace all manual FX control; it shapes and adapts the effect but the engineer still chooses the effect and its level.", "Thinking it changes the dry signal; it acts on the effect (wet) processing."], "scenario_contexts": ["A solo performer setting vocal reverb quickly with FX Assist.", "Keeping a delay effect from cluttering a busy mix automatically.", "A house-of-worship volunteer using FX Assist to manage effects during a service."], "formula_symbolic": "", "formula_words": ""}, {"id": "4413374f-3152-4e6e-9d41-527000662609", "term": "Feedback Assistant", "definition": "Feedback Assistant is an Allen & Heath feature that automatically detects prominent, persistent frequencies caused by acoustic feedback on a mix output and applies narrow notch filters to reduce them while minimising overall tonal change. On CQ mixers it offers up to 16 filters per output and can run in a fixed mode (filters stay in place) or a live mode (filters self-recover), typically working alongside a real-time analyser (RTA) display. Feedback Assistant is a feature of mixers made by Allen & Heath; automatic feedback suppression using notch filters is a general audio technique.", "plain_english": "Feedback is that loud squeal when a microphone picks up its own speaker. Feedback Assistant is an Allen & Heath tool that hunts down those squealing frequencies. It then adds narrow filters to cut just those tones. The rest of the sound stays about the same. It can hold the filters or let them reset during the show.", "purpose_function": "It exists to detect and control feedback quickly, especially on monitor and PA outputs, so an operator can set levels with less risk of ringing.", "practical_application": "During soundcheck an engineer enables Feedback Assistant on a monitor mix, slowly raises the level until it starts to ring, and lets the tool notch out the offending frequencies.", "category": "Mix Assistant", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["GEQ on Faders", "Parametric EQ", "Notch Filter", "RTA (Real-Time Analyser)", "Monitor Mix", "Gain Assistant"], "common_mistakes": ["UNSAFE: Relying on feedback suppression to justify pushing monitor or PA levels dangerously high; excessive levels risk hearing damage and can still feed back.", "Leaving live-mode filters to accumulate over time so the sound becomes dull.", "Assuming it removes all feedback risk; poor mic technique and bad gain structure still cause feedback.", "Confusing narrow feedback notches with broad tone shaping."], "scenario_contexts": ["Ringing out floor wedge monitors before a band takes the stage.", "Controlling feedback on a lectern microphone in a reverberant room.", "Keeping a lavalier mic stable during a live presentation."], "formula_symbolic": "", "formula_words": ""}, {"id": "cee2d6b6-c06d-4642-b970-81fe6c0a9986", "term": "GEQ on Faders", "definition": "GEQ on Faders is a workflow mode on Allen & Heath mixers that maps the bands of a graphic equaliser (GEQ) onto the physical channel faders, so each fader boosts or cuts one fixed frequency band (typically one-third-octave ISO bands across roughly 28–31 bands). Pressing the GEQ 'fader flip' key shows the graphic EQ for the selected mix on the faders, often with a real-time analyser (RTA) shown above each fader. A graphic equaliser with fixed bands and slider-style controls is a standard audio tool; presenting it on motorised faders is implemented on mixers made by Allen & Heath.", "plain_english": "A graphic EQ splits sound into many fixed frequency bands. Each band can be turned up or down. GEQ on Faders puts those bands onto the mixer's real faders. So each fader now controls one frequency. It feels like using an old-style graphic EQ slider. Allen & Heath mixers offer this fader-flip view.", "purpose_function": "It gives fast, tactile, hands-on control of many EQ bands at once, which is quicker than adjusting a graphic EQ on a touchscreen.", "practical_application": "An engineer flips the GEQ for a monitor mix onto the faders and pulls down the fader for a ringing frequency shown on the RTA.", "category": "Equalisation", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["Graphic EQ", "Parametric EQ", "RTA (Real-Time Analyser)", "Feedback Assistant", "Fader Layer", "Monitor Mix"], "common_mistakes": ["Forgetting the faders are temporarily controlling EQ bands, not channel levels, and changing the wrong thing.", "Cutting too many adjacent bands and dulling the overall tone.", "Assuming each fader is a fully sweepable parametric band; graphic EQ bands sit at fixed frequencies."], "scenario_contexts": ["Ringing out monitors by pulling down feedback-prone frequency bands.", "Shaping the tone of a main PA mix quickly during a show.", "Using the RTA-on-faders view to spot and cut a room resonance."], "formula_symbolic": "", "formula_words": ""}, {"id": "750b4482-2899-4920-9434-0d6fe5aafc59", "term": "Gain Assistant", "definition": "Gain Assistant is an Allen & Heath CQ series feature that automatically sets a suitable preamp gain for one or more input channels and can then continuously monitor the input, reducing gain in the background if a source becomes louder than it was at soundcheck. The engineer produces signal from the source — for example by singing or playing into the mic — and the system raises gain to an optimum level; an Auto Gain option keeps watching to prevent unexpected peaks. Gain Assistant is a feature of mixers made by Allen & Heath.", "plain_english": "Setting the right input gain for each mic can be fiddly. Gain Assistant does it for you on Allen & Heath CQ mixers. You make sound into the mic and it finds a good gain level. It can also keep watching during the show. If a singer gets much louder, it eases the gain down. This helps avoid sudden overloads.", "purpose_function": "It speeds up and de-skills gain setting and helps protect against clipping when sources get unexpectedly loud during a performance.", "practical_application": "An operator selects several channels, presses Auto Set while performers play or talk, then enables Auto Gain to guard against peaks during the show.", "category": "Mix Assistant", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["Preamp Gain", "Gain Structure", "Headroom", "Clipping", "Quick Channel", "Feedback Assistant"], "common_mistakes": ["Running Gain Assistant with no signal present, so it cannot measure a real level.", "Assuming automatic gain removes the need to understand gain structure and headroom.", "Expecting it to fix a source that is far too quiet or far too loud at the physical connection.", "Forgetting Auto Gain can lower gain, which may surprise an operator watching the meters."], "scenario_contexts": ["Quickly gain-staging a full band at soundcheck on a CQ mixer.", "Protecting a dynamic vocalist's channel from clipping during a loud chorus.", "A volunteer setting mic gains for a worship service without deep audio experience."], "formula_symbolic": "", "formula_words": ""}, {"id": "48c0e903-f781-4c64-9511-9140f83b3666", "term": "Global Recall Filter", "definition": "A Global Recall Filter (called a Global Filter on Allen & Heath mixers) blocks selected parameters or channel-processing categories from being changed by ANY scene recall, applied across the whole show rather than to a single scene. It is always active and takes precedence over per-scene recall filters, so blocked items are simply left untouched when scenes are recalled. On Allen & Heath consoles it is set per show in the Scenes / Global Filter screen. It is a feature of mixers made by Allen & Heath; global recall filtering of snapshots is a general digital-console concept.", "plain_english": "A scene is a saved snapshot of the whole mixer. Recalling a scene changes many settings at once. A Global Recall Filter protects chosen settings from every scene recall. Those settings stay as they are, no matter which scene you load. It works across the whole show. Allen & Heath calls it the Global Filter.", "purpose_function": "It lets an engineer keep certain settings constant across an entire show while still using scenes to change everything else, without editing every individual scene.", "practical_application": "A monitor engineer globally filters input gains so recalling song scenes never overwrites the preamp gains set at soundcheck.", "category": "Scene Management", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["Scene", "Scene Filter", "Global Safes", "Recall Filter", "Show"], "common_mistakes": ["Confusing the Global Filter with per-scene recall filters; the global one applies to every scene and overrides them.", "Confusing filtering a parameter with 'safeing' a whole channel; a filter targets chosen parameters globally, a safe locks a whole channel.", "Forgetting a global block is active and wondering why a scene will not change that setting."], "scenario_contexts": ["Keeping preamp gains fixed across all scenes in a multi-band show.", "Protecting system output EQ from being altered by song scenes.", "Ensuring monitor sends stay put while front-of-house recalls scenes."], "formula_symbolic": "", "formula_words": ""}, {"id": "5c190bbf-2e27-4e21-81df-0c458736e4ba", "term": "Global Safes", "definition": "Global Safes (Global Scene Safes) are protective settings on Allen & Heath mixers that prevent selected channels or parameters from being overwritten by ANY scene recall, unlike a per-scene recall filter which affects only its own scene. Safed items are excluded from every scene recall until the safe is removed, and on the surface they are typically toggled in a matrix and highlighted. Global Safes are a feature of mixers made by Allen & Heath.", "plain_english": "Scenes reload lots of mixer settings at once. A Global Safe protects a channel or setting from all scene recalls. That safed channel keeps its current settings no matter what scene you load. You turn safes on and off in a simple grid. Allen & Heath mixers include this.", "purpose_function": "It lets an engineer lock important channels or settings so scene changes during a show cannot disturb them.", "practical_application": "An engineer safes the lead vocal channel so recalling scenes between songs never resets its level or processing.", "category": "Scene Management", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["Scene", "Global Recall Filter", "Scene Filter", "Recall Filter", "Channel Strip"], "common_mistakes": ["Confusing a Global Safe with a per-scene recall filter; safes are global while a recall filter only affects its own scene.", "Leaving a channel safed and then being unable to recall wanted changes to it.", "Assuming safeing a channel also blocks manual changes; it only blocks scene recalls."], "scenario_contexts": ["Safeing a guest speaker's mic so scene recalls do not mute or re-level it.", "Protecting the whole output/PA processing from scene changes.", "Keeping an emergency announcement channel constant across a show."], "formula_symbolic": "", "formula_words": ""}, {"id": "22122ff3-e52c-4da3-ba38-f2854136be10", "term": "PAFL", "definition": "PAFL stands for Pre-Fade Listen / After-Fade Listen, a monitoring (solo) system on Allen & Heath mixers that routes a selected channel or bus to a dedicated PAFL bus and the headphone/monitor output for auditioning without affecting the main mix. Pre-Fade Listen taps the signal before the channel fader (so the source is heard at any fader position), while After-Fade Listen taps after the fader and follows the fader level (and usually pan). PAFL is Allen & Heath terminology for the general PFL/AFL solo-monitoring concept used across the industry.", "plain_english": "PAFL lets you listen to one channel on your headphones without changing the main mix. It means Pre-Fade Listen and After-Fade Listen. Pre-fade listens before the volume fader, so you hear the source even if its fader is down. After-fade listens after the fader, so it follows the fader level. Engineers use it to check or troubleshoot a single input.", "purpose_function": "It exists so an engineer can privately audition, check or troubleshoot any single channel or mix without disturbing what the audience hears.", "practical_application": "An engineer presses PAFL on a suspect microphone channel to hear it alone in the headphones and confirm it is working before bringing it into the mix.", "category": "Monitoring", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["PFL (Pre-Fade Listen)", "AFL (After-Fade Listen)", "Solo", "Headphone Output", "Cue Bus", "Fader"], "common_mistakes": ["Confusing pre-fade with after-fade listen; pre-fade ignores the fader position while after-fade follows it.", "Leaving a PAFL engaged and mistaking the headphone/monitor feed for the main mix.", "Assuming PAFL changes the front-of-house mix; it only affects the monitoring/headphone bus."], "scenario_contexts": ["Checking a quiet or dead microphone by soloing it in the headphones.", "Auditioning a source before unmuting it into the main mix.", "Using pre-fade listen to set input gain from the PAFL meter."], "formula_symbolic": "", "formula_words": ""}, {"id": "d4861086-8863-4460-ba21-324443223c7d", "term": "Quick Channel", "definition": "On Allen & Heath CQ series mixers, a Quick Channel is an instrument- or source-centric whole-channel preset that lets the user mix quickly by adjusting multiple processing parameters through a few simplified controls (for example a single knob that controls a full channel of processing). It is the simplified counterpart to the CQ 'Complete Channel' mode, and a channel can be converted between the two at any time with no change to the audio. Quick Channel is a feature of mixers made by Allen & Heath.", "plain_english": "A Quick Channel is a simple way to set up a mixer input on Allen & Heath CQ mixers. It uses ready-made presets for common sources, like vocals or guitar. A few easy controls adjust a whole channel of processing at once. It helps you mix fast without deep menus. You can switch to the detailed Complete Channel mode any time.", "purpose_function": "It exists to make mixing fast and approachable for non-experts by hiding detailed parameters behind a few source-appropriate controls.", "practical_application": "A performer picks a 'vocal' Quick Channel preset for their mic and uses its simplified controls to shape the sound in seconds.", "category": "Channel Processing", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["Complete Channel", "Channel Preset", "Parametric EQ", "Compressor", "Channel Strip"], "common_mistakes": ["Assuming switching between Quick Channel and Complete Channel interrupts or alters the audio; it is seamless.", "Expecting full per-parameter control in Quick Channel; use Complete Channel for that.", "Choosing a preset that does not match the actual source type."], "scenario_contexts": ["A musician self-mixing their vocal quickly on a CQ mixer.", "Setting up a rehearsal PA fast with source presets.", "A volunteer operator handling a multi-input service with simple controls."], "formula_symbolic": "", "formula_words": ""}, {"id": "9fd528a3-d82a-47b3-997f-df7757477b15", "term": "Scene Filter", "definition": "A Scene Filter (Scene Recall Filter) on Allen & Heath mixers determines which channels or parameters a particular scene will change when it is recalled: blocked items are left untouched by that scene, while allowed items are recalled. Unlike a Global Filter, a scene's recall filter affects only the scene it is associated with, and it is set per scene in the Scene Manager. Scene Filter is a feature of mixers made by Allen & Heath; scene/snapshot recall filtering is a general digital-console concept.", "plain_english": "A scene is a saved snapshot of mixer settings. A Scene Filter decides which of those settings a scene will actually load. Blocked settings are left alone when you recall that scene. This filter only affects its own scene, not the others. Allen & Heath mixers let you set it per scene.", "purpose_function": "It lets an engineer make a scene change only some settings (for example mutes and levels) while leaving others as they are, giving precise control over what each scene does.", "practical_application": "An engineer sets a song scene to recall only fader levels and mutes, filtering out EQ so their live tweaks survive the scene change.", "category": "Scene Management", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["Scene", "Global Recall Filter", "Global Safes", "Recall Filter", "Show"], "common_mistakes": ["Confusing a per-scene filter with the global filter; the scene filter affects only its own scene.", "Blocking parameters in a scene and then wondering why the scene does not change them.", "Assuming a scene filter protects a channel from all scenes; only Global Safes or the Global Filter do that."], "scenario_contexts": ["Making a scene recall only mutes for a quick set change.", "Filtering out preamp gain so a scene does not overwrite soundcheck gains.", "Building scenes that change routing but keep processing untouched."], "formula_symbolic": "", "formula_words": ""}, {"id": "84d1a363-82a4-4e9f-bc7e-1136e3cef5ba", "term": "Socket-to-Channel Patch", "definition": "A Socket-to-Channel Patch on Allen & Heath mixers is an assignment in the I/O patchbay that routes a physical input socket (for example a local XLR input, an SLink/networked stage-box input or a USB input) to an internal mixer input channel for processing and mixing. It is typically made on a matrix/grid by touching the cross-point between a source socket and a destination channel, or from the channel's preamp source selector, and factory presets provide one-to-one patching. Flexible socket-to-channel patching is a feature of mixers made by Allen & Heath and a general digital-mixing concept.", "plain_english": "A mixer has physical input jacks called sockets. It also has channels inside where you mix and process sound. A socket-to-channel patch connects one physical socket to one channel. You usually do this on a grid by tapping where a socket meets a channel. This is how a stage mic reaches the channel you mix it on.", "purpose_function": "It exists so any physical input can be freely routed to any mixer channel, separating the stage wiring from the channel layout the engineer wants.", "practical_application": "An engineer patches stage-box socket 5 (a vocal mic) to input channel 1 so it appears on the fader where they want to mix it.", "category": "I/O & Patching", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["I/O Patchbay", "Preamp", "Stage Box (SLink)", "Input Channel", "Direct Out"], "common_mistakes": ["Assuming the physical socket number always equals the channel number; patching can route any socket to any channel.", "Forgetting that on many systems the preamp gain is shared by every channel patched from the same socket.", "Patching the wrong cross-point and then searching for a 'dead' channel that is simply unpatched."], "scenario_contexts": ["Mapping a digital stage box's inputs to the desired mixer channels at load-in.", "Re-patching a spare mic input to a working channel when one fails.", "Routing a USB playback input to a channel for virtual soundcheck."], "formula_symbolic": "", "formula_words": ""}, {"id": "884d3eea-fd08-4a40-ad11-af1db4d99723", "term": "User Role", "definition": "A User Role (User Profile) on Allen & Heath mixers is a login-based permission level that controls which functions and settings a given operator may access or change. An Admin profile has access to all functions and can set the permissions and passwords for other, restricted user profiles; restricted users are limited to the functions the admin allows, and a user can be given a scene to recall automatically at login. Multiple user profiles are supported. User Roles/Profiles are a feature of mixers made by Allen & Heath.", "plain_english": "A User Role sets what a person is allowed to do on the mixer. The Admin role can use everything and set the rules for others. Restricted users can only touch the functions the admin allows. Passwords can protect each login. This stops guests or volunteers from changing critical settings.", "purpose_function": "It exists to protect a show and equipment by limiting less-experienced or guest operators to safe functions while giving a lead engineer full control.", "practical_application": "A head engineer creates a restricted profile for a volunteer that only allows fader and mute changes, and keeps system setup locked under the admin password.", "category": "System Setup", "difficulty": "intermediate", "achievement_id": "102f3c40-ed0a-4712-9c96-9fbaac465a03", "cross": [], "related_terms": ["Admin", "Password", "Global Safes", "Scene", "Custom Layer"], "common_mistakes": ["Setting an admin password and then losing it, which can lock out full access.", "Giving a guest operator admin rights, so they can change critical system settings by mistake.", "Assuming user roles protect scene data; they control access, while Safes and Filters protect recalls."], "scenario_contexts": ["Limiting a house-of-worship volunteer to basic mixing functions.", "Locking down system and I/O setup at a rental venue for visiting engineers.", "Giving a support-act engineer a restricted profile at a festival."], "formula_symbolic": "", "formula_words": ""}, {"id": "9e1da738-05c6-4b7a-98e5-20f71f174817", "term": "DEEP Processing", "definition": "DEEP Processing is Allen & Heath's proprietary in-channel processing technology. It embeds detailed emulations of classic outboard hardware types, such as compressors, preamps, expanders and EQs, directly within a console's input and mix channels, running inside the XCVI FPGA core. The models add effectively zero extra latency and use none of the console's separate RackExtra FX slots. The DEEP name and models are proprietary to Allen & Heath, while the underlying idea, in-channel DSP emulation of analogue processors, is a generic digital-mixer technique.", "plain_english": "DEEP Processing is Allen and Heath's own way of building studio-style effects into each channel. It copies the sound of classic gear like compressors and preamps. These copies run inside the mixer's main processing chip. They do not use up the mixer's separate effects slots. They also add no noticeable delay.", "purpose_function": "It gives every channel high-quality emulations of favourite outboard processors without tying up shared effects units or adding latency. This lets engineers process many channels at once with a consistent, analogue-style character.", "practical_application": "A live engineer inserts a DEEP compressor model on a vocal channel to get an analogue-style sound. All RackExtra FX slots then stay free for reverbs and delays.", "category": "Onboard Processing", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["DEEP Processor", "XCVI", "RackExtra FX", "Dyn8", "RackUltra FX", "dPack"], "common_mistakes": ["Thinking DEEP models use up RackExtra FX slots; they run embedded in the channel strip and do not.", "Assuming DEEP emulations are the exact licensed products, when they are Allen & Heath's own models of those hardware types.", "Believing DEEP adds latency like an external insert; it runs in the FPGA core with effectively zero added latency."], "scenario_contexts": ["Placing a DEEP valve preamp model on a lead vocal for warmth during a live show.", "Using DEEP compressor and expander models across a drum kit while saving FX slots for effects.", "Comparing standard DEEP channel processing on Avantis with the fuller model set unlocked by dPack."], "formula_symbolic": "", "formula_words": ""}, {"id": "651a477a-aced-48fc-a8aa-d050e7854eda", "term": "DEEP Processor", "definition": "A DEEP Processor is a single Allen & Heath DEEP model, for example a specific compressor, preamp, expander or EQ emulation, placed on a channel. Each DEEP Processor runs embedded in the console's XCVI core within the channel's processing chain, adding no significant latency and using no external FX slot. The term names an individual instance of Allen & Heath's proprietary DEEP Processing technology.", "plain_english": "A DEEP Processor is one of Allen and Heath's built-in effect models. You place it on a channel, like a compressor or a preamp. It sounds like classic studio gear. It runs inside the mixer, so it adds no real delay. It does not use the separate effects slots.", "purpose_function": "It lets an engineer add one specific analogue-style processor to a channel from within the console. There is no need to patch external hardware or spend a shared FX slot.", "practical_application": "An engineer selects a DEEP Processor, such as a specific compressor model, in a channel's dynamics section. They use it to shape a snare or a vocal without external gear.", "category": "Onboard Processing", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["DEEP Processing", "XCVI", "Dyn8", "RackExtra FX", "dPack", "Avantis"], "common_mistakes": ["Confusing one DEEP Processor with DEEP Processing, which is the whole embedded-model system.", "Thinking a DEEP Processor consumes a RackExtra FX slot; it lives in the channel strip.", "Assuming a DEEP Processor is the original licensed hardware rather than an Allen & Heath emulation of that type."], "scenario_contexts": ["Inserting a DEEP compressor model on a bass guitar channel during soundcheck.", "Adding a DEEP valve preamp model to warm up a DI'd acoustic guitar.", "Choosing between different DEEP dynamics models to find the right vocal sound."], "formula_symbolic": "", "formula_words": ""}, {"id": "37757c88-39d1-4b59-aa3a-5140cfa9d611", "term": "RackUltra FX", "definition": "RackUltra FX is Allen & Heath's high-end effects processing system, delivered by a dedicated RackUltra FX hardware module (combining FPGA and ARM processing) and its algorithm suite. On Avantis it adds eight stereo RackUltra FX engines, running vocal, reverb, delay, harmoniser, saturation and distortion algorithms, that operate independently of the console's twelve RackExtra FX units and without consuming channels or buses. The name is proprietary to Allen & Heath, while the underlying method, dedicated add-on effects DSP engines, is a generic mixer concept.", "plain_english": "RackUltra FX is Allen and Heath's top-tier effects system. It runs advanced effects like reverbs, delays and vocal tools. On Avantis it adds eight extra stereo effects engines. These are separate from the standard twelve RackExtra effects. It does not use up any channels or buses.", "purpose_function": "It expands a console's effects power with more advanced, plug-in-style algorithms. Engineers gain extra effects engines on top of the standard FX rack for demanding mixes.", "practical_application": "A front-of-house engineer routes lead vocals through a RackUltra FX tuner or reverb. The twelve RackExtra FX units then stay free for the rest of the mix.", "category": "FX Processing", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["RackExtra FX", "DEEP Processing", "XCVI", "dPack", "Avantis", "dLive"], "common_mistakes": ["Confusing RackUltra FX with RackExtra FX; RackUltra is the newer, higher-end additional engine set.", "Assuming RackUltra FX engines use up mix buses or channels, when they run on a separate signal path.", "On Avantis, forgetting that RackUltra FX needs a dPack-enabled system plus the RackUltra FX module."], "scenario_contexts": ["Applying a RackUltra FX harmoniser to backing vocals at a concert.", "Using the RackUltra FX reverb designer for a lush lead-vocal reverb.", "Adding RackUltra FX engines to a busy mix without giving up any RackExtra FX slots."], "formula_symbolic": "", "formula_words": ""}, {"id": "fdc1affc-cd2e-42c2-900f-20ec2a58c5cf", "term": "XCVI", "definition": "XCVI is Allen & Heath's proprietary FPGA-based (field-programmable gate array) mix processing engine used across the dLive, Avantis and SQ consoles. It performs the console's mixing, routing and processing in configurable gate-array hardware at a 96kHz sample rate, rather than on conventional fixed DSP chips. The XCVI name is proprietary to Allen & Heath; the underlying approach, an FPGA digital-mixer engine, is a generic architecture also used by other manufacturers.", "plain_english": "XCVI is Allen and Heath's own processing engine for their digital mixers. It handles the mixing, routing and effects inside one powerful chip. This chip is an FPGA, a type of chip that can be reprogrammed. It runs at 96 kilohertz for high sound quality. The name XCVI is also 96 in Roman numerals.", "purpose_function": "It provides the console's channel processing, mixing and routing in one reconfigurable hardware engine. This gives high channel counts, consistent low latency and a flexible architecture shared across models.", "practical_application": "An engineer benefits from XCVI when the same processing, latency and features carry across dLive, Avantis and SQ. This makes it easier to move between the different consoles.", "category": "Processing Core", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["XCVI Processing Core", "DEEP Processing", "RackExtra FX", "dLive", "Avantis", "RackUltra FX"], "common_mistakes": ["Calling XCVI a fixed DSP; it is an FPGA-based engine, a different type of processing hardware.", "Assuming each console model has a different engine, when dLive, Avantis and SQ share the XCVI architecture.", "Confusing the XCVI engine (the technology) with any one specific console product."], "scenario_contexts": ["Explaining why Avantis and dLive share the same 96 kHz sound and feature set.", "Choosing an Allen & Heath console partly because of the common XCVI processing platform.", "Troubleshooting latency, knowing the XCVI core gives a fixed, low latency figure."], "formula_symbolic": "", "formula_words": ""}, {"id": "5b3a4cdf-5aa0-4241-ad60-65d1922da517", "term": "XCVI Processing Core", "definition": "The XCVI Processing Core is the FPGA-based engine at the heart of Allen & Heath's dLive, Avantis and SQ consoles that runs the XCVI architecture. It carries out all channel processing, mixing, bus routing and embedded effects in gate-array hardware at 96kHz, and its configuration defines the console's channel, bus and processing capacity. It is Allen & Heath's proprietary implementation of a generic FPGA digital-mixer core.", "plain_english": "The XCVI Processing Core is the main chip inside Allen and Heath's digital mixers. It does the mixing, routing and built-in effects work. It is built on FPGA hardware and runs at 96 kilohertz. This core sets how many channels and buses the mixer can handle.", "purpose_function": "It is the central engine that performs and defines the console's processing. Its capacity therefore sets the available channels, buses and onboard processing power.", "practical_application": "When comparing dLive, Avantis and SQ, a technician looks at how each model's XCVI Processing Core is configured. This tells them the channel, bus and processing limits.", "category": "Processing Core", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["XCVI", "DEEP Processing", "RackExtra FX", "RackUltra FX", "dLive", "Avantis"], "common_mistakes": ["Treating 'XCVI' and 'XCVI Processing Core' as unrelated; the core is the hardware running the XCVI engine.", "Assuming the core can be swapped for a different chip, when capacity is unlocked by software packs, not new silicon.", "Believing the core uses standard fixed DSP chips rather than an FPGA."], "scenario_contexts": ["Specifying a dLive system knowing its XCVI Processing Core supports high input and mix-bus counts.", "Understanding that Avantis unlocks more of its core's capacity through the dPack upgrade.", "Explaining that onboard DEEP and RackExtra FX all run inside the XCVI Processing Core."], "formula_symbolic": "", "formula_words": ""}, {"id": "4e973d20-75ce-4255-8d06-7d61dbc632c0", "term": "dPack", "definition": "dPack is Allen & Heath's paid software processing upgrade (license) for the Avantis console. It unlocks extra capacity and processing within the existing XCVI core, increasing input channels from 64 to 96 and configurable mix buses from 42 to 56, and raising simultaneous Dyn8 dynamic-EQ instances from 16 to 24. It also adds processors such as DEEP preamp, compressor and expander models and a parametric EQ. The dPack name is proprietary to Allen & Heath; the concept, a paid software license that unlocks latent hardware capacity, is a generic method.", "plain_english": "dPack is a paid software upgrade for Allen and Heath's Avantis mixer. It unlocks more power that the mixer already has inside. It raises the channel count from 64 to 96. It raises the buses from 42 to 56. It also adds more built-in effects and processors.", "purpose_function": "It lets Avantis owners expand a console's channels, buses and processing without new hardware. This brings more dLive-class processing to the mixer through a software license.", "practical_application": "An engineer buys and installs dPack on an Avantis before a larger show. They then have 96 channels, 56 buses and extra DEEP processing available.", "category": "Software Upgrade", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["Avantis", "XCVI", "DEEP Processing", "Dyn8", "RackUltra FX", "DEEP Processor"], "common_mistakes": ["Thinking dPack adds new physical hardware; it is a software license that unlocks existing core capacity.", "Assuming every Avantis already has 96 channels and 56 buses, when those need the dPack upgrade.", "Confusing dPack's DEEP models and processors with the separate RackUltra FX hardware module."], "scenario_contexts": ["Upgrading an Avantis with dPack to reach 96 input channels for a festival stage.", "Enabling extra Dyn8 instances and DEEP models on Avantis through dPack.", "Deciding whether a show needs the added buses and processing that dPack provides."], "formula_symbolic": "", "formula_words": ""}, {"id": "6cea39ae-eeb4-42dd-aa30-454516b543de", "term": "DX Hub", "definition": "The DX Hub is an Allen & Heath proprietary remote expansion hub that connects to a compatible console through a single SLink or gigaACE port and provides four downstream DX Link ports. Each DX port carries 32x32 channels of 96 kHz audio and feeds DX-series expanders, giving one hub up to 128 remote inputs and 64 remote outputs. It only distributes signal and cascades expanders; it has no preamps or connectors for microphones itself.", "plain_english": "The DX Hub is an Allen & Heath box that splits one cable into four. You run one network cable from the mixer to the hub. Then the hub connects to several stage boxes, called DX expanders. This lets one mixer reach many more inputs and outputs.", "purpose_function": "It exists to fan a single console I/O port out to multiple remote DX expanders, so one link can serve far more stage boxes than a point-to-point connection. This reduces cabling and lets large systems spread I/O across a venue.", "practical_application": "A technician runs one Cat5e cable from the console's SLink or gigaACE port to the DX Hub, then patches DX168, DX164-W, DX012 or DX32 expanders into its four DX ports across the stage.", "category": "I/O Expansion Hub", "difficulty": "intermediate", "achievement_id": "4994320e-1559-4f97-af87-2a6fd0cc421f", "cross": [], "related_terms": ["DX168", "DX32", "SLink", "gigaACE", "DX012", "GX4816"], "common_mistakes": ["Assuming the DX Hub adds inputs itself; it has no preamps and only distributes to expanders", "Exceeding the per-port limit of two DX168/DX164-W/DX012 or one DX32 on a single DX socket", "Confusing its single upstream SLink/gigaACE feed with its four downstream DX ports"], "scenario_contexts": ["Feeding several stage boxes around a theatre from one console I/O port", "Running a pair of DX Hubs for a redundant dual-cable link to dLive hardware", "Centralising DX expander distribution in an install rack room"], "formula_symbolic": "", "formula_words": ""}, {"id": "8da99ee7-c670-43fd-a19c-3c85876352e1", "term": "DX012", "definition": "The DX012 is an Allen & Heath proprietary output-only DX expander in a 1U rack chassis, providing 12 balanced XLR line outputs at 96 kHz. It connects to a compatible console, DX Hub or GX expander over a DX Link port carrying 32x32 channels of audio on shielded Cat5 cabling. It has no microphone inputs.", "plain_english": "The DX012 is an Allen & Heath rack box with twelve outputs. It sends audio out from the mixer to amplifiers, speakers or recorders. It has no inputs, only outputs. One network cable links it back to the mixing system.", "purpose_function": "It exists to add remote line-level outputs near amplifiers, monitors or other gear, so output feeds do not all have to run from the console. This keeps analogue cable runs short and tidy.", "practical_application": "A technician racks the DX012 in an amp room and patches its 12 XLR outputs to amplifier inputs, feeding them digitally from the console over one DX Link cable.", "category": "I/O Expander", "difficulty": "intermediate", "achievement_id": "4994320e-1559-4f97-af87-2a6fd0cc421f", "cross": [], "related_terms": ["DX168", "DX164-W", "DX Hub", "SLink", "DX32", "gigaACE"], "common_mistakes": ["Expecting inputs on the DX012; it is outputs only", "Confusing the DX012 with input-capable expanders like the DX168", "Assuming it uses Dante; DX is a proprietary A&H transport over Cat5, not an open network standard"], "scenario_contexts": ["Feeding amplifier racks with 12 line outputs from a distant console", "Providing extra matrix or aux outputs near stage-left monitors", "Sending outputs to a broadcast or recording room over one cable"], "formula_symbolic": "", "formula_words": ""}, {"id": "dd448bf8-bf36-4fc2-834c-22d340584456", "term": "DX164-W", "definition": "The DX164-W is an Allen & Heath proprietary wall-mountable DX expander offering 16 remote-controlled mic/line inputs and 4 XLR line outputs at 96 kHz. Preamp gain, pad and 48V phantom power are set remotely from the console, and it connects over a DX Link port carrying 32x32 channels on shielded Cat5 cabling.", "plain_english": "The DX164-W is an Allen & Heath stage box built to mount on a wall. It has sixteen inputs and four outputs. You set its microphone gain and power from the mixer, not on the box. One network cable links it to the mixing system.", "purpose_function": "It exists to add fixed, wall-mounted remote I/O in installed rooms, so microphones and outputs can be wired to a wall panel instead of a portable box. Remote preamp control keeps all gain settings recallable at the console.", "practical_application": "A technician mounts the DX164-W on a wall in a conference room or house of worship, wires local mics and speaker feeds to it, and controls it over one DX cable from the mixer.", "category": "I/O Expander", "difficulty": "intermediate", "achievement_id": "4994320e-1559-4f97-af87-2a6fd0cc421f", "cross": [], "related_terms": ["DX168", "DX012", "DX Hub", "SLink", "DX32", "gigaACE"], "common_mistakes": ["Trying to set gain on the box; preamps are remote-controlled from the console", "UNSAFE: leaving 48V phantom power on while patching, which can stress equipment and connectors", "Confusing the wall-mount DX164-W with the portable DX168 stage box"], "scenario_contexts": ["Permanent install in a house of worship with wall-mounted inputs", "Corporate boardroom with fixed mic and output panels", "Fixed classroom or lecture-hall audio wiring"], "formula_symbolic": "", "formula_words": ""}, {"id": "1f1df9d3-6703-47dc-be2c-236e9e721a3f", "term": "DX168", "definition": "The DX168 is an Allen & Heath proprietary portable DX expander with 16 remote-controlled mic/line preamps and 8 XLR line outputs at 96 kHz. Gain, pad and 48V phantom power are controlled from the mixing system, and it connects via an EtherCon DX Link port carrying 32x32 channels on Cat5e up to 100 m, with a second port for cascade or redundancy.", "plain_english": "The DX168 is an Allen & Heath portable stage box. It has sixteen inputs and eight outputs. You plug microphones into it on stage and control their settings from the mixer. One network cable, up to 100 metres, carries all the audio back to the console.", "purpose_function": "It exists to place recallable remote preamps and outputs on stage, so many mic and output cables collapse into one network link back to the console. This replaces heavy analogue multicore snakes.", "practical_application": "A technician sets the DX168 at stage edge, plugs in vocal and instrument mics plus monitor feeds, and runs one Cat5e cable to the console, adjusting all gains remotely.", "category": "I/O Expander", "difficulty": "intermediate", "achievement_id": "4994320e-1559-4f97-af87-2a6fd0cc421f", "cross": [], "related_terms": ["DX164-W", "DX012", "DX Hub", "SLink", "DX32", "gigaACE"], "common_mistakes": ["Using unshielded or over-length cable beyond the 100 m Cat5e limit, causing dropouts", "Expecting local gain knobs; preamps are set remotely from the console", "UNSAFE: hot-patching microphones with 48V phantom power engaged"], "scenario_contexts": ["Portable stage box for a touring band on a compatible console", "Adding remote inputs quickly at a corporate event", "Cascading a second DX168 for extra stage channels"], "formula_symbolic": "", "formula_words": ""}, {"id": "6220e587-b98c-4749-9c1c-ada60240b6f1", "term": "DX32", "definition": "The DX32 is an Allen & Heath proprietary modular DX expander with four card slots accepting 8-channel modules, for up to 32 channels of I/O at 96 kHz. Modules include recallable mic preamps, line outputs and AES3 digital I/O, and it connects over a DX Link port carrying 32x32 channels on shielded Cat5.", "plain_english": "The DX32 is an Allen & Heath expander you build to order. It has four slots for cards. Each card adds eight inputs or outputs, up to thirty-two channels total. You mix and match input, output and digital cards to fit the job.", "purpose_function": "It exists to give a configurable stage rack where the mix of inputs, outputs and digital I/O can be chosen with cards, instead of a fixed layout. This suits installs and tours needing custom channel counts.", "practical_application": "A technician fits the DX32 with the needed mix of preamp, line-output and AES3 cards, racks it near the stage, and links it to the console over one DX cable.", "category": "Modular I/O Expander", "difficulty": "intermediate", "achievement_id": "4994320e-1559-4f97-af87-2a6fd0cc421f", "cross": [], "related_terms": ["DX168", "DX Hub", "Prime I/O", "SLink", "gigaACE", "DX012"], "common_mistakes": ["Assuming a fixed I/O count; the channel mix depends on which 8-channel cards are fitted", "Filling a DX Hub DX port with more than one DX32, which is its per-port limit", "Confusing DX32 modules with open-standard cards; DX is a proprietary A&H format"], "scenario_contexts": ["Custom stage rack with mixed mic, line and AES3 I/O", "Installed system needing a tailored input/output count", "Adding Prime I/O premium modules for higher-fidelity capture"], "formula_symbolic": "", "formula_words": ""}, {"id": "214c1383-db1b-4e5d-aeef-4ae56e218060", "term": "Everything I/O", "definition": "Everything I/O is Allen & Heath's brand name for its family of input/output expansion hardware for the Qu, SQ, Avantis, dLive and AHM systems. It groups DX and GX expanders, hubs and Dante network interfaces under one range, connecting over proprietary transports such as DX, gigaACE and SLink and, for third-party networking, the open Dante standard.", "plain_english": "Everything I/O is Allen & Heath's name for its whole set of add-on input and output boxes. It covers stage boxes, hubs and network cards for their mixers. Some use Allen & Heath's own cabling systems. Others connect to Dante, a shared audio network standard.", "purpose_function": "The label exists to present all of Allen & Heath's expansion I/O as one compatible ecosystem, so users can pick boxes that share connectors and control across their consoles. It helps match the right expander and protocol to a job.", "practical_application": "A technician planning a system browses the Everything I/O range to choose expanders, a DX Hub or Dante interface that fit the console and required channel count.", "category": "I/O Ecosystem", "difficulty": "intermediate", "achievement_id": "4994320e-1559-4f97-af87-2a6fd0cc421f", "cross": [], "related_terms": ["DX Hub", "DX168", "GX4816", "SLink", "gigaACE", "DX32"], "common_mistakes": ["Treating Everything I/O as one device; it is a product range, not a single box", "Assuming every unit uses the same port; DX, gigaACE, SLink and Dante differ", "Confusing A&H proprietary transports with the open Dante standard used by Dante interfaces"], "scenario_contexts": ["Specifying compatible expanders when designing an A&H system", "Choosing between a proprietary DX link and a Dante interface for integration", "Comparing 48 kHz and 96 kHz expanders in the range for a project"], "formula_symbolic": "", "formula_words": ""}, {"id": "89a9bd7f-9553-4ec7-8cde-99ede9437b30", "term": "GX4816", "definition": "The GX4816 is an Allen & Heath proprietary gigaACE expander providing 48 remote-controlled mic/line inputs and 16 XLR line outputs at 96 kHz. It connects to a console over gigaACE (or SLink) carrying 128x128 channels on shielded Cat5e, and adds two DX ports for cascading further DX expanders.", "plain_english": "The GX4816 is a large Allen & Heath stage box. It has forty-eight inputs and sixteen outputs. It uses gigaACE, Allen & Heath's high-capacity network link. It also has two extra ports to add more DX stage boxes downstream.", "purpose_function": "It exists to supply a high channel count from one gigaACE link, covering a big stage while leaving DX ports to expand further. This makes it a main stage rack for larger shows and installs.", "practical_application": "A technician uses the GX4816 as the main stage rack, wiring 48 inputs and 16 outputs, linking to the console over gigaACE and cascading DX168 boxes on its DX ports.", "category": "I/O Expander", "difficulty": "intermediate", "achievement_id": "4994320e-1559-4f97-af87-2a6fd0cc421f", "cross": [], "related_terms": ["gigaACE", "DX Hub", "DX168", "SLink", "DX32", "Everything I/O"], "common_mistakes": ["Confusing the high-capacity gigaACE link (128x128) with a DX link (32x32)", "Trying to use the GX4816's DX1/DX2 ports for a redundant console link, which they do not support", "Assuming local gain controls; the 48 preamps are set remotely from the console"], "scenario_contexts": ["Main stage rack for a large touring or festival stage", "High channel-count install feeding many mics from one gigaACE cable", "Expanding a stage further by cascading DX expanders on its DX ports"], "formula_symbolic": "", "formula_words": ""}, {"id": "2558dbca-b429-4ce1-a4db-c1d687dd905a", "term": "Prime I/O", "definition": "Prime I/O is Allen & Heath's range of premium 8-channel input and output modules for the DX32 modular expander. The Prime input module uses a DC-coupled gain stage with 32-bit, 96 kHz analogue-to-digital conversion, and the Prime output module uses 32-bit digital-to-analogue conversion with a balanced differential output stage. The modules install in DX32 chassis for dLive, Avantis and SQ systems.", "plain_english": "Prime I/O is a set of higher-grade cards from Allen & Heath. They fit into the DX32 modular stage box. The input card captures sound with high-resolution converters. The output card sends audio out cleanly. You can mix them with standard DX32 cards.", "purpose_function": "The range exists to offer higher-fidelity conversion and preamp design than standard DX32 modules, for users wanting improved detail and headroom. It lets an existing DX32 be upgraded card by card.", "practical_application": "A technician fits Prime input and output modules into a DX32 to capture key sources at higher quality, mixing them with standard modules as budget and channel needs allow.", "category": "I/O Modules", "difficulty": "intermediate", "achievement_id": "4994320e-1559-4f97-af87-2a6fd0cc421f", "cross": [], "related_terms": ["DX32", "DX Hub", "DX168", "SLink", "gigaACE", "Everything I/O"], "common_mistakes": ["Thinking Prime I/O is a standalone box; the modules only work inside a DX32 expander", "Assuming all DX32 slots must be Prime; Prime and standard modules can be mixed", "Confusing higher converter bit depth on the module with the fixed 96 kHz system sample rate"], "scenario_contexts": ["Upgrading a DX32 to capture lead vocals or acoustic sources at higher fidelity", "Building a premium stage rack for a recording-grade live capture", "Mixing Prime and standard modules to prioritise key channels"], "formula_symbolic": "", "formula_words": ""}, {"id": "e086ae20-75db-40a4-8f47-bc00394631a9", "term": "Dual-Stage Valve Preamp", "definition": "The Dual-Stage Valve Preamp is a DEEP processing model from Allen & Heath that recreates the distortion characteristics of a two-stage valve (vacuum tube) preamplifier circuit. It applies coloration ranging from subtle warmth to full overdrive, using Drive and Level controls and switchable distortion modes, and runs inside a mixer channel with zero added latency.", "plain_english": "This is a software effect made by Allen & Heath. It copies the warm sound of an old tube amplifier. You turn up the Drive control to add gentle color or heavier grit. It runs right inside a channel on the mixer.", "purpose_function": "It exists to add valve-style harmonic warmth and saturation to a channel without needing outboard tube gear. The name is an Allen & Heath trademark; the underlying method is generic valve preamp saturation.", "practical_application": "An engineer inserts it on a vocal, bass, or drum channel to add analog-style warmth or drive, adjusting Drive and Level to taste while keeping the signal in the digital console.", "category": "Valve Preamp (DEEP)", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["DEEP processing", "Harmonic distortion", "Preamp", "Saturation", "Gain staging", "Dyn8"], "common_mistakes": ["Confusing this modeled preamp with the channel's real input preamp gain stage", "Adding so much Drive that the signal distorts unpleasantly and loses clarity", "Assuming it is a real hardware tube unit rather than an Allen & Heath software emulation"], "scenario_contexts": ["Warming up a thin-sounding vocal on an Allen & Heath SQ or Avantis console", "Adding grit to a DI bass channel during mixing", "Giving a drum bus subtle analog color without patching external gear"], "formula_symbolic": "", "formula_words": ""}, {"id": "b2a3c0c6-2d7e-4d84-9bd6-3cf0e10511ec", "term": "Dyn8", "definition": "Dyn8 is an Allen & Heath proprietary dynamics processor that combines four bands of multiband compression with four bands of dynamic EQ in a single insertable unit. It provides frequency-selective dynamic control that can be placed on input or mix channels of Allen & Heath digital consoles such as dLive and Avantis.", "plain_english": "Dyn8 is a tool made by Allen & Heath for live sound mixers. It splits the sound into frequency bands. Then it can squash loud parts or dip harsh frequencies only when they get too strong. This helps tame vocals or glue a mix together.", "purpose_function": "It exists to give engineers detailed, frequency-specific dynamics control in one processor, combining multiband compression and dynamic equalization. The name Dyn8 is an Allen & Heath trademark; the underlying methods are generic multiband compression and dynamic EQ.", "practical_application": "An engineer inserts Dyn8 on a vocal, subgroup, or full mix to smooth harsh resonances and control dynamics per band without stacking several separate processors.", "category": "Dynamics Processor", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["Dyn8 Engine", "Multiband compression", "Dynamic EQ", "Compressor", "DEEP processing", "Sidechain"], "common_mistakes": ["Confusing dynamic EQ (level-dependent) with static graphic or parametric EQ", "Treating Dyn8 as a single broadband compressor rather than a multiband, per-frequency processor", "Overprocessing all bands at once so the source sounds squashed and lifeless"], "scenario_contexts": ["Taming sibilance and boxiness on a lead vocal at a live show", "Adding cohesion to an in-ear monitor mix", "Tightening a drum subgroup on a dLive or Avantis console"], "formula_symbolic": "", "formula_words": ""}, {"id": "30bdf9be-a316-45dc-941c-cbf3f0d623b1", "term": "Dyn8 Engine", "definition": "A Dyn8 Engine is a single instance of Allen & Heath's Dyn8 dynamics processor, each providing four bands of multiband compression plus four bands of dynamic EQ, that can be inserted on one input or mix channel. Allen & Heath dLive systems provide 64 Dyn8 engines deployable across any 64 channels, while Avantis offers 16 engines at its base and 24 with the dPack upgrade.", "plain_english": "A Dyn8 Engine is one copy of the Dyn8 tool ready to use on a channel. Each engine has its own set of bands to control the sound. A dLive mixer gives you 64 of these engines to spread across channels. You place them where the mix needs the most help.", "purpose_function": "Engines exist as a shared pool of dynamics processing that engineers assign only to the channels that need it, using the console's resources efficiently. The name is an Allen & Heath trademark; each engine performs generic multiband compression and dynamic EQ.", "practical_application": "An engineer assigns Dyn8 engines to the channels most needing detailed dynamics, such as lead vocals and key subgroups, rather than every channel, to make the best use of the limited pool.", "category": "Dynamics Processor", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["Dyn8", "Multiband compression", "Dynamic EQ", "Channel insert", "DEEP processing", "DSP resources"], "common_mistakes": ["Assuming an unlimited number of engines are available on every console", "Placing an engine on every channel and exhausting the shared pool", "Confusing a Dyn8 engine with a DEEP compressor model, which is a separate processor type"], "scenario_contexts": ["Allocating a Dyn8 engine to a lead vocal during soundcheck", "Managing the 16-engine pool on an Avantis with dPack across a busy input list", "Freeing an engine from an unused channel to reassign it to a problem source"], "formula_symbolic": "", "formula_words": ""}, {"id": "05dcfdd6-5643-4991-8e2c-f931daba2232", "term": "Mighty Compressor", "definition": "The Mighty Compressor is an Allen & Heath DEEP compressor model inspired by a classic transistor-array VCA (voltage-controlled amplifier) dynamics processor, known for fast, aggressive, punchy compression. It offers Peak and Average detection modes and a parallel compression path with dry/wet blend, running inside a mixer channel with zero latency.", "plain_english": "The Mighty is a punchy compressor made by Allen & Heath. It grabs loud sounds fast and hard to make instruments cut through a mix. A Peak mode acts like a quick limiter, and an Average mode lets punchy hits pop. You can blend it with the clean sound for parallel compression.", "purpose_function": "It exists to add aggressive, high-energy compression and punch, especially on drums and bass. The name Mighty Compressor is an Allen & Heath trademark; the underlying method is a generic transistor VCA compressor.", "practical_application": "An engineer uses it on kick, snare, drum bus, or bass to add punch and density, choosing Peak or Average mode and dialing in parallel blend to keep natural dynamics.", "category": "DEEP Compressor", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["Compressor", "VCA compressor", "Parallel compression", "Peak Limiter 76", "OptTronik", "Attack and release"], "common_mistakes": ["Using its aggressive settings on delicate sources where gentle compression is wanted", "Ignoring the dry/wet blend and over-squashing the signal", "Assuming Peak and Average modes sound the same rather than choosing by material"], "scenario_contexts": ["Adding punch to a snare drum in an aggressive rock mix", "Compressing a drum bus for parallel 'glue'", "Making a bass guitar sit forward and consistent in a dense mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "92a34c2a-63f2-4b9b-a593-4b832379ea13", "term": "OptTronik", "definition": "OptTronik is an Allen & Heath DEEP compressor model that delivers smooth, natural gain reduction modeled on a studio-favourite compressor, with an opto-electronic (optical) style of response as suggested by its name and character. It is one of the DEEP Compressors and runs inside a mixer channel with zero latency.", "plain_english": "OptTronik is a smooth-sounding compressor made by Allen & Heath. It softens the loudest parts of a sound gently and naturally. It copies the easy, musical feel of a classic studio compressor. Engineers use it when they want control without an obvious effect.", "purpose_function": "It exists to provide gentle, transparent leveling in the style of a classic optical compressor, useful when heavy or aggressive compression would be too obvious. The name OptTronik is an Allen & Heath trademark; the underlying method is a generic optical/opto-electronic compressor.", "practical_application": "An engineer places it on vocals, acoustic instruments, or a mix bus to even out levels smoothly and musically without a pumping or squashed character.", "category": "DEEP Compressor", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["Compressor", "Optical compressor", "Mighty Compressor", "Peak Limiter 76", "DEEP processing", "Gain reduction"], "common_mistakes": ["Expecting fast, aggressive limiting from a smooth optical-style compressor", "Confusing OptTronik with the separate DEEP 'Opto' compressor model", "Assuming it is real hardware rather than an Allen & Heath software emulation"], "scenario_contexts": ["Smoothing a lead vocal gently during a live performance", "Leveling an acoustic guitar without an obvious pumping sound", "Applying subtle glue compression on a mix bus"], "formula_symbolic": "", "formula_words": ""}, {"id": "5754225d-0113-4a8f-b291-322105bdb585", "term": "Peak Limiter 76", "definition": "Peak Limiter 76 is an Allen & Heath DEEP compressor/limiter model that emulates a world-famous late-1960s FET (field-effect transistor) limiting amplifier, of the type introduced by UREI/Universal Audio as the 1176. It models both early 'blackface' and later 'silverface' variants, offers five ratio settings plus an 'All-Buttons' mode for aggressive distorted compression, and runs inside a mixer channel with zero latency.", "plain_english": "Peak Limiter 76 is a fast compressor and limiter made by Allen & Heath. It copies a famous studio unit built with transistors. It can compress gently or clamp down hard on peaks. An 'All-Buttons' mode gives a gritty, aggressive sound. It runs right on a mixer channel.", "purpose_function": "It exists to bring the fast attack and characterful sound of a classic FET limiting amplifier into the console. 'Peak Limiter 76' is an Allen & Heath trademark; the emulated hardware (the 1176) is a UREI/Universal Audio trademark, and the underlying method is a generic FET compressor/limiter.", "practical_application": "An engineer uses it on vocals, guitars, drums, or bass to control peaks and add punch or grit, picking a ratio, choosing the blackface or silverface variant, and optionally engaging All-Buttons mode.", "category": "DEEP Limiter", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["Limiter", "FET compressor", "Compression ratio", "Mighty Compressor", "OptTronik", "Attack and release"], "common_mistakes": ["Assuming All-Buttons mode is a normal setting rather than an aggressive, distorted effect", "Confusing this modeled limiter with a true brickwall output/mastering limiter", "Setting extremely fast attack on sustained sources and dulling the tone"], "scenario_contexts": ["Adding aggressive character to a rock vocal", "Controlling and thickening an electric bass", "Catching drum peaks with fast FET-style limiting on a live console"], "formula_symbolic": "", "formula_words": ""}, {"id": "558f57d0-c699-4b46-9dde-7b0229b34a97", "term": "Source Expander", "definition": "Source Expander is an Allen & Heath DEEP dynamics model that performs downward expansion, reducing the level of a signal when it falls below a set threshold to suppress bleed and background spill. It provides simple threshold and depth controls for quick, set-and-forget operation on input or mix channels.", "plain_english": "Source Expander is a tool made by Allen & Heath that cleans up a channel. When a sound gets quiet, it turns the level down further to hide spill from other instruments. It is gentler than a gate. You just set two controls and leave it.", "purpose_function": "It exists to reduce microphone bleed and background noise smoothly, as a gentler alternative to a hard gate, using only threshold and depth for fast setup. The name Source Expander is an Allen & Heath trademark; the underlying method is a generic downward expander.", "practical_application": "An engineer inserts it on drum mics, live vocals, or spoken-word channels to reduce spill between numbers or during pauses, setting threshold and depth for natural clean-up.", "category": "DEEP Expander", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["Expander", "Noise gate", "Threshold", "Downward expansion", "DEEP processing", "Microphone bleed"], "common_mistakes": ["Confusing an expander with a gate; an expander reduces level gradually rather than cutting it hard", "Setting the threshold too high so wanted quiet passages get suppressed", "UNSAFE: relying on the expander instead of good mic placement to fix serious feedback risk before raising gain"], "scenario_contexts": ["Reducing hi-hat spill into a snare microphone", "Cleaning up a live vocal channel between songs", "Suppressing room noise on a lectern or presenter microphone"], "formula_symbolic": "", "formula_words": ""}, {"id": "4c89310d-6d10-44be-b8b0-bfaf8885ed90", "term": "ME Personal Mixing System", "definition": "The ME Personal Mixing System is Allen & Heath's proprietary personal monitoring platform that lets each performer build an independent monitor mix from a shared set of source channels. It comprises personal mixers (ME-1 and ME-500) and the ME-U distribution hub, linked over Cat5 Ethernet cabling. The name is an Allen & Heath trademark; the underlying method — distributed personal monitor mixing for wedges or in-ears — is a generic live-sound technique.", "plain_english": "This is Allen & Heath's own gear for personal stage monitoring. Each musician gets a small mixer to control their own headphone or in-ear sound. They pick from the same set of channels sent from the main desk. This cuts down on shouting for 'more me' during a show.", "purpose_function": "It moves monitor-mix control to each performer, so a monitor engineer does not have to set every mix by hand. This speeds up soundcheck and lets players tailor their own in-ear or wedge feed.", "practical_application": "A technician patches the console's channels into the ME network, then gives each musician a personal mixer to dial in their own monitor mix.", "category": "Personal Monitoring", "difficulty": "intermediate", "achievement_id": "dd0a3205-2240-40a8-9c0a-5ab65a91a5a5", "cross": [], "related_terms": ["ME-1", "ME-500", "ME-U", "In-Ear Monitor (IEM)", "Monitor Send", "Personal Monitor Mixer"], "common_mistakes": ["UNSAFE: Cranking in-ear or headphone level to hear over a poor mix risks permanent hearing damage; build a balanced mix at a low level instead.", "Assuming the system creates new sources; performers can only mix the fixed channels sent from the console or hub.", "Forgetting the ME mixers need Power over Ethernet or a DC supply, so a plain non-PoE switch leaves them dead."], "scenario_contexts": ["A worship band uses in-ear monitors, with each member mixing their own feed on a personal mixer.", "A touring act runs the ME system so the monitor engineer can focus on wedges while players self-mix in-ears."], "formula_symbolic": "", "formula_words": ""}, {"id": "c4704225-dc7f-4f5b-a1f8-9cff5eaea4a7", "term": "ME-1", "definition": "The ME-1 is a standalone digital personal mixer in Allen & Heath's ME system that receives up to 40 audio sources over a single Cat5 cable. It provides 3-band EQ, up to 16 groups and 16 user presets, plus headphone, mono and stereo outputs for driving in-ears or wedges. The ME-1 is an Allen & Heath trademark; it performs the generic function of a performer-controlled personal monitor mixer.", "plain_english": "The ME-1 is a personal mixer made by Allen & Heath. One network cable feeds it up to forty channels to choose from. A musician uses its knob and buttons to set their own monitor sound. It draws power over the same cable or from a small power supply.", "purpose_function": "It gives one performer hands-on control of their own monitor mix, removing the need for a monitor engineer to set every channel for them.", "practical_application": "A technician runs one Cat5 cable to each ME-1 and clips it to a mic stand, letting the player mix their own in-ears or wedge.", "category": "Personal Monitoring", "difficulty": "intermediate", "achievement_id": "dd0a3205-2240-40a8-9c0a-5ab65a91a5a5", "cross": [], "related_terms": ["ME Personal Mixing System", "ME-500", "ME-U", "In-Ear Monitor (IEM)", "Aviom A-Net", "Monitor Send"], "common_mistakes": ["UNSAFE: Turning the ME-1 headphone or in-ear output to dangerous levels to mask a weak mix; protect hearing by mixing quietly first.", "Expecting more than 40 sources; the ME-1 handles up to 40 channels from the network.", "Feeding it from a non-PoE switch; the ME-1 needs Power over Ethernet or its 12V DC supply."], "scenario_contexts": ["A drummer mixes click, bass and vocals on their own ME-1 during a live set.", "During soundcheck, each band member adjusts their ME-1 without waiting on the monitor engineer."], "formula_symbolic": "", "formula_words": ""}, {"id": "9d21fe51-434b-4dfe-a7f7-31de7c2db6b6", "term": "ME-500", "definition": "The ME-500 is a standalone digital personal mixer in Allen & Heath's ME system that receives up to 16 mono or stereo sources over a single Cat5 cable. It offers 2-band EQ, 8 user presets and an internal headphone amplifier, and is a simpler, more compact unit than the ME-1 on the same ME network. The ME-500 is an Allen & Heath trademark; it performs the generic function of a performer-controlled personal monitor mixer.", "plain_english": "The ME-500 is a smaller personal mixer from Allen & Heath. One cable feeds it up to sixteen channels to mix. It has fewer controls than the ME-1, which keeps it simple. Each musician uses it to set their own headphone or in-ear sound.", "purpose_function": "It offers a straightforward way for a performer to control their own monitor mix, aimed at users who need fewer channels and simpler operation than the ME-1.", "practical_application": "A technician gives each player an ME-500 for quick, simple personal mixing when up to 16 sources are enough.", "category": "Personal Monitoring", "difficulty": "intermediate", "achievement_id": "dd0a3205-2240-40a8-9c0a-5ab65a91a5a5", "cross": [], "related_terms": ["ME Personal Mixing System", "ME-1", "ME-U", "In-Ear Monitor (IEM)", "Monitor Send", "Personal Monitor Mixer"], "common_mistakes": ["UNSAFE: Raising in-ear volume on the ME-500 to overcome a muddy mix; loud in-ears can cause hearing loss, so balance the mix at low volume.", "Assuming it matches the ME-1's 40 sources; the ME-500 handles up to 16 mono or stereo channels.", "Overlooking its 2-band EQ and expecting the ME-1's 3-band EQ."], "scenario_contexts": ["A small club band uses ME-500 units for simple personal in-ear mixes.", "A backing vocalist sets a quick vocal-and-band balance on an ME-500."], "formula_symbolic": "", "formula_words": ""}, {"id": "0a825c9c-1e7b-491e-902a-459a350006e1", "term": "ME-U", "definition": "The ME-U is Allen & Heath's 10-port Power-over-Ethernet hub for the ME personal monitoring system. It distributes up to 40 audio sources, plus channel names and stereo-link data, to connected ME-1 and ME-500 personal mixers and powers them over Cat5 cabling. Removable input cards let it connect to Allen & Heath consoles or to third-party networks such as Dante and MADI; the ME-U is an Allen & Heath trademark.", "plain_english": "The ME-U is a hub that feeds and powers several personal mixers. It sends the same set of channels down to each musician's mixer over a network cable. It also supplies power through that cable, so no extra adapters are needed. Swappable cards let it link to Allen & Heath desks or Dante and MADI systems.", "purpose_function": "It spreads audio and power to many personal mixers from one point and bridges the ME system to non-Allen & Heath consoles through digital audio network cards.", "practical_application": "A technician racks the ME-U, fits the right input card, then runs one Cat5 cable to each performer's personal mixer to carry both audio and power.", "category": "Personal Monitoring", "difficulty": "intermediate", "achievement_id": "dd0a3205-2240-40a8-9c0a-5ab65a91a5a5", "cross": [], "related_terms": ["ME Personal Mixing System", "ME-1", "ME-500", "Power over Ethernet (PoE)", "Dante", "MADI"], "common_mistakes": ["Using a non-PoE network switch in place of the ME-U, which leaves the personal mixers without power.", "Fitting the wrong input card for the connected console or network, so no audio reaches the mixers.", "UNSAFE: Trusting the hub to protect ears; safe listening still depends on each performer keeping in-ear levels low."], "scenario_contexts": ["A festival tech uses the ME-U's Dante card to feed personal mixers from a third-party console.", "A house of worship racks an ME-U to power and feed several personal mixers over single cables."], "formula_symbolic": "", "formula_words": ""}, {"id": "b7b6dca3-ae68-414a-9697-a66b27ec6d43", "term": "AAE", "definition": "AAE is the abbreviation for the Avid Audio Engine, the core audio processing and mixing engine in Pro Tools since version 11. Owned by Avid Technology, it is a 64-bit floating-point engine that handles recording, host (CPU) mixing, plug-in processing, and playback, and it replaced the earlier Digidesign Audio Engine (DAE). Like any DAW audio engine, it is the software layer that routes and processes audio through the session.", "plain_english": "AAE stands for Avid Audio Engine. It is the part of Pro Tools that plays, mixes, and processes your audio. Avid built it and owns the name. It took over from an older engine called DAE.", "purpose_function": "It provides the underlying real-time processing that lets Pro Tools record, mix, run plug-ins, and play many tracks at once. Avid introduced it to allow higher track counts, dynamic use of CPU power, and faster-than-real-time (offline) bounce.", "practical_application": "A technician meets AAE in the Playback Engine dialog, choosing buffer size and host-processing options to balance latency against plug-in load. Its offline bounce lets an engineer render a mix faster than playing it in real time.", "category": "Audio Engine", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Avid Audio Engine", "Playback Engine", "Offline Bounce", "Host-based processing", "Avid Video Engine", "Buffer size"], "common_mistakes": ["Confusing AAE with DAE; DAE was the older engine that AAE replaced in Pro Tools 11.", "Thinking AAE is a plug-in you switch on; it is the built-in engine that always runs Pro Tools audio.", "Assuming AAE also plays video; video is handled by the separate Avid Video Engine (AVE)."], "scenario_contexts": ["Opening the Playback Engine dialog to set a larger buffer for mixing, which changes how AAE uses host processing.", "Using offline bounce to export a stereo mix faster than real time.", "Troubleshooting a host-processor overload when AAE cannot keep up with the current plug-in load."], "formula_symbolic": "", "formula_words": ""}, {"id": "03e10ace-d789-4926-b8d2-91ab9a1bf323", "term": "AVE", "definition": "AVE is the abbreviation for the Avid Video Engine, the built-in video playback and processing engine in Pro Tools since version 11. Owned by Avid Technology, it plays a range of HD video formats — including Avid DNxHD and QuickTime media — directly on the Pro Tools video track without transcoding. It is the video counterpart to the Avid Audio Engine.", "plain_english": "AVE stands for Avid Video Engine. It is the part of Pro Tools that plays video in time with your audio. Avid built it and owns the name. It lets an editor watch the picture while working on the sound.", "purpose_function": "It gives audio-post engineers frame-accurate video playback synced to the session, so sound can be edited against picture. Avid built it into Pro Tools to reduce reliance on outside video software and on transcoding.", "practical_application": "A post-production technician imports a picture file, and AVE plays it in the Video window locked to the timeline while dialogue, effects, and music are edited to it.", "category": "Video Engine", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Avid Video Engine", "Avid Audio Engine", "DNxHD", "Video track", "Video window", "Timecode"], "common_mistakes": ["Confusing AVE (video) with AAE (audio); they are two separate engines.", "Assuming AVE plays every video format; it supports specific formats such as DNxHD and certain QuickTime media.", "Forgetting that heavy video playback shares system resources and can affect performance."], "scenario_contexts": ["Scoring a scene by playing the locked picture through AVE while composing to it.", "Editing dialogue to a DNxHD video clip on the Pro Tools video track.", "Monitoring picture on an external display through a supported Avid video interface."], "formula_symbolic": "", "formula_words": ""}, {"id": "0bccd9db-6e5e-437b-8a81-74e4996c15f9", "term": "Avid Audio Engine", "definition": "The Avid Audio Engine (AAE) is the core software engine in Pro Tools that records, mixes, and processes audio and drives playback. Owned by Avid Technology and introduced in Pro Tools 11, it is a 64-bit floating-point engine that replaced the Digidesign Audio Engine (DAE). It performs the generic role of a DAW audio engine: routing audio through tracks, buses, and plug-ins in real time.", "plain_english": "The Avid Audio Engine is the heart of Pro Tools. It records, mixes, and plays back all of your audio. Avid made it and owns the name. It replaced the older engine, DAE, in Pro Tools 11.", "purpose_function": "It supplies the real-time processing that lets Pro Tools run many tracks, buses, and plug-ins at once. Avid rebuilt it for version 11 to add 64-bit mixing, dynamic host processing, and offline bounce.", "practical_application": "Engineers configure the Avid Audio Engine through the Playback Engine dialog, trading buffer size against latency, and rely on its offline bounce to render mixes quickly.", "category": "Audio Engine", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["AAE", "Playback Engine", "Offline Bounce", "Host-based processing", "Avid Video Engine", "Dynamic host processing"], "common_mistakes": ["Calling it DAE; DAE was the previous engine that the Avid Audio Engine replaced.", "Believing plug-ins always draw full CPU; dynamic host processing frees resources when a plug-in is not passing audio.", "Assuming a larger buffer harms quality; it only trades latency for more processing headroom."], "scenario_contexts": ["Raising the buffer size while mixing a large session to give the engine more processing room.", "Rendering a final mix with offline bounce rather than a real-time bounce.", "Comparing plug-in counts before and after upgrading from DAE-era Pro Tools 10 to the AAE in Pro Tools 11."], "formula_symbolic": "", "formula_words": ""}, {"id": "d7a91698-fbe2-4fbc-a8bb-ff7755523f3a", "term": "Avid Video Engine", "definition": "The Avid Video Engine (AVE) is the built-in video playback engine in Pro Tools, introduced in version 11. Owned by Avid Technology, it plays a range of HD video formats — including Avid DNxHD and QuickTime media — directly in the Pro Tools timeline without transcoding, and it works with supported Avid video interfaces for external monitoring. It is the video counterpart to the Avid Audio Engine.", "plain_english": "The Avid Video Engine plays video inside Pro Tools. It keeps the picture in sync with the sound. Avid made it and owns the name. It lets sound editors watch the film while they work.", "purpose_function": "It provides frame-accurate video playback locked to the session timeline so audio can be edited to picture. Avid built it in to cut reliance on outside video tools and time-consuming transcoding.", "practical_application": "A dialogue editor loads a DNxHD picture file, and the Avid Video Engine plays it in the Video window in sync while edits are made to match the action on screen.", "category": "Video Engine", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["AVE", "Avid Audio Engine", "DNxHD", "Video track", "Video window", "Timecode"], "common_mistakes": ["Mixing it up with the Avid Audio Engine; one handles video, the other audio.", "Expecting it to import any codec; only supported formats such as DNxHD and certain QuickTime media play natively.", "Ignoring that video playback consumes system resources that can affect audio performance."], "scenario_contexts": ["Cutting sound effects to a locked picture in an audio-post session.", "Playing a DNxHD reference movie in the Video window during a mix review.", "Sending video to a client monitor through a supported Avid video interface."], "formula_symbolic": "", "formula_words": ""}, {"id": "97c094cb-8415-4707-95e1-b5fe128f26a5", "term": "DSP Mode Safe", "definition": "DSP Mode Safe is a Pro Tools track setting on Avid HDX and Carbon Hybrid Engine systems that prevents a track from being automatically switched into DSP (hardware) mode. It keeps the chosen track in native (host CPU) mode even when audio is routed to it from a track in DSP mode, so native-only plug-ins on that track are not bypassed.", "plain_english": "DSP Mode Safe is a switch on a Pro Tools track. Normally, turning on hardware DSP mode can pull connected tracks into DSP mode too. This switch stops that on the track you pick. It keeps that track running on the computer instead.", "purpose_function": "It lets an engineer keep certain tracks — such as effect returns using native-only plug-ins — in native mode while others use low-latency DSP mode. Avid added it so a low-latency DSP path does not force a track to drop plug-ins that have no DSP version.", "practical_application": "A technician enables DSP Mode Safe on a reverb return so its native-only plug-in keeps working, even while the recording chain feeding it runs in low-latency DSP mode. It is set by right-clicking the track's DSP Mode button.", "category": "DSP Processing", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Hybrid Engine", "HDX Hybrid Engine", "DSP mode", "Native processing", "Low-latency monitoring", "AAX DSP"], "common_mistakes": ["Expecting a DSP Mode Safe track to also be low-latency; it stays in native mode, so its path is not zero-latency.", "Forgetting that audio monitored through both DSP-mode and DSP Mode Safe (native) tracks may not be time-aligned.", "Assuming it disables DSP everywhere; it only exempts the specific track it is set on."], "scenario_contexts": ["Keeping a reverb return with a native-only plug-in active while tracking through the Hybrid Engine.", "Preventing a bus master from inheriting DSP mode so its native plug-in chain stays intact.", "Right-clicking a track's DSP Mode button to set DSP Mode Safe before a low-latency overdub."], "formula_symbolic": "", "formula_words": ""}, {"id": "7e689428-bb7e-44fc-b0b1-7522659e2cbe", "term": "HDX Classic Mode", "definition": "HDX Classic Mode is the traditional operating mode of Avid Pro Tools HDX systems, in which the mixer and AAX DSP plug-ins run on the dedicated DSP chips of the HDX hardware. In this mode, the available voices and DSP plug-in counts are fixed by the number of installed HDX cards. It is contrasted with the newer Hybrid Engine, which adds per-track switching between DSP and native processing.", "plain_english": "HDX Classic Mode is the older way Pro Tools HDX hardware works. Special DSP chips on the HDX cards run the mixing and effects. How many tracks and effects you get depends on how many cards you have. It is different from the newer Hybrid Engine.", "purpose_function": "It provides very low-latency mixing and processing by running the audio path on dedicated DSP hardware instead of the computer's CPU. Avid used it as the standard HDX architecture before the Hybrid Engine was introduced.", "practical_application": "An engineer opening an older HDX session in Classic mode monitors through DSP plug-ins with near-zero latency, but is limited to the voice and DSP counts of the installed cards.", "category": "DSP Processing", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["HDX Hybrid Engine", "Hybrid Engine", "AAX DSP", "DSP mode", "Voice", "Low-latency monitoring"], "common_mistakes": ["Assuming Classic mode offers the same 2048-voice ceiling as the Hybrid Engine; here voice counts depend on installed HDX cards.", "Thinking Classic mode can run native (host) plug-ins in its DSP path; those must sit on native tracks.", "Confusing HDX Classic mode with host-only (native) Pro Tools systems that have no DSP hardware."], "scenario_contexts": ["Opening a legacy HDX session that was mixed with DSP plug-ins in Classic mode.", "Choosing Classic mode for guaranteed low-latency DSP monitoring on a large HDX rig.", "Hitting a voice-count limit on a Classic-mode HDX system with only one DSP card."], "formula_symbolic": "", "formula_words": ""}, {"id": "18904f05-d281-48b1-a310-7366eb226a1e", "term": "HDX Hybrid Engine", "definition": "The HDX Hybrid Engine is the operating mode of Avid Pro Tools HDX systems that decouples the DSP hardware from the native mixing engine, letting each track switch between low-latency DSP mode and native (host CPU) processing. Owned by Avid Technology, it makes up to 2048 voices available to all HDX systems regardless of card count, while running the mixer natively and offering hardware-accelerated low-latency paths where needed.", "plain_english": "The HDX Hybrid Engine is a newer way HDX hardware works. Each track can use the special DSP chips or the computer to do its processing. You switch a track to DSP for low-latency recording, then back for mixing. It also gives every HDX system a high track count.", "purpose_function": "It combines the low latency of DSP hardware with the flexibility and high track counts of native processing. Avid introduced it so users are no longer limited by how many DSP cards are installed.", "practical_application": "During tracking, an engineer puts the record path into DSP mode for near-zero latency monitoring, then returns those tracks to native mode for mixing with the full plug-in range.", "category": "DSP Processing", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Hybrid Engine", "HDX Classic Mode", "DSP Mode Safe", "DSP mode", "Native processing", "Voice"], "common_mistakes": ["Expecting virtual instruments to run in DSP mode; AAX DSP virtual instruments are not supported, so they stay native.", "Forgetting that enabling DSP mode on a track also switches the tracks its audio routes through, unless DSP Mode Safe is set.", "Assuming native-only plug-ins keep working in DSP mode; without a DSP version they are bypassed."], "scenario_contexts": ["Toggling a track into DSP mode for low-latency vocal overdubs, then back to native for mixing.", "Running a 2048-voice session on a single-card HDX system via the Hybrid Engine.", "Excluding a reverb return from inherited DSP mode using DSP Mode Safe."], "formula_symbolic": "", "formula_words": ""}, {"id": "e9c93b33-ce61-4837-931a-73ff307d18db", "term": "HEAT", "definition": "HEAT (Harmonically Enhanced Algorithm Technology) is an Avid Pro Tools option that adds analog-modeled, soft-saturated harmonic distortion across the channels of the Pro Tools HD/HDX mixer for mixing and mastering. Owned by Avid Technology and designed by Dave Hill of Crane Song, it applies subtle, program-dependent saturation and tonal coloration to emulate analog tape, transformer, and tube signal paths. The underlying method — harmonic saturation and analog modeling — is a generic audio-processing concept.", "plain_english": "HEAT stands for Harmonically Enhanced Algorithm Technology. It is an add-on for Pro Tools that adds gentle analog-style warmth to a mix. It works across the whole mixer, not just one track. Avid owns the name, and the basic idea is harmonic saturation.", "purpose_function": "It adds harmonic richness and gentle saturation to a digital mix so it sounds closer to audio run through analog gear. Avid offers it to give in-the-box mixes some of the character of analog consoles and tape.", "practical_application": "A mix engineer enables HEAT globally on the HD mixer and sets its Drive and Tone controls per channel to warm up an otherwise clean digital mix. Turning Drive one way favours tape-style odd harmonics, the other way tube-style even harmonics.", "category": "Analog Modeling", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Harmonically Enhanced Algorithm Technology", "Avid Audio Engine", "Saturation", "Harmonic distortion", "Pro Tools HD", "AAX"], "common_mistakes": ["Treating HEAT as a single-track plug-in; it is a global option applied across every channel of the HD mixer.", "Dialing in too much Drive so the subtle warmth becomes obvious distortion.", "Assuming it runs on any Pro Tools system; it is an option for Pro Tools HD/HDX."], "scenario_contexts": ["Adding gentle tape-style coloration across a full mix before mastering.", "Comparing a mix with HEAT bypassed and engaged to judge the added warmth.", "Setting per-channel Drive amounts to push drums harder than vocals."], "formula_symbolic": "", "formula_words": ""}, {"id": "cae583a0-ae18-4feb-b146-6d6783b2bf74", "term": "Harmonically Enhanced Algorithm Technology", "definition": "Harmonically Enhanced Algorithm Technology (HEAT) is the full name of an Avid Pro Tools option that adds analog-modeled, soft-saturated harmonic distortion across the channels of the Pro Tools HD/HDX mixer. Owned by Avid Technology and designed by Dave Hill of Crane Song, it emulates the harmonic coloration of analog tape, transformer, and tube signal paths for mixing and mastering. The method itself — harmonic saturation and analog modeling — is a generic audio-processing concept.", "plain_english": "This is the full name of HEAT, an Avid add-on for Pro Tools. It adds gentle analog-style warmth to a mix. It works across the whole mixer at once. The basic idea is harmonic saturation, and Avid owns the name.", "purpose_function": "It adds harmonic content and mild saturation so a clean digital mix takes on some analog character. Avid provides it to bring the feel of analog consoles and tape into an in-the-box workflow.", "practical_application": "An engineer engages the option on the HD mixer and adjusts Drive and Tone per channel, blending in subtle saturation before printing a mix.", "category": "Analog Modeling", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["HEAT", "Saturation", "Harmonic distortion", "Analog modeling", "Pro Tools HD", "Avid Audio Engine"], "common_mistakes": ["Thinking each word describes a separate feature; the full phrase is just the name behind the abbreviation HEAT.", "Overusing Drive so subtle warmth turns into audible distortion.", "Assuming it works on every Pro Tools tier; it is an option for Pro Tools HD/HDX."], "scenario_contexts": ["Explaining to a client what the HEAT abbreviation stands for.", "Applying light saturation across a mix bus-style, channel by channel, before mastering.", "A/B testing the mixer with the option engaged and bypassed."], "formula_symbolic": "", "formula_words": ""}, {"id": "dca61e95-927c-452c-892b-dbc1a583540a", "term": "Hybrid Engine", "definition": "Hybrid Engine is the Avid Pro Tools technology that lets each track switch between hardware DSP processing and native (host CPU) processing within one session. Owned by Avid Technology, it appears on Pro Tools HDX systems and on Pro Tools Carbon, combining low-latency DSP paths with the flexibility and high track counts of native mixing. The general approach — blending DSP-accelerated and host-based processing — is a hybrid processing method.", "plain_english": "The Hybrid Engine is a Pro Tools feature that mixes two kinds of processing. Some tracks run on special DSP hardware for low latency. Others run on your computer for flexibility. You can switch a track between the two. Avid owns the name.", "purpose_function": "It gives engineers low-latency hardware monitoring while recording and full native flexibility while mixing, in the same session. Avid built it for its HDX and Carbon systems.", "practical_application": "On a Carbon or HDX rig, an engineer records through DSP mode for near-zero latency, then mixes the same tracks in native mode with the full plug-in set.", "category": "DSP Processing", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["HDX Hybrid Engine", "HDX Classic Mode", "DSP Mode Safe", "DSP mode", "Native processing", "Low-latency monitoring"], "common_mistakes": ["Assuming the Hybrid Engine removes all latency everywhere; only tracks placed in DSP mode get the low-latency hardware path.", "Forgetting that virtual instruments cannot run in DSP mode.", "Expecting native-only plug-ins to run on the DSP path; they are bypassed in DSP mode."], "scenario_contexts": ["Tracking a band on Carbon with DSP-mode monitoring, then mixing natively.", "Switching a guitar track to DSP mode for a low-latency overdub.", "Using DSP Mode Safe to keep an effects return in native mode."], "formula_symbolic": "", "formula_words": ""}, {"id": "fcea158b-b05f-48e3-9df9-f2679c7f64af", "term": "Pro Tools Sketch", "definition": "Pro Tools Sketch is Avid's non-linear, clip-launching creation tool for arranging audio and MIDI clips in a grid rather than on a fixed timeline. Owned by Avid Technology and introduced with Pro Tools 2023.9, it exists both as the Sketch window inside Pro Tools and as a free companion iPad app, sharing the .ptsketch file format. It applies the generic clip-launching, non-linear session approach used for loop-based composition.", "plain_english": "Pro Tools Sketch is a tool for making music by launching loops and clips. You build ideas in a grid instead of a straight timeline. It works inside Pro Tools and as a free iPad app. Avid owns it, and the clips can move into the normal Pro Tools timeline later.", "purpose_function": "It lets musicians build and try ideas non-linearly, triggering clips and scenes freely before committing to a linear arrangement. Avid added it to support loop-based, improvisational workflows and mobile sketching.", "practical_application": "A producer blocks out a song idea by triggering loops and scenes in Sketch on an iPad, then drags the arrangement into the Pro Tools Edit window to finish it.", "category": "Clip Launching", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Sketch Window", "Scene", "Arrangement", "Clip", "Loop", "Edit window"], "common_mistakes": ["Confusing Pro Tools Sketch with the linear Edit window; Sketch is non-linear and clip-based.", "Assuming clips stay isolated; scenes and whole arrangements can be dragged into the Pro Tools timeline.", "Thinking the iPad app is a separate product; it shares the .ptsketch format and moves projects to Pro Tools."], "scenario_contexts": ["Sketching a beat on the iPad app while travelling, then opening it in Pro Tools.", "Auditioning loop combinations as scenes before arranging a track.", "Dragging a finished Sketch arrangement into the Edit window for detailed mixing."], "formula_symbolic": "", "formula_words": ""}, {"id": "6c4de399-2044-497f-a19c-f4e3c4d1a611", "term": "Sketch Window", "definition": "The Sketch window is the panel inside Pro Tools that hosts the Sketch clip-launching environment: a grid of cells holding audio or MIDI clips organized into scenes and arrangements. Part of Avid's Pro Tools (owned by Avid Technology) from version 2023.9, it lets users trigger looping clips non-linearly and drag scenes or whole arrangements onto the Edit window timeline. It is the in-application view of the broader Pro Tools Sketch feature.", "plain_english": "The Sketch window is the part of Pro Tools that shows the Sketch grid. Each square in the grid holds an audio or MIDI clip. Rows of clips are called scenes, and they play together. You can drag scenes into the normal Pro Tools timeline.", "purpose_function": "It provides the on-screen grid where clips and scenes are triggered and arranged non-linearly inside Pro Tools. It exists so loop-based, non-linear ideas can be built without leaving the main application.", "practical_application": "An engineer opens the Sketch window, fills cells with loops, sequences scenes in the arrangement lane, then drags the result to the Edit window to keep working on it.", "category": "Clip Launching", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Pro Tools Sketch", "Scene", "Arrangement", "Clip", "Edit window", "Loop"], "common_mistakes": ["Confusing the Sketch window with the Edit window; the Sketch window is non-linear and grid-based.", "Leaving Sync off, so clips do not follow the Pro Tools session tempo.", "Assuming content is stuck in the Sketch window; scenes and arrangements can be dragged to the timeline."], "scenario_contexts": ["Populating the Sketch window grid with loops to try song sections.", "Sequencing scenes in the arrangement lane to sketch a song structure.", "Dragging a scene from the Sketch window onto the Edit window timeline."], "formula_symbolic": "", "formula_words": ""}, {"id": "5ecb575e-8cf6-4ac7-8761-9e4489aa5c7e", "term": "AIR Creative Collection", "definition": "The AIR Creative Collection is a bundle of virtual instrument and audio effect plug-ins developed by AIR Music Technology and distributed by Avid Technology for Pro Tools. It includes instruments such as Boom, DB-33, Mini Grand, Structure Free, Vacuum, and Xpand!2, along with a set of 20 effect plug-ins covering choruses, flangers, phasers, reverbs, delays, filters, and distortions.", "plain_english": "This is a free set of software instruments and effects that comes with Pro Tools. Pro Tools is Avid's recording program. The pack includes drums, an organ, a piano, and synths. It also adds effects like reverb, delay, and chorus. Avid owns and supplies the collection.", "purpose_function": "It gives Pro Tools users a ready-made starter set of sounds and effects, so they can compose and mix without buying third-party plug-ins.", "practical_application": "A technician loads an instrument like Xpand!2 or Mini Grand on an instrument track for keyboard parts, or inserts a Creative Collection effect such as Flanger on a mix.", "category": "Plug-in Bundle", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Xpand!2", "Structure Free", "Virtual Instrument", "AAX", "AudioSuite"], "common_mistakes": ["Thinking the Creative Collection is one plug-in rather than a bundle of many separate instruments and effects", "Confusing AIR Music Technology (the developer) with Avid (the distributor and trademark owner)", "Assuming its effects are the same as Pro Tools' built-in EQ III and Dynamics III processors"], "scenario_contexts": ["Building a demo using Boom for drums and Xpand!2 for pads", "Adding a DB-33 tonewheel organ part to a session", "Applying the Non-Linear Reverb effect to a drum bus"], "formula_symbolic": "", "formula_words": ""}, {"id": "1d9343c3-ac0a-4b3c-bf6d-beae6208df76", "term": "Eleven", "definition": "Eleven is a guitar amplifier and speaker-cabinet modeling plug-in for Pro Tools, owned by Avid Technology, available in AAX Native and AudioSuite formats. It digitally emulates the sound of tube guitar amplifiers, cabinets, and microphone choices so a recorded guitar can be shaped without a physical amp.", "plain_english": "Eleven is a software guitar amp made by Avid. It copies the sound of well-known guitar amplifiers and speaker cabinets. You plug a guitar into your computer and pick an amp tone. This gives big guitar sounds without a loud real amp. AAX is Avid's plug-in format.", "purpose_function": "It lets engineers record and reshape electric guitar tones inside the computer, replacing miked amplifiers for tracking or re-amping.", "practical_application": "A technician inserts Eleven on a direct guitar track and chooses an amp and cabinet model to dial in the wanted tone during mixing.", "category": "Amp Modeling Plug-in", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Eleven Rack", "Re-amping", "Convolution", "AAX", "AudioSuite"], "common_mistakes": ["Confusing the Eleven plug-in (software) with Eleven Rack (a hardware unit)", "Printing heavy amp modeling to the recording, leaving no clean direct signal to re-amp later", "Believing Eleven contains the actual branded amps rather than emulations inspired by them"], "scenario_contexts": ["Tracking electric guitar direct and shaping the tone with Eleven", "Re-amping a clean direct take through different Eleven amp models", "Creating consistent guitar tones across overdubs"], "formula_symbolic": "", "formula_words": ""}, {"id": "6b1181c2-2e5d-4927-977d-95a2063e34e1", "term": "Eleven Rack", "definition": "Eleven Rack is a discontinued hardware guitar recording and effects processor from Avid Technology that combines a dual-DSP audio interface with amp, cabinet, and effects modeling. It records dry and processed guitar at once, uses convolution-based cabinet emulations and modeled microphones, and integrates with Pro Tools for re-amping and tone recall.", "plain_english": "Eleven Rack is a hardware box from Avid for recording guitar. It copies the sound of classic amps and speaker cabinets. You plug your guitar into it instead of a real amp. It records both the plain guitar and the processed tone together. That lets you change the amp sound later. It can also process guitar live on stage.", "purpose_function": "It provides studio-quality guitar tones and low-latency processing for recording and live use, and can store its settings inside Pro Tools tracks for recall.", "practical_application": "A technician connects a guitar to Eleven Rack, records a dry and processed signal into Pro Tools, and later re-amps through different models without re-recording.", "category": "Guitar Processor", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Eleven", "Re-amping", "Convolution", "Audio Interface", "DSP"], "common_mistakes": ["Assuming Eleven Rack and the Eleven plug-in are the same product", "Forgetting to capture a dry direct signal, which prevents later re-amping", "Expecting current Pro Tools versions to fully support the discontinued hardware without legacy drivers"], "scenario_contexts": ["Recording guitar with amp modeling through a single interface", "Re-amping a saved dry track through new tones", "Using Eleven Rack as a standalone effects processor for live performance"], "formula_symbolic": "", "formula_words": ""}, {"id": "156c928e-43fc-45d1-8671-368e9a15b225", "term": "GrooveCell", "definition": "GrooveCell is a programmable stereo AAX Native virtual instrument (drum machine) for Pro Tools, owned by Avid Technology. It plays sampled drum and percussion sounds across 16 pads and includes a built-in 16-track, 32-step sequencer that automatically synchronizes with the Pro Tools tempo and meter.", "plain_english": "GrooveCell is a software drum machine from Avid. It plays drum and percussion samples on 16 pads. It has a step sequencer to build beats. The beats follow your song's tempo on their own. You can drag finished patterns into your project. AAX is Avid's plug-in format.", "purpose_function": "It lets producers create and edit drum grooves inside Pro Tools without external hardware, with per-pad sound shaping and built-in effects.", "practical_application": "A technician inserts GrooveCell on an instrument track, programs a beat on the step sequencer, and drags the pattern into the session as MIDI or audio.", "category": "Virtual Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["PlayCell", "SynthCell", "Sonic Drop", "Virtual Instrument", "AAX"], "common_mistakes": ["Moving a session to another computer without the linked sample files, which breaks pad playback", "Confusing GrooveCell (drums and grooves) with SynthCell (synth) or PlayCell (multisample player)", "Forgetting the sequencer follows Pro Tools tempo, then wondering why patterns speed up or slow down"], "scenario_contexts": ["Programming a drum beat for a pop production", "Layering custom samples across pads for a hip-hop groove", "Dragging a GrooveCell pattern into the timeline as MIDI for further editing"], "formula_symbolic": "", "formula_words": ""}, {"id": "bb271e3c-0d06-4b86-bc5b-ea87051f16e6", "term": "PlayCell", "definition": "PlayCell is a stereo AAX Native virtual instrument for Pro Tools, owned by Avid Technology, that plays a factory library of multisampled instruments. It covers drums, pianos, guitars, basses, synths, orchestral, and other sounds, with global macro, amplitude, and filter controls and an on-screen keyboard.", "plain_english": "PlayCell is a software instrument from Avid. It plays recorded sounds of real and electronic instruments. You get pianos, guitars, basses, drums, and synths. You play them from a keyboard or the on-screen keys. Simple knobs let you shape the sound. It is a sample player, not a synthesizer.", "purpose_function": "It gives Pro Tools users a broad, ready-to-play sound library for quickly adding melodic and rhythmic parts to a session.", "practical_application": "A technician loads PlayCell on an instrument track, picks a preset such as a piano or bass, and records a MIDI performance.", "category": "Virtual Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["GrooveCell", "SynthCell", "Sonic Drop", "Virtual Instrument", "MIDI"], "common_mistakes": ["Confusing PlayCell (a multisample player) with SynthCell (a synthesizer)", "Expecting deep synthesis controls when PlayCell mainly plays back samples", "Not installing optional content drops and assuming a preset is missing"], "scenario_contexts": ["Adding a quick piano or bass part to a demo", "Auditioning orchestral sounds for a scoring sketch", "Building a full instrumental using only the PlayCell library"], "formula_symbolic": "", "formula_words": ""}, {"id": "7b0f3a9f-976e-46af-ba2d-015c7ef59d82", "term": "Pro Subharmonic", "definition": "Pro Subharmonic is a bass-enhancement plug-in for Pro Tools and VENUE systems (AAX Native and AudioSuite), owned by Avid Technology, that synthesizes low-frequency content one and two octaves below the source signal. It provides separate Lower, Upper, and Direct gain controls and can track pitch via MIDI to add controlled sub-bass.", "plain_english": "Pro Subharmonic is an Avid effect that adds deep low bass. It creates new tones one and two octaves below the original sound. This makes bass feel bigger and more powerful. You can mix in how much low end you add. An octave is a doubling or halving of pitch.", "purpose_function": "It reinforces or creates deep sub-bass energy in program material when the original recording lacks low-end weight.", "practical_application": "A technician inserts Pro Subharmonic on a kick or bass track, sets the frequency range, and blends in synthesized sub content to add weight.", "category": "Effect Plug-in", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["ReVibe II", "Reel Tape Suite", "Subharmonic", "AAX", "AudioSuite"], "common_mistakes": ["Adding too much sub content, which muddies the mix", "UNSAFE: Driving large amounts of sub-bass at high level can damage loudspeakers and hearing — monitor at safe levels", "Applying it broadband instead of limiting it to the intended low-frequency range"], "scenario_contexts": ["Adding weight to a thin kick drum in a dance mix", "Reinforcing sub-bass for a cinematic sound effect", "Strengthening a bass guitar that lacks low end on small speakers"], "formula_symbolic": "", "formula_words": ""}, {"id": "a74a09e8-1997-4309-9f92-fe5774c36d29", "term": "ReVibe II", "definition": "ReVibe II is an algorithmic reverberation plug-in for Pro Tools (AAX Native and AudioSuite) and VENUE systems, owned by Avid Technology. It models acoustic spaces using selectable room types and provides detailed control of early reflections, decay time, and frequency-dependent decay through its decay EQ and decay color graphs.", "plain_english": "ReVibe II is a reverb effect from Avid. Reverb is the echo and tail you hear in a room. This plug-in builds those room sounds using math, not recordings. You pick a room type and set how long the tail lasts. It makes dry recordings sound like a real space.", "purpose_function": "It creates realistic or creative spatial ambience, letting engineers place dry tracks in a convincing acoustic environment.", "practical_application": "A technician sets up ReVibe II on an effects send, chooses a room type, and adjusts decay to add depth to vocals or drums.", "category": "Reverb Plug-in", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Pro Subharmonic", "Reel Tape Suite", "Reverb", "AAX", "AudioSuite"], "common_mistakes": ["Confusing ReVibe II (algorithmic reverb) with convolution reverbs that use recorded impulse responses", "Inserting the reverb directly on a track instead of using an effects send with a wet/dry blend", "Setting decay times too long, which washes out the mix"], "scenario_contexts": ["Adding hall ambience to a lead vocal", "Creating a short room sound on a drum bus", "Designing a large reverb for a film ambience"], "formula_symbolic": "", "formula_words": ""}, {"id": "20e4d4ee-5174-4b73-bd8e-45ecbc063304", "term": "Reel Tape Suite", "definition": "Reel Tape Suite is a set of analog-tape emulation plug-ins for Pro Tools (AAX Native and AudioSuite), owned by Avid Technology, comprising Reel Tape Saturation, Reel Tape Delay, and Reel Tape Flanger. It models the harmonic saturation, tape-based delay/echo, and tape flanging behavior of reel-to-reel tape machines.", "plain_english": "Reel Tape Suite is a group of Avid effects that copy old tape recorders. Recording to tape adds warmth and gentle distortion. The suite has three tools. One adds tape warmth. One makes tape echo. One makes a swirling flange sound.", "purpose_function": "It recreates the sonic character of analog tape — saturation, delay, and flanging — for warmth and vintage effects in a digital session.", "practical_application": "A technician inserts Reel Tape Saturation on a drum bus for gentle warmth, or Reel Tape Delay on a vocal for tape-style echo.", "category": "Tape Emulation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["ReVibe II", "Pro Subharmonic", "Saturation", "AAX", "AudioSuite"], "common_mistakes": ["Overdriving the saturation stage until the track sounds harsh instead of warm", "Treating the three plug-ins as one when they are separate saturation, delay, and flanger tools", "Expecting exact modeling of one specific named tape machine"], "scenario_contexts": ["Warming up a digital drum bus with tape saturation", "Creating vintage slap-back echo on vocals", "Adding tape flange to a guitar or synth"], "formula_symbolic": "", "formula_words": ""}, {"id": "e2e3ddd8-97a9-4239-bc8b-89295735e2bd", "term": "Sonic Drop", "definition": "Pro Tools | Sonic Drop is Avid Technology's ongoing content program that delivers free samples, loops, and instrument presets to Pro Tools users on a regular (monthly) basis. Much of the content is designed for Avid's Cell instruments, such as PlayCell, GrooveCell, and SynthCell.", "plain_english": "Sonic Drop is a free content program from Avid for Pro Tools. Each month it gives users new sounds. These include samples, loops, and instrument presets. Many are made for the Cell instruments like PlayCell and GrooveCell. Producers use them to get fresh sounds at no extra cost.", "purpose_function": "It regularly expands the Pro Tools sound library at no extra cost, keeping the bundled instruments supplied with new, ready-to-use content.", "practical_application": "A technician downloads the latest Sonic Drop, then loads its presets and loops into GrooveCell or PlayCell to start a track quickly.", "category": "Content Library", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["PlayCell", "GrooveCell", "SynthCell", "Virtual Instrument", "Loop"], "common_mistakes": ["Thinking Sonic Drop is a plug-in rather than a downloadable content program", "Assuming the content is paid when it is provided free to Pro Tools users", "Not downloading new drops and missing the added presets and loops"], "scenario_contexts": ["Loading a monthly Sonic Drop preset pack into SynthCell", "Starting a beat from Sonic Drop loops in GrooveCell", "Browsing new sample content to spark ideas"], "formula_symbolic": "", "formula_words": ""}, {"id": "e6d29b19-40b6-47c2-bcce-1072a437bb8a", "term": "SynthCell", "definition": "SynthCell is a programmable stereo AAX Native virtual instrument for Pro Tools, owned by Avid Technology, based on subtractive synthesis. It uses two oscillators feeding two filters, with an 8x8 modulation matrix, dual ADSR envelopes, an LFO, an arpeggiator, and built-in effects, and offers up to 32-voice polyphony.", "plain_english": "SynthCell is a software synthesizer from Avid. A synthesizer makes sounds electronically instead of recording them. It starts with basic waveforms and shapes them with filters. You can build basses, leads, and pads. It has an arpeggiator that plays patterns from held notes. AAX is Avid's plug-in format.", "purpose_function": "It gives Pro Tools users a flexible synthesizer for designing original electronic sounds and sequenced parts.", "practical_application": "A technician loads SynthCell on an instrument track, edits the oscillators and filters to design a bass or lead, and records a MIDI part.", "category": "Virtual Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["PlayCell", "GrooveCell", "Sonic Drop", "Subtractive Synthesis", "AAX"], "common_mistakes": ["Confusing SynthCell (a synthesizer) with PlayCell (a sample player)", "Expecting sampled acoustic instruments when SynthCell generates sound from oscillators", "Overloading the modulation matrix so the patch becomes unstable or noisy"], "scenario_contexts": ["Designing a synth bass for an electronic track", "Creating an evolving pad with the modulation matrix", "Using the arpeggiator to generate a rhythmic sequence"], "formula_symbolic": "", "formula_words": ""}, {"id": "37f6b05b-e420-4c6c-97f0-0c532ee1a951", "term": "Xpand!2", "definition": "Xpand!2 is a multitimbral workstation virtual instrument developed by AIR Music Technology and distributed by Avid Technology, available in AAX Native and other plug-in formats. It layers up to four independent parts, each loading a patch from a large built-in sound library, and adds Smart Knob macro controls, an arpeggiator, and built-in effects.", "plain_english": "Xpand!2 is a software instrument from Avid. It can play up to four different sounds at once. You pick a sound for each of its four slots. Together they make rich, layered patches. Simple Smart Knobs change the sound fast. It is part of the free Creative Collection.", "purpose_function": "It provides a large, easy-to-use palette of ready-made and layered sounds for quick composition and sound design in Pro Tools.", "practical_application": "A technician loads Xpand!2, browses to a layered pad or bass patch, tweaks the Smart Knobs, and records a MIDI part.", "category": "Virtual Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["AIR Creative Collection", "Structure Free", "Virtual Instrument", "AAX", "MIDI"], "common_mistakes": ["Assuming each patch is a single sound when Xpand!2 can stack up to four parts", "Overlooking the Smart Knobs, which are the quickest way to reshape a patch", "Confusing Xpand!2 with a sampler that lets you import your own samples"], "scenario_contexts": ["Adding a layered pad to a song sketch", "Using Xpand!2 as a general-purpose sound source for demos", "Assigning Smart Knobs to automate timbre changes"], "formula_symbolic": "", "formula_words": ""}, {"id": "5292866d-a112-40e0-bdbc-052f7ddb37a4", "term": "Attention Expand Zone", "definition": "On the Avid S4/S6 control surface, an Attention Expand Zone is one or more channel-strip Knob Modules configured to display and control the parameters of the currently attentioned (focused) track. It spreads that single track's knob functions across a bank of physical strips, so many of its controls appear at once without paging. It is a proprietary feature of Avid Technology's EUCON surfaces.", "plain_english": "The S4 and S6 are large Avid mixing surfaces. One track is always in focus, called the attentioned track. An Attention Expand Zone is a set of knob strips set aside for that focused track. It spreads the track's controls across several strips. This lets you see and adjust more of one track at once.", "purpose_function": "It lets an engineer edit many parameters of one focused track at the same time, instead of scrolling through pages of controls on a single strip.", "practical_application": "A mixer assigns a row of Knob Modules as an Attention Expand Zone so the attentioned track's EQ, dynamics, and sends all stay visible and adjustable together.", "category": "S4/S6 Console", "difficulty": "intermediate", "achievement_id": "285a21d4-9d43-4c4a-a93b-64bce7ca7d7d", "cross": [], "related_terms": ["Attention Fader", "EuControl", "Master Touch Module", "Avid S6", "Control Surface", "EUCON"], "common_mistakes": ["Confusing an Attention Expand Zone with ordinary channel strips; the zone always follows the attentioned track, not a fixed channel.", "assuming it is a software plugin; it is a hardware configuration of the S4/S6 surface", "forgetting that changing which track is attentioned instantly changes what the zone controls"], "scenario_contexts": ["Detailed mix of a lead vocal where the engineer wants EQ, compression, and sends on one focused track at once.", "post-production dialogue editing on an S6 with a dedicated zone following the focused track", "teaching a new operator how a focused track's controls spread across the surface"], "formula_symbolic": "", "formula_words": ""}, {"id": "eb0cfd15-13b3-4532-b9b6-acdd2c582541", "term": "Attention Fader", "definition": "A motorized fader that always controls the currently attentioned (focused) track. On the Avid S4/S6 it is the Attention Track Fader on the Master Automation Module, with record, input, solo, and mute status indicators; in the Avid Control app the equivalent floating \"Att Fader\" gives level control of the selected channel from any view. It is a proprietary feature of Avid Technology's EUCON control systems.", "plain_english": "On an Avid surface, one track is always in focus, called the attentioned track. The Attention Fader is a motor-driven slider tied to that focused track. Whichever track you focus on, this fader controls its volume. You do not have to hunt for the track's own fader.", "purpose_function": "It gives a single, always-available fader for the focused track, so an engineer can ride its level no matter which bank of channels is shown on the surface.", "practical_application": "An engineer taps a track to attention it, then rides its level on the Attention Fader while the other faders stay on their assigned channels.", "category": "S4/S6 Console", "difficulty": "intermediate", "achievement_id": "285a21d4-9d43-4c4a-a93b-64bce7ca7d7d", "cross": [], "related_terms": ["Attention Expand Zone", "EuControl", "Avid Control", "Master Touch Module", "EUCON", "Control Surface"], "common_mistakes": ["Thinking the Attention Fader is a master or monitor fader; it follows the focused track, not the main output.", "forgetting that its position updates whenever a different track is attentioned", "confusing the S4/S6 Attention Track Fader with the Avid Control app's floating Att Fader; they are the same idea on different hardware"], "scenario_contexts": ["Riding a solo instrument's level during a mix by attentioning that track.", "quickly adjusting whichever track is selected during editing without reaching across the surface", "using the Avid Control tablet app to grab a floating fader for the selected channel"], "formula_symbolic": "", "formula_words": ""}, {"id": "3db8ca4f-0236-4983-b1cb-8565307d0471", "term": "Avid Control", "definition": "Avid Control is a tablet and phone application (iOS and Android) that turns the device into a EUCON control surface for Pro Tools and other EUCON-aware applications such as Logic Pro, Cubase, and Nuendo. It offers Mixer, Tracks, Channel, Soft Keys, Meters, and Monitoring views for controlling channel levels, solo, mute, transport, inserts, panning, and automation. It requires EuControl software on the workstation and communicates over Wi-Fi or Ethernet. It is a trademark of Avid Technology (formerly Pro Tools | Control).", "plain_english": "Avid Control is an app for tablets and phones. It turns your device into a remote control for audio software like Pro Tools. You can move faders, mute, solo, and start playback from the screen. It talks to your computer over Wi-Fi using Avid's EUCON control system.", "purpose_function": "It gives engineers hands-on, wireless control of a digital audio workstation without a large hardware console, and can also extend Avid hardware surfaces.", "practical_application": "An engineer places a tablet running Avid Control near the recording position to adjust levels and run transport while away from the computer keyboard.", "category": "Control App", "difficulty": "intermediate", "achievement_id": "285a21d4-9d43-4c4a-a93b-64bce7ca7d7d", "cross": [], "related_terms": ["EuControl", "EUCON", "Avid Control Desktop", "Attention Fader", "Avid S1", "Control Surface"], "common_mistakes": ["Thinking it works without EuControl installed on the computer; the workstation must run EuControl.", "assuming it uses MIDI; it uses the EUCON Ethernet protocol over the network", "confusing the mobile Avid Control app with the computer-based Avid Control Desktop"], "scenario_contexts": ["Tracking a musician while controlling Pro Tools from a tablet in the live room.", "adjusting a monitor mix from across the studio", "using a phone as a simple transport and level remote for a EUCON-aware DAW"], "formula_symbolic": "", "formula_words": ""}, {"id": "1bb6b600-7094-47b3-b0a3-74f9398a823a", "term": "Avid Control Desktop", "definition": "Avid Control Desktop is a macOS and Windows desktop application that provides Meters and Soft Keys display for an associated Avid S1 (like a linked Avid Control app) and Meters display for an Avid S3. It can show up to 32 tracks and be stretched across multiple monitors, runs in Meters mode, and cannot operate standalone (it requires one or more S1s or an S3). It is part of Avid's EUCON/EuControl ecosystem and a trademark of Avid Technology.", "plain_english": "Avid Control Desktop is a computer app for Mac and Windows. It shows meters and soft keys on your screen instead of on a tablet. It works alongside Avid's S1 or S3 hardware. It can show up to 32 tracks across several monitors. On its own it does not control the mix; it needs the S1 or S3 hardware.", "purpose_function": "It adds large on-screen metering and soft-key displays for S1 or S3 users who want that information on computer monitors rather than a tablet.", "practical_application": "An S1 user opens Avid Control Desktop to see wide, multi-monitor metering for up to 32 tracks while mixing.", "category": "Control App", "difficulty": "intermediate", "achievement_id": "285a21d4-9d43-4c4a-a93b-64bce7ca7d7d", "cross": [], "related_terms": ["Avid Control", "EuControl", "EUCON", "Avid S1", "Master Touch Module", "Control Surface"], "common_mistakes": ["Expecting it to control a DAW on its own; it needs an S1 or S3 and runs in Meters mode.", "confusing it with the mobile Avid Control app, which can run standalone", "assuming it replaces hardware faders; it is a display companion, not a fader controller"], "scenario_contexts": ["Showing large metering across two monitors while working on an Avid S1.", "adding a meter-bridge view for an S3 without extra hardware", "a post suite using on-screen soft keys alongside an S1 surface"], "formula_symbolic": "", "formula_words": ""}, {"id": "c736e966-82f6-4250-8646-cc466a4ad9fc", "term": "EuControl", "definition": "EuControl is Avid software that lets a workstation computer find, link, and communicate with EUCON control surfaces - including the Avid Control app, Avid Dock, S1, S3, and Artist Series - and configure and assign them to applications. It uses EUCON, an Ethernet-based control protocol that originated with Euphonix, which Avid acquired in 2010. EuControl and EUCON are trademarks of Avid Technology.", "plain_english": "EuControl is Avid software that runs on your computer. It finds Avid control surfaces on the network and links them to your audio software. It also lets you set up and assign those surfaces. It uses a system called EUCON to send control messages over Ethernet. EUCON came from a company named Euphonix, which Avid bought.", "purpose_function": "It acts as the bridge between Avid EUCON hardware and the workstation, handling discovery, connection, and configuration so surfaces can control the software.", "practical_application": "An engineer installs EuControl, opens it to confirm the S1 or Avid Control app is connected, and assigns which application the surface controls.", "category": "Control Software", "difficulty": "intermediate", "achievement_id": "285a21d4-9d43-4c4a-a93b-64bce7ca7d7d", "cross": [], "related_terms": ["EUCON", "Avid Control", "Avid Control Desktop", "Avid S1", "Artist Series", "Control Surface"], "common_mistakes": ["Thinking a surface works without EuControl running; the software must be installed and active.", "confusing EuControl (the software) with EUCON (the protocol it uses)", "assuming EUCON is MIDI; it is a separate Ethernet-based control protocol"], "scenario_contexts": ["Setting up a new Avid S1 and confirming it appears in EuControl.", "assigning a control surface to Pro Tools versus another EUCON-aware application", "troubleshooting why a surface is not linking to the workstation"], "formula_symbolic": "", "formula_words": ""}, {"id": "7c740603-6fee-4bd9-a958-9a78990a69c0", "term": "Master Touch Module", "definition": "The Master Touch Module (MTM) is the central master-section module of the Avid S4/S6 control surface. It has a tilting 12.1-inch multipoint touchscreen, eight rotary encoders, and dedicated knobs and keys for monitoring and global control, letting an operator view, access, and edit tracks, processing, and metering without a mouse. (Avid's S4/S6 software guide also refers to this touchscreen hub as the Master Module.) It is a trademark of Avid Technology.", "plain_english": "The Master Touch Module, or MTM, is the main control panel of Avid's S4 and S6 mixing surfaces. It has a large 12-inch touchscreen you can tilt. Around it are knobs and buttons for monitoring and overall control. You use it to see and change tracks, effects, and meters by touch instead of by mouse.", "purpose_function": "It serves as the surface's central hub, giving touchscreen access to mix parameters and monitoring so the engineer does not have to work through computer menus.", "practical_application": "An engineer uses the MTM touchscreen to select tracks, check metering, and set monitoring levels while mixing on an S6.", "category": "S4/S6 Console", "difficulty": "intermediate", "achievement_id": "285a21d4-9d43-4c4a-a93b-64bce7ca7d7d", "cross": [], "related_terms": ["Attention Fader", "Attention Expand Zone", "EuControl", "Avid S6", "EUCON", "Control Surface"], "common_mistakes": ["Confusing the Master Touch Module with the Master Automation Module, which holds the transport and Attention Track Fader.", "assuming every S6 is identical; the surface is modular and module counts vary", "thinking the touchscreen replaces the computer display; it complements the DAW rather than replacing it"], "scenario_contexts": ["Checking full-mix metering on the MTM during a music mix.", "setting monitor and talkback controls from the master section in a post suite", "selecting and editing a track's processing by touch on the S6"], "formula_symbolic": "", "formula_words": ""}, {"id": "6b3f5c2c-e068-40d4-80e7-d4e05a8b6db5", "term": "Avid Cloud Collaboration", "definition": "Avid Cloud Collaboration is a proprietary feature of Avid's Pro Tools digital audio workstation, first introduced in Pro Tools 12.5, that lets multiple users share and work on the same project through cloud-hosted storage. The project is kept on Avid's cloud servers with a local cache, and invited collaborators can exchange tracks, edits, and messages remotely. The underlying idea is generic cloud-based project sharing; the trademark and service belong to Avid Technology.", "plain_english": "Avid Cloud Collaboration lets people work on the same Pro Tools project from different places. The project lives on internet servers, not just one computer. You invite others to join, and they can add or change tracks. It works like a shared online folder built into the recording software.", "purpose_function": "It exists so engineers, producers, and musicians can work on the same recording session remotely without physically shipping session files. It manages cloud storage, track sharing, and change tracking inside Pro Tools.", "practical_application": "A technician uses it to invite a remote collaborator into a Pro Tools project, share selected tracks, and pull down the other person's edits over the internet.", "category": "Avid Ecosystem", "difficulty": "intermediate", "achievement_id": "681cb58c-4a8b-470d-b37c-f9d1ca124c01", "cross": [], "related_terms": ["Pro Tools", "Avid Link", "Digital Audio Workstation (DAW)", "Session (Pro Tools)", "Cloud Storage", "Track"], "common_mistakes": ["Confusing cloud Projects with local Sessions; the two formats store and share data differently.", "Assuming unlimited collaborators; free-tier storage and project limits cap how many people can join.", "Believing files transfer instantly regardless of connection; low internet bandwidth slows syncing."], "scenario_contexts": ["A producer in one city shares a Pro Tools project with a mixing engineer in another to trade revisions.", "A band member records overdubs at home and uploads tracks for the studio engineer to review.", "A remote session where two collaborators chat and swap tracks inside Pro Tools."], "formula_symbolic": "", "formula_words": ""}, {"id": "b67af58c-974c-4651-accc-8542c0276eb6", "term": "Avid Complete Plugin Bundle", "definition": "The Avid Complete Plugin Bundle is a proprietary software package from Avid Technology that provides access to Avid's full collection of audio plug-ins, delivered on a subscription basis. The plug-ins use Avid's AAX (Avid Audio eXtension) format and cover common processing categories such as equalization, dynamics, reverb, delay, and virtual instruments. It runs in Pro Tools and other AAX-compatible hosts; the bundle name is proprietary, while the individual processors implement generic audio-effect and instrument concepts.", "plain_english": "The Avid Complete Plugin Bundle gives you all of Avid's audio plug-ins in one paid subscription. A plug-in is a small tool that adds an effect, like reverb, echo, or tone control. This package includes many of them for use inside Pro Tools. You pay a regular fee to keep using them.", "purpose_function": "It exists to give Pro Tools users one licensed set of mixing, mastering, and instrument plug-ins from Avid instead of buying each title separately.", "practical_application": "A technician subscribes to the bundle to obtain Avid's equalizers, compressors, reverbs, and instruments, then inserts them on tracks while mixing in Pro Tools.", "category": "Avid Ecosystem", "difficulty": "intermediate", "achievement_id": "681cb58c-4a8b-470d-b37c-f9d1ca124c01", "cross": [], "related_terms": ["AAX (Avid Audio eXtension)", "Pro Tools", "Plug-in", "Virtual Instrument", "Equalizer (EQ)", "Dynamics Processor"], "common_mistakes": ["Assuming the plug-ins work in any DAW; they need an AAX-compatible host such as Pro Tools.", "Thinking a subscription grants permanent ownership; access ends when the subscription lapses.", "Confusing the paid Complete Bundle with the smaller plug-in set already included with Pro Tools."], "scenario_contexts": ["An engineer subscribes to get a full palette of Avid effects for a mix session.", "A studio standardizes on the bundle so every Pro Tools workstation carries the same plug-ins.", "A user adds Avid instruments and effects to a Pro Tools project through the bundle."], "formula_symbolic": "", "formula_words": ""}, {"id": "064f0fb9-2eb9-42d2-961d-92477009d73a", "term": "Avid Inner Circle", "definition": "Avid Inner Circle (Pro Tools Inner Circle) is a proprietary loyalty and rewards program run by Avid Technology for Pro Tools subscribers. Enrolled annual subscribers receive periodic benefits such as free or exclusive plug-ins, sound and sample libraries, tutorials, and discounts from Avid partners. It is a subscriber-benefit scheme rather than a piece of software, and rewards are claimed through the user's Avid account.", "plain_english": "Avid Inner Circle is a rewards program for people who pay for a yearly Pro Tools subscription. Members get free extras added over time, like plug-ins, sounds, and training videos. You claim these through your Avid account. It is Avid's way of rewarding loyal subscribers.", "purpose_function": "It exists to add ongoing value for paying Pro Tools subscribers and encourage renewal by bundling extra plug-ins, content, and partner offers.", "practical_application": "A technician who subscribes to Pro Tools signs in to their Avid account to redeem the current Inner Circle plug-ins and content for use in sessions.", "category": "Avid Ecosystem", "difficulty": "intermediate", "achievement_id": "681cb58c-4a8b-470d-b37c-f9d1ca124c01", "cross": [], "related_terms": ["Pro Tools", "Avid Link", "Avid Complete Plugin Bundle", "Subscription License", "Plug-in", "Avid Account"], "common_mistakes": ["Thinking Inner Circle is free for everyone; it requires an eligible paid Pro Tools subscription.", "Assuming perpetual-license owners get the rewards; benefits target active subscribers.", "Missing time-limited rewards by not redeeming them before the offering changes."], "scenario_contexts": ["A subscriber redeems a bundled third-party plug-in offered through Inner Circle.", "A studio factors Inner Circle extras into the value of yearly Pro Tools subscriptions.", "A newly renewed subscriber checks their Avid account for the latest Inner Circle rewards."], "formula_symbolic": "", "formula_words": ""}, {"id": "d2801e0a-dad1-4563-9e5c-aad3dbf5b915", "term": "Avid Link", "definition": "Avid Link is a free proprietary application from Avid Technology that acts as a hub for managing Avid products and connecting with the media-creation community. It lets users activate and manage Avid software licenses and downloads (for products such as Pro Tools, Media Composer, and Sibelius), find and message collaborators, browse a marketplace, and receive product news and notifications. It replaced Avid's earlier Application Manager; the underlying functions of license management and professional networking are generic, while the Avid Link name and service are proprietary.", "plain_english": "Avid Link is a free app from Avid for people who use Avid software. It lets you install and turn on your Avid programs, like Pro Tools. You can also find other creators, send messages, and read news. Think of it as a control panel and a community app in one.", "purpose_function": "It exists to bring license activation, software updates, account management, and community networking into a single free application for Avid users.", "practical_application": "A technician uses Avid Link to activate a Pro Tools license, download updates, and control which computer a subscription runs on.", "category": "Avid Ecosystem", "difficulty": "intermediate", "achievement_id": "681cb58c-4a8b-470d-b37c-f9d1ca124c01", "cross": [], "related_terms": ["Pro Tools", "Media Composer", "Avid Account", "Software License Activation", "Avid Complete Plugin Bundle", "iLok"], "common_mistakes": ["Confusing Avid Link with the older Application Manager; Avid Link installs over and replaces it.", "Thinking Avid Link is a DAW; it manages licenses and community, not audio recording.", "Forgetting to deactivate a license in Avid Link before moving software to a new computer."], "scenario_contexts": ["A new user installs Avid Link to activate and download Pro Tools.", "An engineer deactivates a license in Avid Link before reinstalling on another machine.", "A freelancer uses Avid Link's Find Talent feature to connect with collaborators."], "formula_symbolic": "", "formula_words": ""}, {"id": "797a46af-7841-4588-99b3-0fa95e26f357", "term": "Avid VENUE", "definition": "Avid VENUE is Avid Technology's family of proprietary digital live-sound mixing systems used for concert, theatre, house-of-worship and broadcast work. A VENUE system is modular: a control surface at the mix position, a separate DSP mixing engine, and remote stage-mounted I/O (input/output) racks, all joined over a digital audio network. The first generation (D-Show, Profile, SC48, Mix Rack) has been succeeded by the VENUE | S6L generation.", "plain_english": "Avid VENUE is a brand of digital mixing systems for live shows. Avid Technology owns the name. Instead of one big mixer, the job is split into parts. A control desk sits with the engineer. A separate engine does the sound processing. Boxes on stage handle the microphone inputs. A network links them all together.", "purpose_function": "It provides a scalable, modular platform for mixing many live audio channels, keeping heavy processing in a dedicated engine and the physical inputs near the performers to shorten cable runs.", "practical_application": "A live-sound engineer patches stage sources into the stage racks, then mixes the show from the control surface, recalling snapshots for each song or scene.", "category": "Live Mixing System", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["VENUE | S6L", "E6L", "Stage Rack", "Snapshot", "Digital Live Sound", "Pro Tools"], "common_mistakes": ["Assuming VENUE is a single console; it is a modular system of a surface, an engine and stage racks.", "Confusing the original VENUE platform (Profile, D-Show, SC48) with the newer VENUE | S6L generation.", "Thinking VENUE and Pro Tools are the same product; VENUE is the live system, Pro Tools is Avid's recording software it can link to."], "scenario_contexts": ["Mixing front-of-house for a touring band.", "Running monitors from a second VENUE system sharing the same stage inputs.", "Recording a show to Pro Tools for a later virtual soundcheck."], "formula_symbolic": "", "formula_words": ""}, {"id": "ce1cc9b9-45a2-4e18-b33f-4d5ddd79b6b2", "term": "E6L", "definition": "The E6L is the rack-mounted digital signal-processing (DSP) engine of Avid's VENUE | S6L system, where all audio mixing and processing actually take place; the S6L control surface is only a remote controller for it. It shipped in three tiers - E6L-112, E6L-144 and E6L-192 - whose numbers indicate maximum processing-channel capacity, and it connects to the surface and stage I/O over an AVB (IEEE 802.1 Audio Video Bridging) network. E6L is a trademark of Avid Technology.", "plain_english": "The E6L is the brain of an Avid S6L mixing system. It is a rack unit that does all the actual sound mixing and effects. The control desk just tells it what to do. It comes in three sizes. Bigger numbers, like 112, 144 or 192, mean more channels it can handle. Avid Technology owns the name.", "purpose_function": "It centralises all mixing DSP in one dedicated unit so processing power is separate from the control surface, letting the same surface drive different-sized engines.", "practical_application": "A technician racks the E6L at or near the mix position, connects it to the surface and stage racks over AVB, and picks an engine tier that matches the channel count a show needs.", "category": "Mixing Engine", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["VENUE | S6L", "E6LX", "Stage Rack", "AVB", "DSP", "True Gain"], "common_mistakes": ["Thinking the S6L control surface does the audio processing; the E6L engine does, the surface is only control.", "Assuming all E6L engines are identical; the -112, -144 and -192 differ in channel capacity.", "Confusing the E6L with the newer E6LX, which adds a second network card and higher I/O limits."], "scenario_contexts": ["Specifying an E6L-192 for a large festival with high channel counts.", "Swapping a control surface while keeping the same engine.", "Diagnosing which engine tier a rented S6L system uses."], "formula_symbolic": "", "formula_words": ""}, {"id": "ca0759e5-677e-4817-82cd-c2c572b8b7d8", "term": "E6LX", "definition": "The E6LX is the current (3rd-generation) mixing engine for Avid's VENUE | S6L system, introduced in late 2024 to replace the earlier E6L engines; the flagship model is the E6LX-256. Each E6LX ships with two AVB-192 network cards (original E6L engines had one) and supports up to 256 inputs and up to 160 outputs. E6LX is a trademark of Avid Technology.", "plain_english": "The E6LX is the newest version of the Avid S6L mixing engine. It replaced the older E6L engines in late 2024. It has two network cards instead of one. That lets it handle more inputs and outputs, up to 256 in and 160 out. Avid Technology owns the name.", "purpose_function": "It exists to give the S6L system more input/output capacity and network redundancy than the original E6L engines, while keeping the same modular surface-and-stage-rack architecture.", "practical_application": "A technician spec'ing a new large-format S6L rig chooses an E6LX-256 engine for its higher I/O ceiling and its two network cards.", "category": "Mixing Engine", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["E6L", "VENUE | S6L", "AVB", "Stage Rack", "DSP", "I/O Sharing"], "common_mistakes": ["Assuming E6LX and E6L are interchangeable names; E6LX is the newer 3rd-generation engine with higher limits.", "Overlooking that E6LX carries two AVB network cards, not one.", "Thinking the added capacity comes from the control surface rather than the engine."], "scenario_contexts": ["Upgrading an older E6L rig to an E6LX-256 for a bigger tour.", "Planning a redundant AVB network using the engine's two cards.", "Confirming a target of up to 256 inputs is within the E6LX spec."], "formula_symbolic": "", "formula_words": ""}, {"id": "88ad3638-a168-4630-8f06-11b36812a85a", "term": "True Gain", "definition": "True Gain is Avid's name for the input-gain architecture on VENUE | S6L Stage I/O racks that lets up to three S6L systems share the same physical microphone preamps while each system retains distributed (independent) ownership of the input's gain, with real-time gain tracking between systems. So a front-of-house and a monitor system can feed from one preamp without a gain change on one desk upsetting the other. True Gain is a proprietary Avid Technology feature; the underlying idea is shared-preamp gain compensation.", "plain_english": "True Gain is Avid's way of handling microphone input levels on S6L stage boxes. Up to three mixing systems can share the same stage preamps. So the front-of-house engineer can raise their own gain without changing the monitor engineer's level. Each system keeps its own setting for the shared mic. Avid Technology owns the name.", "purpose_function": "It exists so multiple consoles can safely share one set of stage preamps, letting each engineer control input level without a gain change on one system disrupting mixes on another.", "practical_application": "On a show where separate front-of-house and monitor S6L systems share Stage 64 inputs, engineers rely on True Gain so each desk keeps control of its own input levels.", "category": "Input Gain", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["True Gain Automation", "Stage Rack", "I/O Sharing", "VENUE | S6L", "Gain", "Preamp"], "common_mistakes": ["Assuming a gain change on one shared system always changes every system's level; True Gain gives each system its own gain ownership.", "Confusing True Gain (an input-gain scheme) with output or fader levels.", "Thinking a single console must own the preamp for all users of a shared input."], "scenario_contexts": ["Sharing Stage 64 preamps between front-of-house and monitor S6L systems.", "Setting input gains at monitors without changing the FOH engineer's levels.", "Planning an I/O-sharing setup across two or three S6L systems."], "formula_symbolic": "", "formula_words": ""}, {"id": "59cc871d-c52b-4d99-ba36-5b5fae77395e", "term": "True Gain Automation", "definition": "True Gain Automation refers to the VENUE | S6L snapshot (scene-recall) system storing and recalling each input's True Gain value, so input-gain settings travel with the show as snapshots are recalled. Because gain is part of the automation data, different gain settings can be recalled per song or scene, and selected inputs can be made 'safe' so their gain is not overwritten. It is a proprietary Avid Technology feature built on standard scene-recall (snapshot) automation.", "plain_english": "True Gain Automation lets an Avid S6L save and recall input gain settings with its scene snapshots. Snapshots store settings for each song or scene. With this, the input gains can change automatically as you move through a show. You can also lock certain inputs so their gain does not change. Avid Technology owns the name.", "purpose_function": "It exists so input gain can be part of automated scene recall, letting gain follow the show rather than being reset by hand for every song or scene.", "practical_application": "A theatre engineer stores different input gains in each snapshot so radio-mic levels recall correctly scene to scene, marking shared inputs safe where needed.", "category": "Input Gain", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["True Gain", "Snapshot", "VENUE | S6L", "Stage Rack", "Scene Recall", "I/O Sharing"], "common_mistakes": ["Forgetting to make shared inputs safe, so a recalled snapshot changes gain that another system depends on.", "Assuming gain is never automated; True Gain can be stored and recalled in snapshots.", "Confusing recalled input gain with fader automation, which is a separate parameter."], "scenario_contexts": ["Recalling per-scene input gains in a musical-theatre show.", "Protecting a shared preamp from snapshot gain changes with a safe.", "Building a snapshot list where each song has its own input gains."], "formula_symbolic": "", "formula_words": ""}, {"id": "4c331e8a-7472-493c-bae3-19756fe1f0d8", "term": "VENUE Link", "definition": "VENUE Link is Avid's communication protocol that connects a VENUE | S6L system to a Pro Tools computer over the same Ethernet link used for Pro Tools AVB (Network Port C on the surface). With it enabled, the S6L can auto-create Pro Tools sessions with tracks named and routed from the show file, control the Pro Tools transport from the surface, and link VENUE snapshots to Pro Tools markers - the backbone of the integrated virtual-soundcheck workflow. VENUE Link is proprietary to Avid Technology.", "plain_english": "VENUE Link is a connection between an Avid S6L mixer and Pro Tools recording software. It uses one network cable between them. It can build a Pro Tools session automatically, with tracks named to match your channels. You can also run Pro Tools play and record from the mixer. Avid Technology owns the name.", "purpose_function": "It ties the live console and Pro Tools together so recording, playback and virtual soundcheck can be set up and driven from the surface instead of managing two systems by hand.", "practical_application": "An engineer enables VENUE Link to auto-create a matching Pro Tools session, records the show, then plays it back through the console for a virtual soundcheck.", "category": "Recording Integration", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Pro Tools", "Virtual Soundcheck", "VENUE | S6L", "AVB", "Snapshot", "Live Recording"], "common_mistakes": ["Thinking VENUE Link carries the audio; audio travels over Pro Tools AVB, while VENUE Link is the control protocol sharing that connection.", "Forgetting to enable VENUE Link, then wondering why tracks are not auto-created or named.", "Confusing VENUE Link with the network cabling itself."], "scenario_contexts": ["Auto-generating a named Pro Tools session before a multitrack recording.", "Controlling the Pro Tools transport from the S6L during virtual soundcheck.", "Linking snapshots to Pro Tools markers for aligned playback."], "formula_symbolic": "", "formula_words": ""}, {"id": "e6f2d361-91cf-4c2a-827b-73963b57bef0", "term": "VENUE On-Stage", "definition": "VENUE | On-Stage is Avid's iOS app for iPad and iPhone that lets a performer remotely control their own monitor mix on a VENUE | S6L system - adjusting the master level, and the level and pan of each member channel feeding a selected aux monitor mix or the mains. It is a personal monitor-mixing remote and is proprietary to Avid Technology.", "plain_english": "VENUE On-Stage is an Avid app for iPad and iPhone. It lets a performer adjust their own monitor mix from the stage. They can set the overall level, and the level and position of each instrument or voice in the mix. It talks to an Avid S6L system over a network. Avid Technology owns the name.", "purpose_function": "It exists to let performers tweak their own aux/monitor mixes wirelessly, freeing the monitor engineer and giving each musician control of what they hear.", "practical_application": "A singer uses the app on an iPad to raise their own vocal and lower the guitar in their in-ear monitor mix during soundcheck.", "category": "Monitor Control App", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["VENUE | S6L", "Aux Send", "Monitor Mix", "In-Ear Monitors", "VENUE Standalone Software"], "common_mistakes": ["Thinking it is a full remote for the whole console; it controls level and pan for a selected aux/monitor mix, not front-of-house mixing.", "Assuming it works without a wireless network linking the iPad or iPhone to the system.", "Confusing per-performer monitor control with mixing the main house sound."], "scenario_contexts": ["A musician setting their own in-ear mix from the stage.", "Several performers each adjusting their own aux monitor mixes.", "Offloading simple monitor tweaks from the monitor engineer during a show."], "formula_symbolic": "", "formula_words": ""}, {"id": "50fad79d-8946-4829-9638-fe0f0fba7ee1", "term": "VENUE Standalone Software", "definition": "VENUE Standalone Software is Avid's free offline version of the VENUE | S6L software that runs on a Windows computer (or a Mac running Windows), letting engineers build and edit show files, presets, snapshots and events, and learn the interface away from the hardware. Because it has no audio hardware, it cannot pass real-time audio; it is for preparation and training only. It is proprietary to Avid Technology.", "plain_english": "VENUE Standalone Software is a free Avid program for a regular computer. It runs the S6L mixing software without the mixer hardware. You can build and edit your show files, snapshots and settings ahead of time. You can also learn the layout. It cannot play real sound, because that needs the actual hardware. Avid Technology owns the name.", "purpose_function": "It lets engineers prepare shows and practise the interface offline, so setup time on the real system is shorter.", "practical_application": "An engineer builds and names channels, patches and snapshots at home in the standalone software, then loads that show file onto the S6L at the venue.", "category": "Offline Software", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["VENUE | S6L", "Show File", "Snapshot", "Preset", "Offline Editing"], "common_mistakes": ["Expecting to hear audio in the standalone software; it cannot pass real-time audio without the hardware.", "Assuming it needs a paid licence; it is a free download.", "Thinking a show built offline cannot transfer; show files move to the real system."], "scenario_contexts": ["Pre-building a show file and snapshots before load-in.", "Training a new engineer on the interface without a console.", "Editing a saved show file on a laptop between gigs."], "formula_symbolic": "", "formula_words": ""}, {"id": "1e7011ed-47a9-424a-a295-0e87113890fa", "term": "VENUE | S6L", "definition": "VENUE | S6L is Avid's current-generation modular digital live-sound mixing system, built from three main parts: an S6L control surface at the mix position, a separate E6LX or E6L DSP engine that does all the processing, and one or more Stage I/O racks (Stage 64/48/32/16) near the sources. The parts connect over an AVB (IEEE 802.1 Audio Video Bridging) Ethernet network, and up to three systems can share stage I/O. VENUE | S6L is a trademark of Avid Technology.", "plain_english": "VENUE S6L is Avid's modern live-sound mixing system. It has three main parts. A control desk sits with the engineer. A separate engine does all the sound processing. Stage boxes near the band handle the inputs. A network cable links them. Up to three systems can share the same stage boxes. Avid Technology owns the name.", "purpose_function": "It provides a scalable, fully modular live-mixing platform where the surface, processing engine and I/O are separate, so each can be sized and shared to fit the production.", "practical_application": "A touring engineer runs front-of-house on an S6L surface driven by an E6LX engine, with Stage 64 racks on stage feeding the show over AVB.", "category": "Live Mixing System", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Avid VENUE", "E6L", "E6LX", "Stage Rack", "AVB", "True Gain"], "common_mistakes": ["Treating the S6L surface as the whole system; the engine and stage racks are separate, required parts.", "Assuming any surface only works with one engine; S6L systems are modular and mix-and-match.", "Confusing the AVB audio network with the separate ECx Ethernet control network."], "scenario_contexts": ["Building a front-of-house rig from a surface, an E6LX engine and Stage 64.", "Sharing stage I/O between front-of-house and monitor S6L systems.", "Networking the surface, engine and stage racks over redundant AVB rings."], "formula_symbolic": "", "formula_words": ""}, {"id": "d4097424-3e3a-446f-a680-9cddde299e4c", "term": "Carbon Expanded", "definition": "Carbon Expanded is Avid Technology's term for a Pro Tools | Carbon system enlarged with one or two Carbon Pre expansion units. Adding the expanders raises the system to as many as 24 microphone/line preamp inputs and 24 line outputs while keeping a single hybrid interface. The name and design are proprietary to Avid; the underlying method is standard preamp and A/D-D/A input/output expansion.", "plain_english": "Carbon is Avid's studio audio interface. Carbon Expanded means you add extra boxes called Carbon Pre to it. This gives you more microphone inputs and outputs. You can grow to about 24 mic inputs for tracking a whole band at once.", "purpose_function": "It lets a Carbon owner add more preamp and analog channels for larger sessions without buying a separate system, sharing one clock and control setup.", "practical_application": "An engineer tracking a full band or a large drum kit adds Carbon Pre units so every microphone has its own preamp and converter channel.", "category": "Audio Interface (Avid)", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Pro Tools | Carbon", "Mic Preamp", "A/D Converter", "DigiLink", "Sample Rate"], "common_mistakes": ["Thinking Carbon Expanded is a separate product rather than a Carbon system fitted with Carbon Pre expanders", "Assuming any interface can expand Carbon; expansion uses Avid's own Carbon Pre units", "Expecting unlimited expansion, when the system supports up to two Carbon Pre units"], "scenario_contexts": ["Tracking a full band live off the floor needing 20-plus microphone inputs", "A growing project studio adding preamp channels as its needs increase", "A drum session needing an individual preamp on every close microphone"], "formula_symbolic": "", "formula_words": ""}, {"id": "f072986e-12c8-41b0-8210-d75a5a54bfdf", "term": "DigiLink", "definition": "DigiLink is Avid Technology's proprietary digital audio connection that links Pro Tools HD/HDX cards or HD Native hardware to Avid audio interfaces. A single DigiLink port carries up to 32 channels of audio in each direction plus embedded clock and control data. It is a proprietary transport; the underlying idea is multichannel digital audio and clock carried over one cable.", "plain_english": "DigiLink is Avid's special cable and connector for Pro Tools systems. It carries up to 32 audio channels each way down one lead. It also sends the clock timing and control signals. It joins the Pro Tools card to the audio interface.", "purpose_function": "It moves many channels of digital audio and clock between the Pro Tools engine and its interfaces over one connector, simplifying wiring in HD and HDX rigs.", "practical_application": "A technician connects an HD I/O or MTRX to a Pro Tools HDX card with a DigiLink cable, then adds more interfaces through the expansion port.", "category": "Digital I/O Interface", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["DigiLink Mini", "Pro Tools | Carbon", "MTRX", "Word Clock", "Sample Rate"], "common_mistakes": ["Confusing DigiLink with generic Ethernet or USB; it is an Avid-proprietary connection", "Forgetting the primary versus expansion port roles when chaining interfaces", "Assuming the 32-channel count holds at all sample rates, when high rates reduce usable channels per port"], "scenario_contexts": ["Wiring a Pro Tools HDX rig to its audio interfaces", "Adding a second HD interface through the expansion port", "Troubleshooting lost audio caused by a bad DigiLink cable or the wrong port"], "formula_symbolic": "", "formula_words": ""}, {"id": "34615c8d-572d-43a0-8933-d7acf91fc7cd", "term": "DigiLink Mini", "definition": "DigiLink Mini is a physically smaller version of Avid Technology's DigiLink connector that carries the same up-to-32-channel bidirectional audio plus clock and control data. It appears on later Avid interfaces such as HD I/O and MTRX, where panel space is limited. Adapters allow DigiLink and DigiLink Mini equipment to interconnect.", "plain_english": "DigiLink Mini is a smaller plug that does the same job as DigiLink. It still carries up to 32 audio channels each way. Newer Avid interfaces use it to save space. Adapters let the older and newer connectors work together.", "purpose_function": "It provides the DigiLink connection in a compact form so newer interfaces can fit more ports, while staying compatible with older DigiLink gear through adapters.", "practical_application": "A technician links an MTRX or HD I/O to an HDX card using a DigiLink Mini cable, or an adapter when joining older DigiLink hardware.", "category": "Digital I/O Interface", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["DigiLink", "MTRX", "MTRX Studio", "Word Clock", "Pro Tools | Carbon"], "common_mistakes": ["Assuming DigiLink and DigiLink Mini plug together directly, when an adapter is needed", "Thinking Mini carries fewer channels; its capacity is the same 32 per port", "Using a cable longer than the rating allows for high sample rates"], "scenario_contexts": ["Connecting an MTRX to a Pro Tools HDX card", "Adapting a legacy DigiLink interface to a Mini port", "Choosing the correct cable length for a 192 kHz session"], "formula_symbolic": "", "formula_words": ""}, {"id": "20e1518d-5e7e-41c8-961b-6db8b422cc41", "term": "Loop Sync", "definition": "Loop Sync is Avid Technology's dedicated word-clock loop used to synchronize multiple Avid HD audio interfaces and peripherals. Devices connect in a daisy chain with 75-ohm BNC cables carrying a 1-5 V, 50%-duty-cycle clock, and the clock master (such as SYNC X) sits as both the first and last unit in the loop. It is a proprietary implementation of standard word-clock distribution.", "plain_english": "Loop Sync is Avid's way to keep several interfaces on the same clock. The boxes connect in a ring using BNC cables. One device acts as the master and closes the loop. This keeps all the audio samples lined up in time.", "purpose_function": "It keeps every interface in a Pro Tools HD system locked to one sample clock, preventing clicks, drift, and timing errors across devices.", "practical_application": "A technician daisy-chains an HD I/O, an HD MADI, and a SYNC X with BNC Loop Sync cables so all the converters share one clock.", "category": "Clock & Synchronization", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Word Clock", "SYNC X", "MTRX", "Sample Rate", "DigiLink"], "common_mistakes": ["Leaving the loop open, when the master must be first and last to close the chain", "Confusing Loop Sync with ordinary word-clock outputs; it is a dedicated loop", "Setting two devices as clock master, which causes conflicts"], "scenario_contexts": ["Clocking a multi-interface Pro Tools HDX rig", "Adding an interface and re-closing the Loop Sync chain", "Diagnosing clicks caused by an open or broken loop"], "formula_symbolic": "", "formula_words": ""}, {"id": "f638f98b-bde6-4977-ab68-c41be1ae1071", "term": "MTRX", "definition": "Pro Tools | MTRX is Avid Technology's modular audio converter, router, and monitor interface for Pro Tools, built on Digital Audio Denmark (DAD) converter technology. The base unit connects to Pro Tools with two 32-channel DigiLink Mini ports (64 channels) and accepts up to eight option cards for mic pre, analog, Dante, MADI, and other I/O, with routing managed in DADman software up to a 1500 x 1500 cross-point matrix. The name is proprietary; the underlying methods are A/D-D/A conversion and matrix routing.", "plain_english": "MTRX is Avid's large, build-to-order audio interface for Pro Tools. You add cards to give it the inputs and outputs you need. It connects to Pro Tools through DigiLink and can route very high channel counts. Software called DADman controls the routing and monitoring.", "purpose_function": "It provides high-quality, expandable conversion, routing, and monitoring for large studios and post facilities that need flexible I/O in one unit.", "practical_application": "A post studio configures an MTRX with AD/DA, Dante, and MADI cards, then routes monitoring and sources in DADman.", "category": "Converter/Interface (Avid)", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["MTRX II", "MTRX Studio", "DigiLink Mini", "Dante", "A/D Converter"], "common_mistakes": ["Thinking MTRX is fixed I/O, when it is modular with up to eight option cards", "Forgetting it needs DADman software for routing and setup", "Assuming DigiLink alone carries all channels, when Dante or MADI cards add more"], "scenario_contexts": ["Building a central converter and router for a post house", "Feeding an immersive monitor system through Pro|Mon", "Bridging Pro Tools, Dante, and MADI in one facility hub"], "formula_symbolic": "", "formula_words": ""}, {"id": "b61c06de-b378-4e39-a25d-52a98e75b385", "term": "MTRX II", "definition": "Pro Tools | MTRX II is the second-generation Avid Technology modular converter, router, and monitor interface for Pro Tools, built on DAD converter and Dante technology. It offers eight option-card slots, 256 channels of integrated Dante, 64 channels of DigiLink over two Mini ports, 64 channels of coaxial MADI, a 4096 x 4096 routing matrix, and a 1024-channel SPQ speaker-EQ engine, all controlled in DADman. The name is proprietary; the methods are A/D-D/A conversion, networked audio, and DSP matrix routing.", "plain_english": "MTRX II is the newer version of Avid's big modular interface. It adds built-in Dante networking and speaker correction. It still uses option cards and connects to Pro Tools through DigiLink. It can route thousands of channels inside one box.", "purpose_function": "It gives large studios and post facilities expanded conversion, networked audio, room correction, and monitoring in a single, configurable unit.", "practical_application": "A dubbing stage uses MTRX II as its clock, converter, and monitor hub, applying SPQ speaker EQ to a calibrated immersive rig.", "category": "Converter/Interface (Avid)", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["MTRX", "MTRX Studio", "Dante", "DigiLink Mini", "A/D Converter"], "common_mistakes": ["Assuming MTRX II and the original MTRX have identical cards and specifications", "Overlooking the built-in Dante and SPQ, which the original MTRX required as options", "Thinking DigiLink alone supplies its 256 Dante channels"], "scenario_contexts": ["Serving as the central hub of an immersive mix stage", "Applying room correction via SPQ on a calibrated monitor system", "Networking many rooms over 256-channel Dante"], "formula_symbolic": "", "formula_words": ""}, {"id": "3509a101-1922-4206-8a19-5456134dc184", "term": "MTRX Studio", "definition": "Pro Tools | MTRX Studio is Avid Technology's fixed-configuration converter and monitor interface for Pro Tools HDX and HD Native, built on DAD converter technology. It provides 2 mic/DI preamps, 16 analog line inputs and 16 line outputs, 2 monitor outputs, 2 headphone outputs, 64x64 Dante, 16 ADAT channels, and two DigiLink Mini ports carrying 64 channels to Pro Tools, plus SPQ speaker EQ and a 512 x 512 routing matrix in DADman. The name is proprietary; the methods are standard A/D-D/A conversion and DSP monitoring.", "plain_english": "MTRX Studio is Avid's ready-made interface for Pro Tools HD systems. It has a fixed set of inputs and outputs, so you do not add cards. It includes converters, Dante networking, and speaker EQ built in. It connects to Pro Tools through DigiLink.", "purpose_function": "It brings much of the MTRX platform's conversion, routing, and monitoring to smaller HDX and HD Native studios in one fixed unit.", "practical_application": "A music mix room uses MTRX Studio for its converters, monitor control, and SPQ speaker calibration, connected to an HDX card by DigiLink Mini.", "category": "Converter/Interface (Avid)", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["MTRX", "MTRX II", "DigiLink Mini", "Dante", "A/D Converter"], "common_mistakes": ["Expecting modular card slots, when MTRX Studio is fixed I/O", "Assuming it has many mic preamps, when it has two", "Ignoring that SPQ and Pro|Mon monitoring need DADman setup"], "scenario_contexts": ["Acting as the converter and monitor hub for a music mix room", "Calibrating monitors with SPQ speaker EQ", "Connecting to HDX or HD Native by DigiLink Mini"], "formula_symbolic": "", "formula_words": ""}, {"id": "ac7e53cf-a2c9-4a7b-8755-e440f80b6c49", "term": "Pro Tools | Carbon", "definition": "Pro Tools | Carbon is Avid Technology's hybrid audio interface for Pro Tools that combines onboard HDX DSP with native (host CPU) processing, connecting to the computer over AVB Ethernet. It provides 8 mic preamps (with variable input impedance on channels 5-8), 2 DI inputs, 8 DB25 line inputs and outputs, monitor and headphone outputs, and 16 ADAT channels, with conversion up to 32-bit/192 kHz. The name and hybrid engine are proprietary; the underlying methods are A/D-D/A conversion, preamp gain staging, and DSP-assisted monitoring.", "plain_english": "Carbon is Avid's studio audio interface for Pro Tools. It mixes special DSP chips with your computer's own power. This lets you record through effects with almost no delay. It has eight microphone inputs and connects over an Ethernet cable.", "purpose_function": "Its hybrid design lets engineers monitor through AAX DSP plug-ins with very low latency while keeping the flexibility of native processing, chosen per track.", "practical_application": "A tracking engineer records vocals through Carbon's preamps and monitors with DSP reverb and compression at near-zero latency.", "category": "Audio Interface (Avid)", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Carbon Expanded", "Mic Preamp", "A/D Converter", "DigiLink", "Sample Rate"], "common_mistakes": ["Thinking Carbon connects by USB or Thunderbolt, when it uses AVB Ethernet", "Confusing its hybrid HDX-plus-native engine with a native-only interface", "Assuming all of its inputs are analog, when several are ADAT digital channels"], "scenario_contexts": ["Recording vocals with near-zero-latency DSP monitoring", "Tracking a band with eight preamps at once", "Switching a track between DSP and native processing"], "formula_symbolic": "", "formula_words": ""}, {"id": "6f4bd95c-6cc3-48d4-9159-955dea6d3f0f", "term": "SYNC X", "definition": "Pro Tools | SYNC X is Avid Technology's master clock and synchronization peripheral for Pro Tools HDX and HD Native systems. It generates and locks to references including internal clock, word clock over 75-ohm BNC, Loop Sync, video/tri-level and black-burst, 10 MHz, AES3/AES3id, and LTC timecode, and it can generate LTC and MIDI Time Code together plus offer Variable Speed Override. The name is proprietary; the underlying methods are standard word-clock, video-reference, and timecode synchronization.", "plain_english": "SYNC X is Avid's master clock box for Pro Tools HD systems. It keeps the audio and video in step with each other. It works with word clock, video reference, and timecode. This matters most in film and TV post work.", "purpose_function": "It provides one accurate clock and timecode master so Pro Tools stays locked to video and other gear, which is essential in post-production.", "practical_application": "A post engineer locks Pro Tools to a video black-burst reference through SYNC X and reads LTC from the picture source.", "category": "Clock & Synchronization", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Loop Sync", "Word Clock", "MTRX", "DigiLink", "Sample Rate"], "common_mistakes": ["Confusing SYNC X's clock reference role with an audio interface's converters", "Forgetting it must be first and last in the Loop Sync chain", "Mixing up house sync (video reference) with word-clock inputs"], "scenario_contexts": ["Locking Pro Tools to picture in film and TV post", "Distributing house video sync and word clock in a facility", "Generating LTC and MTC to drive external machines"], "formula_symbolic": "", "formula_words": ""}, {"id": "0ae0192a-11e7-4aba-8e66-87d4972dc968", "term": "Acoustic Drummer", "definition": "In Logic Pro (Apple Inc.'s digital audio workstation), an Acoustic Drummer is a Drummer preset that performs on a sampled acoustic drum kit through the Drum Kit Designer instrument, rather than on electronic sounds. Each acoustic drummer has a genre and personality, and its part is generated algorithmically from the user's settings rather than played by a person.", "plain_english": "An Acoustic Drummer is a virtual drummer in Logic Pro. It plays real recorded drum sounds, like a live kit. You pick a style and the software creates the beat. Apple owns Logic Pro, and the part is made by software.", "purpose_function": "It provides a realistic acoustic-kit drum performance without recording a live drummer, letting users audition genre-specific grooves and fills that respond to their settings.", "practical_application": "A technician adds an Acoustic Drummer to build a rock or songwriter backing track, then adjusts feel, complexity and fills to fit the song.", "category": "Virtual Drummer", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Drummer", "Electronic Drummer", "Drummer Track", "Drum Kit Designer", "Drummer Editor", "Session Players"], "common_mistakes": ["Thinking the Acoustic Drummer records a real drummer; it is software-generated", "Confusing Acoustic Drummer (Drum Kit Designer) with Electronic Drummer (Drum Machine Designer)", "Assuming the kit is fixed; kit pieces can be swapped and tuned"], "scenario_contexts": ["Creating a realistic acoustic-kit groove for a songwriter demo", "Auditioning different acoustic drummer personalities to match a genre", "Replacing a placeholder loop with a responsive acoustic drum performance"], "formula_symbolic": "", "formula_words": ""}, {"id": "fcd82d5c-237b-471a-9be0-ba8a8e5d02dd", "term": "Bass Player", "definition": "In Logic Pro, the Bass Player is a Session Player that automatically generates a bass performance on a software instrument track, played through the Studio Bass instrument. Its notes follow the project's chords (the global Chord track or region chords), and the user shapes the part by choosing a player style, presets and rhythmic patterns.", "plain_english": "The Bass Player is a virtual bass guitarist in Logic Pro. It plays a bass line that matches your song's chords. You choose a style and the software writes the part. Apple owns Logic Pro, and a computer makes the performance.", "purpose_function": "It creates a chord-aware bass accompaniment without recording a bassist, giving producers a quick, musically appropriate low-end part.", "practical_application": "A technician adds a Bass Player, sets a chord track, and dials in style and complexity so the bass locks with the Drummer and the song's harmony.", "category": "Session Players", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Session Players", "Keyboard Player", "Drummer", "Session Player Region", "Session Player Editor", "Chord Track"], "common_mistakes": ["Forgetting to set a Chord track, so the bass has no harmony to follow", "Expecting recorded audio; it is a generated software-instrument performance", "Confusing the Bass Player feature with a plain bass instrument patch"], "scenario_contexts": ["Generating a bass line that follows a chord track for a pop demo", "Building a rhythm section by pairing the Bass Player with the Drummer", "Sketching a groove before a live bassist records the final part"], "formula_symbolic": "", "formula_words": ""}, {"id": "71c32d7c-5534-46cb-be13-8ccc789e1603", "term": "Drummer", "definition": "Drummer is a Logic Pro feature (Apple Inc.) that adds a virtual, algorithmically generated drum performer to a project. It lives on a Drummer track and plays Drummer regions, producing genre-based grooves and fills that the user shapes with presets and controls rather than by programming each note. It was introduced in Logic Pro X in 2013 and is now part of the Session Players family.", "plain_english": "Drummer is a Logic Pro tool that adds a virtual drummer. You pick a style and the software plays the drums for you. You control the feel with simple knobs, not by placing each note. Apple owns Logic Pro, and the beat is computer-made.", "purpose_function": "It lets users get a realistic, genre-appropriate drum part quickly, without programming beats or recording a live drummer.", "practical_application": "A technician starts a song by adding a Drummer, choosing a genre and drummer, then tuning complexity and fills to fit the track.", "category": "Virtual Drummer", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Drummer Track", "Drummer Region", "Drummer Editor", "Acoustic Drummer", "Electronic Drummer", "Session Players"], "common_mistakes": ["Trying to edit individual drum notes directly; Drummer is controlled by settings", "Confusing Drummer (generated performance) with a plain drum-kit instrument", "Forgetting each Drummer track uses only one drummer at a time"], "scenario_contexts": ["Laying down a first drum groove for a new song idea", "Swapping drummer personalities to try different feels", "Building a full rhythm section with Drummer, Bass Player and Keyboard Player"], "formula_symbolic": "", "formula_words": ""}, {"id": "f5027491-aec4-40e8-850c-12733038dfb9", "term": "Drummer Editor", "definition": "The Drummer Editor is the Logic Pro control panel used to shape a Drummer performance. It offers a preset/personality list plus controls such as an XY complexity-and-loudness pad, kit-piece selection, fills, swing and 'follow' options; changing these regenerates the algorithmic performance in the selected Drummer region.", "plain_english": "The Drummer Editor is the control panel for your virtual drummer. It shows presets and simple controls for loudness, complexity and fills. You move a pad and choose options, and the beat updates. It shapes the Drummer without programming notes.", "purpose_function": "It gives users direct, musical controls to shape and regenerate a Drummer performance instead of editing raw MIDI notes.", "practical_application": "A technician opens the Drummer Editor to raise complexity, add fills, or make the drummer follow another track's rhythm.", "category": "Virtual Drummer", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Drummer", "Drummer Region", "Drummer Track", "Session Player Editor", "Acoustic Drummer", "Electronic Drummer"], "common_mistakes": ["Looking for individual notes to edit; the editor uses presets and controls", "Not noticing changes apply only to the selected Drummer region", "Confusing the Drummer Editor with the newer Session Player Editor"], "scenario_contexts": ["Adjusting a drummer's complexity and loudness with the XY pad", "Adding fills and choosing kit pieces for a chorus", "Setting the drummer to follow the rhythm of a bass track"], "formula_symbolic": "", "formula_words": ""}, {"id": "d6b1d870-dac0-459f-810b-d5542c01fd09", "term": "Drummer Region", "definition": "A Drummer region is the yellow region on a Drummer track that holds the settings from which Logic Pro generates a drum performance. It stores performance parameters (style, complexity, fills and follow settings) rather than fixed MIDI notes, so editing its settings re-creates the groove; it can be converted to a MIDI region for note-level editing.", "plain_english": "A Drummer region is the yellow block on a Drummer track. It holds the settings that tell Logic how to play the drums. It does not store fixed notes, so changing its settings makes a new beat. Think of it as a recipe, not a finished recording.", "purpose_function": "It stores the settings from which Logic Pro generates the drum groove, so edits regenerate the part rather than rewrite each note.", "practical_application": "A technician splits or resizes Drummer regions to give verse and chorus their own grooves and fills.", "category": "Virtual Drummer", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Drummer", "Drummer Track", "Drummer Editor", "Session Player Region", "Acoustic Drummer", "Electronic Drummer"], "common_mistakes": ["Treating a Drummer region like a normal MIDI region full of notes", "Expecting copied regions to sound identical if their settings differ", "Forgetting each region can carry different drummer settings"], "scenario_contexts": ["Creating separate Drummer regions for verse and chorus", "Resizing a Drummer region to change how long the groove plays", "Converting a Drummer region to MIDI for manual editing"], "formula_symbolic": "", "formula_words": ""}, {"id": "e0483584-df96-4a33-8db2-be6ecbb89e2f", "term": "Drummer Track", "definition": "A Drummer track is the specialized track type in Logic Pro that hosts Drummer regions and a single virtual drummer. Each Drummer track uses one drummer and kit at a time and outputs through the associated drum instrument (Drum Kit Designer for acoustic drummers, Drum Machine Designer for electronic drummers).", "plain_english": "A Drummer track is a special track in Logic Pro for one virtual drummer. It holds the yellow Drummer regions. Each track uses a single drummer and kit at a time. It is where the computer-made drums live in your project.", "purpose_function": "It provides a dedicated track type that hosts a virtual drummer and its regions, keeping the generated drum performance organized and easy to manage.", "practical_application": "A technician creates a Drummer track to add software drums, then edits its regions and drummer settings across the song.", "category": "Virtual Drummer", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Drummer", "Drummer Region", "Drummer Editor", "Track Stacks", "Acoustic Drummer", "Electronic Drummer"], "common_mistakes": ["Expecting one Drummer track to play two drummers at once", "Confusing a Drummer track with an ordinary software instrument track", "Adding many Drummer regions but forgetting they all share one drummer"], "scenario_contexts": ["Adding a Drummer track to start a new arrangement", "Managing verse and chorus grooves on one Drummer track", "Using an electronic drummer, which loads a Track Stack on the Drummer track"], "formula_symbolic": "", "formula_words": ""}, {"id": "efaffc78-cde9-4688-8ccb-f2100cf4dc14", "term": "Electronic Drummer", "definition": "In Logic Pro, an Electronic Drummer is a Drummer preset that performs using electronic and drum-machine sounds through Drum Machine Designer, rather than a sampled acoustic kit. It covers electronic-leaning genres such as Electronic and Hip Hop, generates its pattern algorithmically from user settings, and typically loads a Track Stack of drum-machine sounds.", "plain_english": "An Electronic Drummer is a virtual drummer that uses electronic sounds. It plays synth and drum-machine beats instead of a real kit. You pick a style and Logic makes the pattern. Apple owns Logic Pro, and the beat is software-made.", "purpose_function": "It provides genre-appropriate electronic drum performances using Drum Machine Designer, without programming each hit.", "practical_application": "A technician chooses an Electronic Drummer to build a hip hop or electronic beat, then adjusts the pattern and drum sounds.", "category": "Virtual Drummer", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Drummer", "Acoustic Drummer", "Drummer Track", "Drum Machine Designer", "Drummer Editor", "Session Players"], "common_mistakes": ["Confusing Electronic Drummer (Drum Machine Designer) with Acoustic Drummer (Drum Kit Designer)", "Thinking the sounds cannot be changed; the drum-machine kit is editable", "Expecting acoustic realism from an electronic drummer preset"], "scenario_contexts": ["Building an electronic or hip hop beat quickly", "Loading a Track Stack of drum-machine sounds via an electronic drummer", "Blending an electronic drummer with synth bass and keys"], "formula_symbolic": "", "formula_words": ""}, {"id": "b69511e7-60fe-4b60-aac3-fe3568a18e84", "term": "Flex & Follow", "definition": "Flex & Follow is a per-region Smart Tempo setting in Logic Pro that determines whether an audio region is Flex-enabled and follows the project tempo. Its options are Off (the region keeps its own tempo), On (the region time-stretches to follow tempo changes), and On + Align Bars or On + Align Bars and Beats (which additionally snap analyzed tempo markers to bars or beats). Flex is Logic's time-stretching engine.", "plain_english": "Flex & Follow is a setting on each audio clip in Logic Pro. It tells the clip whether to match the song's tempo. When it is on, Logic stretches the audio to stay in time. When it is off, the clip keeps its original speed.", "purpose_function": "It lets recorded audio automatically conform to the project tempo, so loops and takes stay in sync when the tempo changes.", "practical_application": "A technician sets an imported loop to Flex & Follow On so it stretches to the session tempo instead of drifting out of time.", "category": "Smart Tempo", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Smart Tempo", "Flex Time", "Tempo", "Apple Loops", "Audio Region", "Time Stretching"], "common_mistakes": ["Leaving Flex & Follow On when you want the audio to keep its native tempo", "Confusing Flex & Follow (tempo following) with Flex Time (manual timing edits)", "Expecting pitch to change; the setting stretches time, not pitch"], "scenario_contexts": ["Making an imported loop follow the session tempo", "Turning follow Off to keep a sample at its original speed", "Aligning a recorded take to the bar-and-beat grid with On + Align"], "formula_symbolic": "", "formula_words": ""}, {"id": "05c74f2a-9e58-448b-9953-92e0bbd1ec52", "term": "Keyboard Player", "definition": "In Logic Pro, the Keyboard Player is a Session Player that automatically generates a piano or keyboard performance on a software instrument track, played through the Studio Piano instrument. Its notes follow the project's chords (the global Chord track or region chords), and the user shapes the part with a player style, presets and patterns.", "plain_english": "The Keyboard Player is a virtual piano player in Logic Pro. It plays chords and parts that match your song. You pick a style and the software performs it. Apple owns Logic Pro, and a computer plays the keys.", "purpose_function": "It generates a chord-aware keyboard accompaniment automatically, giving producers a musical part without recording a keyboardist.", "practical_application": "A technician adds a Keyboard Player over a chord track to create piano comping that fits the song's harmony.", "category": "Session Players", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Session Players", "Bass Player", "Drummer", "Session Player Region", "Session Player Editor", "Chord Track"], "common_mistakes": ["Not setting a Chord track, so the keyboard part lacks harmony to follow", "Expecting audio; the part is generated on a software instrument", "Confusing the Keyboard Player with a static piano patch"], "scenario_contexts": ["Adding piano comping that follows the chord track", "Pairing the Keyboard Player with Bass Player and Drummer for a full band", "Sketching a keyboard part before a live player records it"], "formula_symbolic": "", "formula_words": ""}, {"id": "e61dca0a-5c80-478e-b04b-17c7334895a4", "term": "Live Loops", "definition": "Live Loops is a Logic Pro feature (Apple Inc.) for non-linear, improvisational music creation using a grid of cells that hold audio or MIDI loops. Cells can be triggered and looped in real time and captured into the linear Tracks area timeline; it is a clip-launching workflow comparable to Ableton Live's Session View.", "plain_english": "Live Loops is a way to make music in Logic Pro by triggering loops. You build a grid of small clips and play them live. It works like a scratchpad, not a straight timeline. Apple made it, and it is similar to Ableton Live's Session View.", "purpose_function": "It supports non-linear, improvisational arranging by letting users trigger and combine loops in real time, then capture the result into the timeline.", "practical_application": "A technician builds song sections as cells, performs different combinations live, and records the arrangement into the Tracks area.", "category": "Live Loops", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Live Loops Cell", "Live Loops Grid", "Apple Loops", "Scene", "Tracks Area", "Cell"], "common_mistakes": ["Thinking a track can play a cell and a timeline region at the same time", "Assuming Live Loops replaces the timeline; the two work together", "Confusing Logic's Live Loops with Ableton's Session View by name"], "scenario_contexts": ["Improvising an arrangement by launching loop cells live", "Sketching song sections before committing to a timeline", "Performing a set by triggering scenes"], "formula_symbolic": "", "formula_words": ""}, {"id": "333edad7-0d93-43e7-9eae-7d7b80326126", "term": "Live Loops Cell", "definition": "A Live Loops cell is a single square in the Live Loops grid that contains one loopable musical phrase, either audio or MIDI. Each cell can be started, stopped and looped independently; on any given track, only one cell in the grid or one region in the Tracks area can play at a time, never both.", "plain_english": "A Live Loops cell is one square in the grid. It holds a single loop, either audio or MIDI. You can start, stop and loop it on its own. On each track, only one cell or one timeline clip plays at a time.", "purpose_function": "It is the basic building block of Live Loops, storing one loopable phrase that can be triggered independently for live arranging.", "practical_application": "A technician records or drags a loop into a cell, then triggers it to audition parts during a Live Loops performance.", "category": "Live Loops", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Live Loops", "Live Loops Grid", "Scene", "Apple Loops", "Audio Region", "MIDI Region"], "common_mistakes": ["Expecting a cell and a Tracks-area region to play together on one track", "Thinking cells only hold audio; they hold MIDI too", "Forgetting cells loop until they are stopped"], "scenario_contexts": ["Dragging an Apple Loop into an empty cell", "Recording a MIDI idea directly into a cell", "Triggering individual cells to test combinations"], "formula_symbolic": "", "formula_words": ""}, {"id": "a8ff7aa5-5d67-4a97-b92b-d585f0ad16b3", "term": "Live Loops Grid", "definition": "The Live Loops grid is the matrix of cells in Logic Pro, with each row tied to a track and each vertical column forming a scene. It provides the non-linear workspace where cells are triggered and combined, running alongside the linear Tracks area, which shares the same tracks.", "plain_english": "The Live Loops grid is the table of cells in Logic Pro. Each row is a track, and each column is a scene. You trigger cells here to arrange music by hand. It sits next to the normal timeline and works with it.", "purpose_function": "It provides the non-linear workspace where cells are organized by track and scene and triggered to build arrangements in real time.", "practical_application": "A technician arranges cells across rows and columns in the grid, then launches scenes to play whole sections at once.", "category": "Live Loops", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Live Loops", "Live Loops Cell", "Scene", "Tracks Area", "Apple Loops", "Cell"], "common_mistakes": ["Confusing grid rows (tracks) with columns (scenes)", "Thinking the grid is separate from your tracks; each row is a project track", "Expecting grid and timeline to both sound on the same track at once"], "scenario_contexts": ["Building an arrangement across grid rows and scene columns", "Launching a scene to play a full section", "Switching a track between a grid cell and a timeline region"], "formula_symbolic": "", "formula_words": ""}, {"id": "ac7055f0-2511-42b8-ac47-e068f9bbfb05", "term": "Logic Patch", "definition": "In Logic Pro, a patch is a saved collection of settings that define a track's sound: the instrument, effects, Smart Controls and routing, stored as one or more channel strip settings plus any aux routing. Patches are chosen from the Library, and the patches shown depend on the track type.", "plain_english": "A patch in Logic Pro is a saved sound for a track. It includes the instrument, effects, controls and routing. You pick patches from the Library. Loading one sets up the whole sound at once.", "purpose_function": "A patch bundles all the settings that make a track's sound, so users can recall a complete, ready-to-play sound in one step.", "practical_application": "A technician chooses a patch from the Library to instantly load an instrument with its effects and controls for a new track.", "category": "Patches", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Logic Pro Sound Library", "Channel Strip", "Smart Controls", "Library", "Software Instrument", "Track Stacks"], "common_mistakes": ["Thinking a patch is only an instrument; it also stores effects and routing", "Not realizing the Library shows only patches that match the track type", "Confusing a Logic patch with a MainStage patch"], "scenario_contexts": ["Loading a vocal patch with its channel strip and effects", "Switching a track's patch while producing to try a new sound", "Saving a custom patch to reuse across projects"], "formula_symbolic": "", "formula_words": ""}, {"id": "518d5b0f-0237-43c3-a716-18e1cc9a0977", "term": "Logic Pro", "definition": "Logic Pro is a professional digital audio workstation (DAW) developed and sold by Apple Inc. for macOS, with a separate version for iPad. It provides multitrack audio and MIDI recording, editing, mixing, software instruments and effects for music production. It originated as Emagic's Logic (from Notator) and became an Apple product after Apple acquired Emagic in 2002.", "plain_english": "Logic Pro is music-making software from Apple. It records, edits and mixes audio and MIDI on Mac and iPad. Producers use it to build full songs with instruments and effects. People call this kind of program a DAW, short for digital audio workstation.", "purpose_function": "It provides a complete environment for recording, arranging, mixing and producing music and audio, competing with DAWs such as Pro Tools and Ableton Live.", "practical_application": "A technician uses Logic Pro to track a band, edit takes, program instruments, and mix a finished song.", "category": "DAW Software", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Logic Pro Sound Library", "Logic Patch", "Drummer", "Live Loops", "MainStage", "Logic Remote"], "common_mistakes": ["Calling it 'Logic Pro X'; the current version is named Logic Pro", "Assuming it runs on Windows; it is macOS and iPadOS only", "Confusing Logic Pro with GarageBand, Apple's simpler music app"], "scenario_contexts": ["Recording and mixing a song in a Mac-based studio", "Producing music on the go with Logic Pro for iPad", "Using software instruments and Drummer to build a track"], "formula_symbolic": "", "formula_words": ""}, {"id": "0d2d41e1-95e1-4eab-9a35-746202764415", "term": "Logic Pro Sound Library", "definition": "The Logic Pro Sound Library is the collection of sound content installed with and downloadable for Logic Pro, including patches, software instruments, Apple Loops, drum kits, samples and sound packs. Essential content installs with the app, additional content downloads on demand, and the library can be relocated to another drive.", "plain_english": "The Sound Library is Logic Pro's collection of sounds and loops. It holds patches, instruments, drum kits, samples and Apple Loops. Some content installs with the app, and more can be downloaded. You can also move it to another drive to save space.", "purpose_function": "It stores and organizes all of Logic Pro's sound content so users can browse and load patches, instruments and loops, with extra content available on demand.", "practical_application": "A technician downloads additional sound packs into the Sound Library, then loads its patches and loops while producing.", "category": "Content Library", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Logic Patch", "Apple Loops", "Library", "Sound Pack", "Drum Kit Designer", "Software Instrument"], "common_mistakes": ["Thinking all content installs at once; much is downloaded separately", "Deleting the Sound Library to free space and losing needed patches", "Not knowing the library can be relocated to an external drive"], "scenario_contexts": ["Downloading additional sound packs before a session", "Relocating the Sound Library to an external drive", "Browsing library patches and Apple Loops to find sounds"], "formula_symbolic": "", "formula_words": ""}, {"id": "8ec7d375-5c5a-4f9b-9338-6a146ea57071", "term": "Logic Remote", "definition": "Logic Remote is an Apple app for iPad and iPhone that wirelessly remote-controls Logic Pro for Mac. It lets you play software instruments with on-screen Touch Instruments and control transport, recording, mixing, automation, Smart Controls, patches, and plug-ins. Logic Remote is a trademark of Apple Inc.; the underlying idea is a networked remote-control surface for a DAW.", "plain_english": "Logic Remote is a free Apple app for iPad and iPhone. It connects to Logic Pro on your Mac over Wi-Fi. You can play instruments by touch and control mixing and recording. Think of it as a wireless remote for the software.", "purpose_function": "It exists so you can control Logic Pro away from the computer keyboard and mouse, using touch. This makes playing parts, mixing, and recording faster and more hands-on.", "practical_application": "An engineer sets an iPad on a keyboard stand to arm tracks, roll transport, and ride faders from across the room. A player uses its on-screen keys or fretboard to record software-instrument parts.", "category": "Remote Control", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Logic Pro", "MainStage", "Logic Patch", "Live Loops", "Track Stacks"], "common_mistakes": ["Thinking Logic Remote is a full DAW; it only controls Logic Pro or MainStage running on a Mac.", "Forgetting the Mac and device must share the same Wi-Fi network to connect.", "Assuming it works on Android; it is an Apple iOS and iPadOS app only."], "scenario_contexts": ["Tracking a vocal while standing at the mic and starting recording from the iPad.", "Mixing on the couch using the iPad Mixer instead of the Mac trackpad.", "Playing Touch Instrument parts into a project without a hardware MIDI keyboard."], "formula_symbolic": "", "formula_words": ""}, {"id": "c4a40eb2-30d9-4318-8f0d-40e25af93aa8", "term": "MainStage", "definition": "MainStage is Apple's live-performance software for Mac. It hosts the same software instruments and effect plug-ins used in Logic Pro so a musician can play them on stage. Sounds are organized into concerts, sets, and patches. MainStage is a trademark of Apple Inc.; it is a live plug-in host built around Logic's audio engine.", "plain_english": "MainStage is an Apple app for live shows on a Mac. It turns your computer into a stage instrument rig. You store your sounds as patches and switch between them while you play. It uses the same instruments and effects as Logic Pro.", "purpose_function": "It exists to bring studio-quality software instruments and effects to live performance. Performers get reliable, quick sound changes without a rack of hardware.", "practical_application": "A keyboard player builds a concert of patches, one per song section, and steps through them live with a foot switch. A guitarist uses it as a laptop-based amp and effects rig on stage.", "category": "Live Performance", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["MainStage Concert", "MainStage Patch", "MainStage Set", "MainStage Loopback", "Logic Pro", "Logic Remote"], "common_mistakes": ["Confusing MainStage with Logic Pro; MainStage is for live performance, not multitrack recording and editing.", "Building huge concerts that overload the CPU, causing dropouts during a show.", "Not testing patch changes before the gig, then finding audio glitches when switching sounds."], "scenario_contexts": ["A touring keyboardist replacing hardware synths with a Mac running MainStage.", "A worship or theatre musician recalling exact sounds cue by cue.", "A guitarist using MainStage as a live amp and pedalboard emulation."], "formula_symbolic": "", "formula_words": ""}, {"id": "1f623628-7e8e-4832-af8f-0a0c022203d4", "term": "MainStage Concert", "definition": "A concert is the top-level document in Apple MainStage. It holds everything for a performance: all sets, patches, channel strips, and global settings. Opening a concert loads the whole live rig. The term is used within MainStage, a trademark of Apple Inc.", "plain_english": "A concert is the main file you open in MainStage. It holds all of your sounds and settings for a show. Think of it as the whole rig saved in one document. Inside it are sets and patches.", "purpose_function": "It exists to keep an entire performance setup in a single, recallable file. That lets a performer load one document and be ready to play a whole show.", "practical_application": "A musician saves one concert per band or tour and opens it before the gig. Global effects and outputs are set once at the concert level for the whole show.", "category": "MainStage", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["MainStage", "MainStage Set", "MainStage Patch", "MainStage Loopback", "Logic Patch"], "common_mistakes": ["Confusing a concert with a patch; a concert contains many patches, not a single sound.", "Storing every song as a separate concert, which makes switching between songs slow live.", "Forgetting that concert-level channel strips affect all patches in the concert."], "scenario_contexts": ["Loading one concert file at the start of a live set.", "Setting a master reverb at concert level so every patch shares it.", "Backing up a full performance rig by copying its concert file."], "formula_symbolic": "", "formula_words": ""}, {"id": "c0081bd8-6756-4c6c-938a-349777dc799a", "term": "MainStage Loopback", "definition": "Loopback is a live-looping plug-in in Apple MainStage. Used as an insert effect in a channel strip, it records and plays back audio in real time so a performer can layer or overdub loops on stage. It offers transport, sync, snap-to, and play-from controls plus group functions. The name is Apple's; the underlying tool is a generic live phrase looper.", "plain_english": "Loopback is a live looper inside MainStage. You record a short part and it plays back over and over. Then you play more parts on top to build a layered sound. It stays in time with your performance.", "purpose_function": "It exists so a solo or small act can build up layered arrangements live, one loop at a time. This replaces a separate hardware loop pedal.", "practical_application": "A performer records a chord loop, then overdubs a bass line and a melody over it during a song. Sync settings keep each new loop locked to the tempo.", "category": "MainStage", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["MainStage", "MainStage Patch", "MainStage Concert", "Live Loops", "Live Loops Cell"], "common_mistakes": ["Confusing MainStage Loopback with the Loopback delay in Logic Pro; here it is a live looper.", "Recording a loop that is not on the beat, so overdubs drift out of time.", "Forgetting to set the sync or length, which leaves loops the wrong size."], "scenario_contexts": ["A solo artist looping guitar and vocals live to sound like a full band.", "Layering a percussion groove under an improvised solo on stage.", "Building an intro pad loop before the rest of the band comes in."], "formula_symbolic": "", "formula_words": ""}, {"id": "1a5afbac-ad62-4f7f-8629-dccc0f2e3a30", "term": "MainStage Patch", "definition": "A patch is a selectable sound in Apple MainStage. It is a saved set of channel strips, holding the instruments and effects a performer calls up during a show. Patches are grouped into sets inside a concert. The term is used within MainStage, a trademark of Apple Inc.", "plain_english": "A patch is one sound you pick during a live show in MainStage. It bundles the instruments and effects for that moment. You switch patches to change sounds between songs or parts. Many patches make up a set.", "purpose_function": "It exists to store a ready-to-play sound that can be recalled instantly on stage. This lets a performer change tones quickly without touching menus.", "practical_application": "A keyboardist makes one patch for a piano verse and another for a synth-lead chorus, then switches between them. Each patch keeps its own effects and split points.", "category": "MainStage", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["MainStage", "MainStage Set", "MainStage Concert", "Logic Patch", "MainStage Loopback"], "common_mistakes": ["Mixing up a MainStage patch with a Logic Patch; they live in different apps.", "Putting too many instruments in one patch, which strains the CPU during changes.", "Not labeling patches clearly, making them hard to find live."], "scenario_contexts": ["Assigning a foot switch to step through patches song by song.", "Splitting a keyboard so a patch plays bass on the left and piano on the right.", "Copying a favorite patch between concerts to reuse a sound."], "formula_symbolic": "", "formula_words": ""}, {"id": "669604d3-f2af-42f0-b39d-9094ba46a03c", "term": "MainStage Set", "definition": "A set is a group of patches in Apple MainStage. It organizes related patches inside a concert, for example the patches for one song. Sets appear as folders in the Patch List and can hold their own shared channel strips. The term is used within MainStage, a trademark of Apple Inc.", "plain_english": "A set is a folder of patches in MainStage. It keeps related sounds together, like all the patches for one song. Sets sit inside a concert. They make a big list of patches easier to manage.", "purpose_function": "It exists to organize patches so performers can find and recall them quickly during a show. Sets can also hold sounds shared by all their patches.", "practical_application": "A player groups a song's intro, verse, and chorus patches into one set. A set-level channel strip can add a delay used by every patch in that set.", "category": "MainStage", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["MainStage", "MainStage Patch", "MainStage Concert", "MainStage Loopback", "Logic Patch"], "common_mistakes": ["Confusing a set with a concert; a concert can contain many sets.", "Forgetting that a set-level channel strip affects all patches inside that set.", "Leaving patches ungrouped, which makes live navigation slow."], "scenario_contexts": ["Making one set per song in a live setlist.", "Adding a shared reverb at set level for a group of related patches.", "Collapsing sets in the Patch List to keep a long show organized."], "formula_symbolic": "", "formula_words": ""}, {"id": "8b9d3829-ccea-4ebf-87f5-f443310fb362", "term": "Percussionist", "definition": "In Apple's Drummer and Session Player system, a Percussionist is a virtual performer that generates auxiliary percussion parts, such as tambourine, shaker, congas, or claps, rather than a full drum kit. It plays on its own track and follows a chosen style, and its parts can be tuned like other Session Player performances. The feature is Apple's; the underlying method is algorithmic performance generation.", "plain_english": "A Percussionist is a virtual player in Apple's music apps. It adds percussion like tambourine, shaker, or congas. It works like the Drummer, but for hand percussion instead of a drum kit. You pick a style and it plays a matching part.", "purpose_function": "It exists to add lively, human-feeling percussion to a track without recording a real player. It gives quick, editable percussion parts that fit the song's style.", "practical_application": "A songwriter adds a Percussionist track with a shaker and tambourine to lift a chorus. The performance can be regenerated or adjusted to sit under the main drums.", "category": "Session Players", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Session Players", "Drummer", "Session Player Editor", "Session Player Region", "Drummer Editor"], "common_mistakes": ["Thinking a Percussionist plays a full drum kit; it plays auxiliary percussion instead.", "Layering it too loud, so it clashes with the main Drummer part.", "Assuming its part is fixed; like other Session Players it can be regenerated and edited."], "scenario_contexts": ["Adding a shaker groove under an acoustic guitar demo.", "Layering hand percussion over a Drummer track to add motion.", "Building a Latin-flavored percussion part without hiring a player."], "formula_symbolic": "", "formula_words": ""}, {"id": "8b180fb6-aff2-4446-ad67-4975a75f11a4", "term": "Selection-Based Processing", "definition": "Selection-based processing is a Logic Pro feature that applies one or more audio effect plug-ins directly to selected audio regions or marquee selections. The effect is rendered offline into the audio when you click Apply, so it is destructive, though you can preview first or create a new take to keep the original. It supports two plug-in sets for comparison and gain compensation. The feature is part of Logic Pro, a trademark of Apple Inc.", "plain_english": "Selection-based processing bakes an effect right into a piece of audio. You pick a region, choose plug-ins, and click Apply. Logic then writes the effect into the file itself. You can preview it first or save a copy to keep the original safe.", "purpose_function": "It exists to commit effects like noise reduction or distortion straight into audio, instead of running them live on every playback. This saves CPU and locks in a sound.", "practical_application": "An editor selects a noisy dialogue clip and applies de-noise and EQ offline to just that region. A producer prints a distortion effect into a single vocal phrase.", "category": "Audio Editing", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Logic Pro", "Track Stacks", "Stem Splitter", "Flex & Follow", "Logic Pro Sound Library"], "common_mistakes": ["Assuming it is non-destructive; it renders the effect into the audio unless you create a new take.", "Forgetting to preview, then applying the wrong plug-in settings permanently.", "Using it for effects you plan to keep tweaking, where a normal channel-strip insert is better."], "scenario_contexts": ["Cleaning up one noisy region of a location recording.", "Printing a creative effect onto a single word or phrase in a vocal.", "Committing CPU-heavy processing to free up the mix for playback."], "formula_symbolic": "", "formula_words": ""}, {"id": "1862b786-a5cd-4298-921b-3d138874d704", "term": "Session Player Editor", "definition": "The Session Player Editor is the interface in Logic Pro for shaping a Session Player's automatically generated performance. In it you change the style, choose presets, pick or build a rhythmic pattern, set which chords the region follows, fine-tune settings, and regenerate the performance. It is part of Logic Pro, a trademark of Apple Inc.", "plain_english": "The Session Player Editor is where you direct a virtual player in Logic Pro. You change its style, feel, and pattern. You can also tell it which chords to follow. Then Logic rebuilds the part to match your choices.", "purpose_function": "It exists to give the user control over the computer-generated performance. This lets you steer a Bass, Keyboard, Drummer, or Synth Player toward the exact feel you want.", "practical_application": "A producer opens the editor to make a bass part busier and lock it to the song's chords. A songwriter swaps a drummer's style and regenerates until the groove fits.", "category": "Session Players", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Session Players", "Session Player Region", "Synth Player", "Percussionist", "Drummer Editor"], "common_mistakes": ["Editing the wrong region because the editor follows whichever Session Player region is selected.", "Not setting the chord track, so the player follows the wrong harmony.", "Expecting note-by-note MIDI editing; convert the region to MIDI first for that."], "scenario_contexts": ["Changing a keyboard player's complexity and feel to fit a ballad.", "Choosing a rhythmic pattern for a synth bass part.", "Regenerating a drum performance until the fills sit right."], "formula_symbolic": "", "formula_words": ""}, {"id": "658586cb-70d5-4668-95eb-044a80c43982", "term": "Session Player Region", "definition": "A Session Player region is the region on a Session Player track that holds an automatically generated performance in Logic Pro. A new Session Player track starts with one eight-bar region, and the region follows the project's chords and the settings you choose. It can be regenerated and converted into MIDI or pattern regions. The feature is part of Logic Pro, a trademark of Apple Inc.", "plain_english": "A Session Player region is the block that holds a virtual player's part. Logic fills it with a performance that follows your chords. You can regenerate it or change its settings. You can also turn it into normal MIDI to edit each note.", "purpose_function": "It exists to store and control a computer-generated performance as an editable region on the timeline. This lets you place, resize, and rework the part like any other region.", "practical_application": "A user drags a Session Player region to cover a chorus and regenerates it for variation. Converting the region to MIDI lets an engineer tweak individual notes.", "category": "Session Players", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Session Players", "Session Player Editor", "Synth Player", "Percussionist", "Drummer Region"], "common_mistakes": ["Trying to edit single notes directly; convert the region to a MIDI region first.", "Ignoring the chord track, so the region plays the wrong harmony.", "Assuming regions are fixed length; they can be resized and regenerated."], "scenario_contexts": ["Extending a bass region across a new song section.", "Regenerating a region to get a different fill or variation.", "Converting a region to MIDI to fine-tune specific notes."], "formula_symbolic": "", "formula_words": ""}, {"id": "8f8429fd-c8cc-4de7-b3bb-85e060c91d82", "term": "Session Players", "definition": "Session Players are a Logic Pro feature that automatically generates realistic backing performances that respond to your direction. The core players are the Bass Player, Keyboard Player, and Drummer, with Synth Player styles built on the Bass and Keyboard players. Each plays on its own track, follows the project's chords, and can be edited and regenerated. The feature is Apple's; the underlying method is algorithmic performance generation.", "plain_english": "Session Players are virtual musicians inside Logic Pro. They play bass, keys, and drums for you. You give direction and they create parts that follow your chords. You can change the style and rebuild the part until it fits.", "purpose_function": "They exist to give a songwriter a fast, flexible backing band without hiring players. They fill out arrangements and respond to changes in style and chords.", "practical_application": "A writer adds a Bass Player and Keyboard Player to a chord sketch to hear a full arrangement. An engineer regenerates parts and edits the feel to match a reference track.", "category": "Session Players", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Bass Player", "Keyboard Player", "Drummer", "Synth Player", "Session Player Editor", "Session Player Region"], "common_mistakes": ["Not setting the chord track, so the players follow the wrong harmony.", "Treating parts as final; they are meant to be edited and regenerated.", "Confusing Session Players with recorded loops; they are generated performances that adapt."], "scenario_contexts": ["Building a quick backing band around a chord progression.", "Auditioning different bass and drum styles for a demo.", "Generating a starting arrangement, then converting parts to MIDI to finish."], "formula_symbolic": "", "formula_words": ""}, {"id": "e6b647cc-95c7-444a-a253-a60d09b0e24f", "term": "Stem Splitter", "definition": "Stem Splitter is a Logic Pro feature that separates a mixed audio recording into individual stems, such as vocals, drums, bass, and other instruments. It creates a summing stack of separate, editable tracks below the original and mutes the source region. It runs on Macs with Apple silicon (M1 or later). The name is Apple's; the underlying method is audio source separation, or demixing.", "plain_english": "Stem Splitter pulls a finished mix apart into its main parts. It can separate vocals, drums, bass, and other instruments. Each part lands on its own track you can edit. It needs a Mac with Apple silicon to work.", "purpose_function": "It exists to recover separate parts from a stereo mix when the original multitracks are gone. This helps with remixing, sampling, and cleanup.", "practical_application": "A remixer splits an old stereo track to isolate the vocal and build a new beat under it. An engineer removes drums from a reference clip to study the arrangement.", "category": "Audio Editing", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Logic Pro", "Selection-Based Processing", "Track Stacks", "Flex & Follow", "Logic Pro Sound Library"], "common_mistakes": ["Expecting perfect separation; splits can have artifacts, especially on dense mixes.", "Trying to run it on an Intel Mac; it needs Apple silicon (M1 or later).", "Deleting the original region before checking the separated stems."], "scenario_contexts": ["Isolating a vocal from a stereo mix for a remix.", "Pulling a drum stem out to study or replace it.", "Recovering usable parts when the original session files are lost."], "formula_symbolic": "", "formula_words": ""}, {"id": "d46ec60a-8b50-4054-9a04-60caec062c25", "term": "Synth Player", "definition": "The Synth Player is a set of Session Player styles in Logic Pro that generates synthesizer parts. It comprises Bass Player and Keyboard Player styles, and the loaded patch uses the Alchemy plug-in to make sound. Styles include synth-bass options like 808 Bass, Pump Bass, and Sequenced Bass, and keyboard options like Rhythmic Chords, Modulated Pad, and Simple Pad. The feature is Apple's; the underlying method is algorithmic performance generation with software synthesis.", "plain_english": "The Synth Player makes synth parts for you in Logic Pro. It comes as bass and keyboard styles, like 808 bass or pad chords. It uses Logic's Alchemy synth to make the sound. You pick a style and it plays a matching part that follows your chords.", "purpose_function": "It exists to add modern electronic bass and keyboard parts without programming them by hand. It pairs generated performances with synth sounds ready to use.", "practical_application": "A producer adds a Sequenced Bass style to drive a track, then edits its feel in the editor. A writer drops in a pad style to fill out the harmony.", "category": "Session Players", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Session Players", "Bass Player", "Keyboard Player", "Session Player Editor", "Session Player Region"], "common_mistakes": ["Thinking the Synth Player is a separate instrument; it is a set of Bass and Keyboard Player styles.", "Not setting the chord track, so the generated part follows the wrong harmony.", "Forgetting the sound comes from the Alchemy plug-in, which you can further edit."], "scenario_contexts": ["Adding an 808-style synth bass to a hip-hop beat.", "Using a pad style to sustain chords under a vocal.", "Auditioning sequenced synth patterns for an electronic track."], "formula_symbolic": "", "formula_words": ""}, {"id": "a5c11203-0e98-4384-a3f9-cc657dd0a6db", "term": "Track Stacks", "definition": "Track Stacks are a Logic Pro feature that groups several tracks under one main track. There are two types: a Folder Stack, which only organizes tracks visually, and a Summing Stack, which routes its subtracks to an auxiliary channel strip so they share one subgroup for level and processing. The feature is part of Logic Pro, a trademark of Apple Inc.; the underlying idea is folder and subgroup (bus) grouping.", "plain_english": "Track Stacks combine several tracks into one folder in Logic Pro. A Folder Stack just tidies tracks together. A Summing Stack also sends those tracks to one shared control. That lets you set the level and effects for the whole group at once.", "purpose_function": "They exist to keep large projects tidy and to control groups of tracks together. A Summing Stack also lets you process a whole submix, like all the drums, on one channel.", "practical_application": "An engineer sums all drum tracks into one Summing Stack to compress and level the kit together. A Folder Stack hides a group of tracks to clean up a busy arrangement.", "category": "Track Management", "difficulty": "intermediate", "achievement_id": "09e6242e-714c-468f-a176-9d8271ba40f0", "cross": [], "related_terms": ["Logic Pro", "Selection-Based Processing", "Stem Splitter", "Logic Patch", "Flex & Follow"], "common_mistakes": ["Confusing the two types; a Folder Stack does not create an audio subgroup, a Summing Stack does.", "Expecting shared processing on a Folder Stack, where there is no aux channel strip.", "Adding the same effect on both the stack and its subtracks, doubling the processing."], "scenario_contexts": ["Summing drum tracks to bus-compress the whole kit.", "Folding backing vocals into one stack to declutter the arrangement.", "Controlling the level of a whole instrument group with one fader."], "formula_symbolic": "", "formula_words": ""}, {"id": "4681a6bc-60ec-4358-a771-8220f3f0ef38", "term": "Adaptive Limiter", "definition": "The Adaptive Limiter is a look-ahead, loudness-maximizing peak limiter plug-in in Apple's Logic Pro (trademark Apple Inc.). It controls perceived loudness by rounding and smoothing signal peaks, letting a signal reach its maximum level without exceeding the 0 dBFS output ceiling, and it can add slight harmonic coloration. It is Apple's implementation of the generic loudness-maximizing method, distinct from a transparent true-peak brickwall limiter used for final true-peak-safe limiting.", "plain_english": "This is a loudness tool inside Apple's Logic Pro. It gently rounds off the loudest peaks in a track. That lets you make the sound louder without clipping the digital ceiling. Engineers usually add it at the very end of a mix.", "purpose_function": "It maximizes loudness while stopping peaks from clipping past 0 dBFS, so a finished mix sounds louder and stays clean.", "practical_application": "A technician places it last on the stereo output during mastering to raise level and catch peaks; because look-ahead adds latency, it is bypassed while recording.", "category": "Dynamics Processor", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Limiter", "Multipressor", "Compressor", "0 dBFS", "Mastering", "True peak"], "common_mistakes": ["Leaving it active while tracking, which adds latency", "Driving the input too hard and squashing the dynamics", "Confusing it with a standard compressor rather than a peak limiter", "Expecting it to fix a poorly balanced mix"], "scenario_contexts": ["Final loudness stage on a stereo master", "Preventing clipping on a bounced mix", "Raising the perceived level of a quiet track"], "formula_symbolic": "", "formula_words": ""}, {"id": "d86b075a-4ebb-409d-9cd0-3898cfce6f79", "term": "Alchemy", "definition": "Alchemy is a sampler and multi-synthesis software instrument in Apple's Logic Pro (trademark Apple Inc.). It combines several sound engines - additive, spectral, granular, sampler (pitch), and virtual analog - with extensive sample manipulation, resynthesis, modulation, arpeggiation, and sequencing. It is Apple's proprietary instrument built on generic synthesis and sampling methods.", "plain_english": "Alchemy is a powerful instrument built into Apple's Logic Pro. It can play back samples and build sounds in several different ways. You can twist recordings into brand-new tones. Producers use it for normal sounds and for wild sound design.", "purpose_function": "It puts many synthesis and sampling methods in one instrument, so users can design a huge range of sounds and morph between them.", "practical_application": "A producer loads an Alchemy preset on an instrument track, then edits its sources, filters, and modulation to shape a pad, bass, or lead.", "category": "Software Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Sampler", "Additive synthesis", "Granular synthesis", "Virtual analog", "Alchemy Transform Pad", "Alchemy Perform Pad"], "common_mistakes": ["Assuming it is only a sampler", "Overloading the CPU by stacking many voices and engines", "Ignoring its modulation and performance controls", "Confusing standalone Alchemy with the Sampler (EXS24)"], "scenario_contexts": ["Designing an evolving pad for a film cue", "Resynthesizing a vocal into a textured tone", "Layering multiple engines for a rich lead"], "formula_symbolic": "", "formula_words": ""}, {"id": "ddb672ab-df70-4421-b799-c802ad4f43fc", "term": "Alchemy Perform Pad", "definition": "The Alchemy Perform pad is the performance-controls area of Apple's Alchemy instrument in Logic Pro (trademark Apple Inc.). It presents eight assignable knobs, two X/Y pads, and AHDSR envelope controls - sixteen controls in total - that modulate key sound parameters in real time. All of its controls can be recorded as automation in a Logic project.", "plain_english": "The Perform pad is a control panel inside Alchemy. It gives you knobs and X/Y pads to tweak the sound live. You can change filters, effects, and movement while you play. Logic can record these moves as automation.", "purpose_function": "It gathers the most useful sound controls in one place so a player can shape and automate a patch expressively during performance or mixing.", "practical_application": "A musician maps cutoff, reverb, and arpeggiator amounts to the Perform pad knobs, then automates them across a track.", "category": "Instrument Control", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Alchemy", "Alchemy Transform Pad", "Automation", "AHDSR envelope", "Modulation", "XY pad"], "common_mistakes": ["Confusing the Perform pad with the Transform pad", "Not realizing the controls can be reassigned", "Forgetting the controls can be automated", "Assuming a preset locks the control assignments"], "scenario_contexts": ["Live-tweaking a pad during a performance", "Automating filter sweeps in a mix", "Mapping macro controls to a hardware controller"], "formula_symbolic": "", "formula_words": ""}, {"id": "72cc46e6-1c18-45f8-a1a7-8ece168d6d9c", "term": "Alchemy Transform Pad", "definition": "The Alchemy Transform pad is a performance control in Apple's Alchemy instrument (Logic Pro; trademark Apple Inc.). It arranges up to eight sound 'snapshots' on an X/Y grid; dragging a framing box morphs (interpolates) smoothly between them in real time, updating the performance controls to the blended values. It applies the generic idea of snapshot morphing to Alchemy's controls.", "plain_english": "The Transform pad lets you blend between saved sound settings in Alchemy. It puts up to eight versions on a grid. You drag a box to morph smoothly from one to another. This makes sounds shift and evolve as you play.", "purpose_function": "It lets a user store several sound states and blend between them smoothly, instead of switching presets abruptly.", "practical_application": "A sound designer captures eight snapshots, then drags across the Transform pad to morph a bass into an arpeggiated lead during a performance.", "category": "Instrument Control", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Alchemy", "Alchemy Perform Pad", "Snapshot", "Morphing", "Interpolation", "Automation"], "common_mistakes": ["Confusing it with the Perform pad", "Expecting instant switches rather than smooth morphs", "Not assigning snapshots before using it", "Overlooking the rate control that sets morph speed"], "scenario_contexts": ["Morphing between two textures in a build-up", "Assigning snapshots to keyboard notes for live recall", "Creating evolving movement in a pad"], "formula_symbolic": "", "formula_words": ""}, {"id": "b662d8f9-b440-40f3-978c-c8f4241e8ec7", "term": "Amp Designer", "definition": "Amp Designer is a guitar amplifier modeling plug-in in Apple's Logic Pro (trademark Apple Inc.). It emulates more than 20 guitar amplifiers, their speaker cabinets, and seven microphone types, which can be mixed and matched, and adds built-in effects such as spring reverb, vibrato, and tremolo. It is Apple's implementation of generic guitar amp, cabinet, and microphone modeling.", "plain_english": "Amp Designer copies the sound of classic guitar amps inside Logic Pro. You pick an amp, a speaker cabinet, and a microphone. It also adds effects like reverb and tremolo. Guitarists use it to record without a loud real amp.", "purpose_function": "It recreates amp, cabinet, and microphone tones digitally so players can get amplifier sounds without miking a real rig.", "practical_application": "An engineer records a clean DI guitar, then dials in an amp, cabinet, and mic position in Amp Designer to shape the recorded tone.", "category": "Amp/Distortion", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Bass Amp Designer", "Pedalboard", "DI box", "Speaker cabinet", "Microphone modeling", "Guitar amplifier"], "common_mistakes": ["Setting gain so high it masks the performance", "Ignoring the microphone type and its position", "Assuming it only works on guitar signals", "Placing it after heavy distortion by mistake"], "scenario_contexts": ["Re-amping a DI guitar in the mix", "Getting an amp tone quietly in a home studio", "Applying an amp character to vocals or synths"], "formula_symbolic": "", "formula_words": ""}, {"id": "bd4c7f38-d56e-4c91-90d2-173430da5f88", "term": "Bass Amp Designer", "definition": "Bass Amp Designer is a bass guitar amplifier modeling plug-in in Apple's Logic Pro (trademark Apple Inc.). It emulates three bass amplifiers and their speaker cabinets with three selectable microphones, plus a direct injection (D.I.) path that can be blended in parallel with the amp. It is Apple's implementation of generic bass amp, cabinet, and D.I. modeling.", "plain_english": "Bass Amp Designer copies classic bass amps inside Logic Pro. You choose an amp, a speaker cabinet, and a microphone. It also has a direct (DI) sound you can blend in. Bass players use it to record without a real amp.", "purpose_function": "It models bass amp, cabinet, microphone, and D.I. tones so a bassist can capture recorded bass sounds without hardware.", "practical_application": "A technician records a DI bass, then blends the modeled amp and cabinet sound with the clean D.I. signal for weight and clarity.", "category": "Amp/Distortion", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Amp Designer", "DI box", "Speaker cabinet", "Microphone modeling", "Bass guitar", "Parallel processing"], "common_mistakes": ["Ignoring the D.I. and amp blend option", "Over-driving the preamp and losing low end", "Choosing a mic position that thins the bass", "Confusing it with the guitar Amp Designer"], "scenario_contexts": ["Blending D.I. and amp tone on a bass track", "Recording bass quietly at home", "Shaping bass tone to sit in a dense mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "4c01736c-23f5-4931-ae60-937b2b2da80f", "term": "Beat Breaker", "definition": "Beat Breaker is a time and pitch multi-effect plug-in in Apple's Logic Pro (trademark Apple Inc.). It slices incoming audio in real time and lets each slice be reordered, repeated, and processed for time, pitch, filter cutoff, resonance, volume, and pan, forming recallable patterns. It applies the generic idea of rhythmic audio slicing and re-sequencing (scratch/stutter effects).", "plain_english": "Beat Breaker chops up audio as it plays inside Logic Pro. You can move, repeat, and rearrange the slices in time. It can also filter, pan, and change the volume of each piece. Producers use it to create stutters, scratches, and new rhythms.", "purpose_function": "It reshapes the rhythm and timing of audio in real time, letting users build stutter, glitch, and re-sequenced patterns from any material.", "practical_application": "A producer inserts Beat Breaker on a drum loop, draws a slice pattern, and switches between saved patterns for fills and variations.", "category": "Creative Effect", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Delay Designer", "Quick Sampler", "Sampler", "Time stretching", "Drum Machine Designer", "Glitch"], "common_mistakes": ["Expecting a simple delay rather than a slicer", "Not using Bypass Below to keep kick and bass intact", "Overusing patterns until the groove is lost", "Forgetting that it processes incoming audio in real time"], "scenario_contexts": ["Adding stutter fills to a drum loop", "Rearranging a vocal chop rhythmically", "Live-switching patterns during a performance"], "formula_symbolic": "", "formula_words": ""}, {"id": "ab2f0352-01ca-4c64-833a-6df5c63e1acd", "term": "ChromaGlow", "definition": "ChromaGlow is a saturation and harmonic-distortion plug-in in Apple's Logic Pro (trademark Apple Inc.). Per Apple's documentation it adds warmth and vintage character by simulating analog audio equipment and overdriven circuits. It is Apple's implementation of the generic analog-saturation / harmonic-coloration method.", "plain_english": "ChromaGlow adds warmth and grit to sounds inside Logic Pro. It copies the way old analog gear colors audio. A little makes tracks feel richer and fuller. Too much turns into obvious distortion.", "purpose_function": "It colors a signal with analog-style harmonics and saturation, adding warmth, weight, or drive that clean digital audio can lack.", "practical_application": "An engineer adds ChromaGlow to a drum bus or vocal for subtle harmonic warmth, or pushes it harder for obvious grit.", "category": "Distortion Effect", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Distortion", "Overdrive", "Saturation", "Bitcrusher", "Amp Designer", "Harmonic distortion"], "common_mistakes": ["Adding so much that it muddies the mix", "Confusing gentle saturation with hard clipping", "Using it on every track by default", "Ignoring gain staging into the effect"], "scenario_contexts": ["Warming up a digital vocal", "Adding weight to a drum bus", "Driving a synth for extra edge"], "formula_symbolic": "", "formula_words": ""}, {"id": "530e66c6-9de4-474c-bbf7-89cf2aaa7dfe", "term": "ChromaVerb", "definition": "ChromaVerb is an algorithmic reverb plug-in in Apple's Logic Pro (trademark Apple Inc.). It uses a circular absorption model with fourteen room-type algorithms that simulate how sound is gradually absorbed in a real space. It is Apple's proprietary implementation of generic algorithmic reverberation (not convolution).", "plain_english": "ChromaVerb adds space and echo tails to sound inside Logic Pro. It copies how rooms and halls make sound linger. You pick a room type and shape the tail. It makes dry tracks feel like they were recorded in a real space.", "purpose_function": "It creates artificial reverberation to place sounds in a sense of space, adding depth and ambience to a mix.", "practical_application": "An engineer sends vocals or drums to a ChromaVerb bus, chooses a room or hall type, and sets size and decay to add space.", "category": "Reverb", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Reverb", "Convolution reverb", "Space Designer", "Decay", "Pre-delay", "Early reflections"], "common_mistakes": ["Confusing algorithmic reverb with convolution reverb", "Setting decay so long it clutters the mix", "Adding it on every channel instead of a shared bus", "Ignoring pre-delay and losing clarity"], "scenario_contexts": ["Adding hall ambience to a lead vocal", "Creating room depth on drums", "Designing a large space for a film cue"], "formula_symbolic": "", "formula_words": ""}, {"id": "c2bb34a2-3ea7-4676-84a9-0faa820bc12a", "term": "Delay Designer", "definition": "Delay Designer is a multitap delay effect plug-in in Apple's Logic Pro (trademark Apple Inc.). It provides up to 26 individually editable taps, each with its own level, pan, pitch (transposition), and lowpass or highpass filtering. It is Apple's implementation of the generic multitap delay method.", "plain_english": "Delay Designer is an advanced echo tool in Logic Pro. It can create many separate echoes, called taps. Each tap can have its own volume, position, pitch, and tone. You can build a simple echo or a full rhythmic pattern.", "purpose_function": "It generates complex, individually shaped echoes, so users can make anything from a simple slap-back to a rhythmic delay sequence.", "practical_application": "An engineer places taps in time on a synth or vocal, tuning each tap's pan, pitch, and filter to build a rhythmic delay pattern.", "category": "Delay", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Delay", "Echo", "Beat Breaker", "Feedback", "Multitap delay", "Tap tempo"], "common_mistakes": ["Confusing it with a basic single-tap delay", "Creating so many taps the mix gets cluttered", "Forgetting to sync taps to the tempo", "Overusing feedback and causing buildup"], "scenario_contexts": ["Building a rhythmic delay on a vocal", "Creating a pattern-sequencer effect", "Adding a tuned slap-back to a lead"], "formula_symbolic": "", "formula_words": ""}, {"id": "1cd507f0-36bd-43f7-b249-f181805ea480", "term": "Direction Mixer", "definition": "Direction Mixer is a stereo-imaging plug-in in Apple's Logic Pro (trademark Apple Inc.). It decodes middle/side (MS) recordings or adjusts left/right (LR) signals, letting you set the stereo spread (width) and the pan direction of the stereo center. It is Apple's implementation of generic M/S decoding and stereo-width control.", "plain_english": "Direction Mixer changes the width and balance of stereo sound in Logic Pro. It can widen or narrow the stereo image. It also works with mid/side recordings, a method that captures a center channel and a separate sides channel. Engineers use it to control how wide a track feels.", "purpose_function": "It controls stereo width and center placement and decodes mid/side recordings, so engineers can adjust or correct the stereo image.", "practical_application": "An engineer uses it to decode an MS-miked recording, or to widen or narrow the stereo spread of a stereo track in the mix.", "category": "Imaging", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Mid/side (MS)", "Stereo width", "Panning", "Mono compatibility", "Imaging", "Spread"], "common_mistakes": ["Widening so far the mix loses mono compatibility", "Confusing MS mode with LR mode", "Forgetting that an MS recording must be decoded", "Over-widening and thinning the center"], "scenario_contexts": ["Decoding a mid/side room recording", "Widening a stereo synth pad", "Checking mono compatibility of a wide mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "65dd4c57-f338-44ad-994e-62075b388802", "term": "Drum Kit Designer", "definition": "Drum Kit Designer is a sampled virtual acoustic-drum instrument in Apple's Logic Pro (trademark Apple Inc.). It lets users build custom kits from a library of recorded drum and percussion sounds, exchange individual pieces, and adjust their tuning, dampening, and level; multi-mic 'plus' kits add microphone and room control. It applies generic multisampled-instrument playback and provides the kits used by the Drummer feature.", "plain_english": "Drum Kit Designer is a virtual acoustic drum set in Logic Pro. It uses real recorded drum sounds. You can swap out drums and change their tuning and volume. It gives realistic drums without recording a real kit.", "purpose_function": "It provides realistic sampled acoustic drums and lets users assemble and tune a custom kit for programming or for the Drummer feature.", "practical_application": "A producer loads Drum Kit Designer, swaps the snare and kick, tunes each piece to the song, then plays or programs the kit via MIDI.", "category": "Software Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Drum Machine Designer", "Drummer", "Drum Synth", "Sampler", "Multisample", "Snare drum"], "common_mistakes": ["Confusing it with the electronic Drum Machine Designer", "Ignoring the multi-mic 'plus' kits for mixing control", "Not tuning the pieces to the track", "Assuming it synthesizes rather than plays recorded samples"], "scenario_contexts": ["Building a custom acoustic kit for a song", "Editing the sounds of a Drummer track", "Tuning individual drums to fit a mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "2befffd2-0db2-4f11-8bd3-7e5258787ec3", "term": "Drum Machine Designer", "definition": "Drum Machine Designer is an electronic drum-kit instrument and interface in Apple's Logic Pro (trademark Apple Inc.). It shows a grid of pads where each pad represents a kit piece mapped to its own subtrack and sound source, such as Drum Synth or Quick Sampler, each with its own channel strip. It applies the generic drum-machine / pad-grid production concept.", "plain_english": "Drum Machine Designer is an electronic drum kit in Logic Pro. It shows a grid of pads, one per drum sound. Each pad can use a synth or a sample. Producers use it to build and mix electronic beats.", "purpose_function": "It organizes electronic drum sounds as pads, each on its own subtrack, so users can build, tweak, and mix a full electronic kit in one instrument.", "practical_application": "A producer loads a Drum Machine Designer kit, edits each pad's sound and channel strip, and programs beats on the pad grid or via MIDI.", "category": "Software Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Drum Kit Designer", "Drum Synth", "Quick Sampler", "Sampler", "Step Sequencer", "Drum machine"], "common_mistakes": ["Confusing it with the acoustic Drum Kit Designer", "Not realizing each pad is a separate subtrack and channel", "Overlooking that pads can host Drum Synth or Quick Sampler", "Forgetting to save a customized kit"], "scenario_contexts": ["Building an electronic beat from pads", "Layering a synth kick with a sampled snare", "Mixing each drum pad on its own channel"], "formula_symbolic": "", "formula_words": ""}, {"id": "7d924c8f-4294-48d0-a94b-1e75480ea923", "term": "Drum Synth", "definition": "Drum Synth is a drum-synthesis instrument in Apple's Logic Pro (trademark Apple Inc.). It generates kick, snare/clap, percussion, and hat/cymbal sounds through electronic synthesis rather than samples, with per-sound controls for pitch, filter, effects, and envelopes, plus mono, poly, and gate modes. It can run standalone or inside Drum Machine Designer, applying generic drum-synthesis methods.", "plain_english": "Drum Synth makes drum sounds inside Logic Pro using synthesis, not recordings. It covers kicks, snares, hats, and percussion. You shape each sound with knobs for pitch and tone. Producers use it for punchy electronic drums.", "purpose_function": "It creates fully synthetic drum sounds that can be tuned and shaped freely, useful for electronic drums, fills, and drum replacement.", "practical_application": "A producer uses Drum Synth to add a synthesized kick or fill to a groove, or embeds it in Drum Machine Designer to build an electronic kit.", "category": "Software Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Drum Machine Designer", "Drum Kit Designer", "Drummer", "Synthesizer", "Envelope", "Kick drum"], "common_mistakes": ["Assuming it plays samples instead of synthesizing sound", "Ignoring the group categories such as kicks and snares", "Not using key tracking for chromatic playback", "Overlooking the mono, poly, and gate modes"], "scenario_contexts": ["Adding a synth kick to a Drummer groove", "Designing a custom electronic snare", "Building an electronic kit inside Drum Machine Designer"], "formula_symbolic": "", "formula_words": ""}, {"id": "69014c66-b4f4-4bca-aee7-49ef3ad33ffd", "term": "EVOC 20 PolySynth", "definition": "EVOC 20 PolySynth is a vocoder instrument in Apple's Logic Pro (trademark Apple Inc.) that combines a vocoder with a polyphonic synthesizer. An analysis signal (usually a voice) supplied through a side chain shapes the harmonic content of the built-in synthesizer, which is played from a MIDI keyboard, producing talking and singing-synth timbres. It is Apple's implementation of the generic vocoder method.", "plain_english": "EVOC 20 PolySynth is a vocoder built into Logic Pro. A vocoder makes a synth 'talk' or 'sing.' It uses your voice to shape a synthesizer's sound. You play notes on a keyboard while speaking to get robot-voice effects.", "purpose_function": "It imposes the character of a voice (or other audio) onto a synthesizer, so users can create classic vocoder 'robot voice' and talking-synth sounds.", "practical_application": "An engineer routes a vocal into EVOC 20 PolySynth as the side-chain analysis source and plays chords to make the synth sing the vocal's words.", "category": "Software Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Vocoder", "Sidechain", "Synthesizer", "Formant", "Carrier and modulator", "EVOC 20 Filterbank"], "common_mistakes": ["Forgetting to set the side-chain analysis input", "Confusing the carrier synth with the analysis voice", "Expecting pitch correction instead of vocoding", "Speaking too quietly for clear articulation"], "scenario_contexts": ["Creating a robot-voice vocal effect", "Making a synth 'sing' a melody", "Processing drums for rhythmic vocoder textures"], "formula_symbolic": "", "formula_words": ""}, {"id": "9612dfa0-65a2-412b-89b7-de86288433a6", "term": "Grooveshifter", "definition": "Grooveshifter is a legacy rhythm effect plug-in in Apple's Logic Pro (trademark Apple Inc.). It rhythmically varies an audio recording to add a swing feel by delaying even beats, and it requires the project tempo to match the recording's tempo. It applies the generic swing / groove-timing concept to audio and is retained as a legacy plug-in.", "plain_english": "Grooveshifter adds a swing feel to recorded audio in Logic Pro. It gently delays certain beats to make the timing groove. The project tempo must match the recording. It is an older, legacy effect kept for compatibility.", "purpose_function": "It adds swing or groove to straight audio by shifting the timing of even beats, without re-recording the part.", "practical_application": "An engineer applies Grooveshifter to a straight guitar or drum recording, choosing whether the material is beat-based or tonal, then setting a swing amount to add groove.", "category": "Time/Pitch Effect", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Swing", "Quantize", "Groove template", "Tempo", "Legacy plug-ins", "Time stretching"], "common_mistakes": ["Using it when project and audio tempo do not match", "Choosing the wrong material type (beat versus tonal)", "Expecting it to fix badly timed playing", "Setting swing so high it sounds unnatural"], "scenario_contexts": ["Adding swing to a straight guitar part", "Grooving a recorded drum loop", "Matching a part's feel to a swung project"], "formula_symbolic": "", "formula_words": ""}, {"id": "83e54156-1828-4216-8aa9-2ed753aa799a", "term": "Multipressor", "definition": "Multipressor is a multiband compressor (multiband dynamics) plug-in in Apple's Logic Pro (trademark Apple Inc.). It splits the signal into up to four frequency bands, compresses each band independently (with downward expansion available per band for noise control), then recombines them. It is Apple's implementation of the generic multiband compression method used in mastering.", "plain_english": "Multipressor is a multiband compressor in Logic Pro. It splits sound into up to four frequency ranges. It squeezes the volume of each range on its own. Engineers use it to control loud parts without dulling the whole sound.", "purpose_function": "It compresses frequency bands separately, so heavy compression on one range does not affect the others, useful for mastering and adding glue.", "practical_application": "A mastering engineer uses Multipressor to tame a boomy low band or harsh highs independently while leaving the mids natural.", "category": "Dynamics Processor", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Compressor", "Adaptive Limiter", "Multiband compression", "Crossover", "Downward expander", "Mastering"], "common_mistakes": ["Over-compressing one band and unbalancing the tone", "Setting the crossover points carelessly", "Confusing it with a single-band compressor", "Ignoring the per-band downward expansion"], "scenario_contexts": ["Controlling a boomy low end on a master", "De-harshing vocals in a specific band", "Adding glue across a full mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "b53aec14-689b-4c97-a4a7-4224ff5eeeb9", "term": "Phat FX", "definition": "Phat FX is a multi-effect plug-in in Apple's Logic Pro that chains several processors to add weight and grit to a signal. It combines distortion stages, a bass enhancer, a modeled compressor, and a multimode resonant filter, with two LFOs, an envelope follower, and an assignable XY pad for modulation. The effects can be reordered in the chain. Phat FX is a proprietary Apple feature; the underlying processors are standard distortion, dynamics, and filter effects.", "plain_english": "Phat FX is a bundle of effects in Logic Pro from Apple. It stacks distortion, compression, a filter, and a bass boost in one plug-in. You use it to make drums, bass, or guitar sound thicker and punchier. You can drag the effects to change their order.", "purpose_function": "It bundles several tone-shaping and dynamics effects into one unit so an engineer can quickly add warmth, punch, and presence without loading many separate plug-ins.", "practical_application": "A technician inserts Phat FX on a bass, drum, or guitar track, picks a preset, then reorders the distortion, filter, and compressor blocks and modulates them with the XY pad.", "category": "Multi-effect plug-in", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Step FX", "Remix FX", "Distortion", "Compressor", "Multimode filter", "Low-frequency oscillator (LFO)"], "common_mistakes": ["Pushing the three distortion units too hard, which adds harshness and clipping instead of warmth", "Forgetting that effect order changes the result, so filtered-then-distorted sounds different from distorted-then-filtered", "Assuming it is a single distortion box rather than a full chain of processors"], "scenario_contexts": ["Thickening a DI bass track for a pop mix", "Adding grit and movement to a drum bus", "Designing an aggressive synth-bass tone for electronic music"], "formula_symbolic": "", "formula_words": ""}, {"id": "d0196a44-e852-452c-999c-f28b21939590", "term": "Quick Sampler", "definition": "Quick Sampler is a single-sample instrument plug-in in Apple's Logic Pro that builds a playable sampler from one audio file. You drag or record a sample, and it maps across the keyboard with C3 as the default root note. Its modes include Classic, One Shot, Slice, and Recorder, plus optional Flex time-and-pitch handling. Quick Sampler is a proprietary Apple feature based on standard sample-playback synthesis.", "plain_english": "Quick Sampler is a Logic Pro instrument from Apple that turns one sound file into an instrument. You drag in a sample, then play it up and down the keyboard. Higher keys play it higher and faster; lower keys play it lower. A mode called Slice cuts a loop into separate hits you can trigger.", "purpose_function": "It lets a producer create a usable, tuned sampler instrument from a single sound almost instantly, instead of building a full multi-sample instrument by hand.", "practical_application": "An engineer drags a vocal chop, drum hit, or loop into Quick Sampler, chooses One Shot for drums or Slice for a loop, then plays or sequences it from a MIDI keyboard.", "category": "Sampler instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Sampler", "Sample Alchemy", "Drum Machine Designer", "One Shot mode", "Slice mode", "Root key"], "common_mistakes": ["Confusing Quick Sampler (one sample) with Sampler, which maps many samples across zones", "Leaving the wrong root key set, so the sample plays back out of tune", "Using Classic mode for a drum hit when One Shot is the right trigger mode"], "scenario_contexts": ["Turning a recorded vocal phrase into a playable chromatic instrument", "Chopping a drum loop into individual slices for a new beat", "Triggering a single kick or snare sample as a one-shot"], "formula_symbolic": "", "formula_words": ""}, {"id": "645fd377-806e-4c28-8b6e-f4b37d2442ca", "term": "Remix FX", "definition": "Remix FX is a multi-effect performance plug-in in Apple's Logic Pro aimed at real-time, DJ-style manipulation, and is usually placed on the stereo output. Two XY pads control effects such as filter, wobble, orbit, repeater, reverb, and delay, alongside gater and downsampler sliders and reverse, scratch, and tape-stop buttons. All controls can be automated or driven by a MIDI controller. Remix FX is a proprietary Apple feature built from standard filter, gate, and tape-emulation effects.", "plain_english": "Remix FX is a Logic Pro plug-in from Apple for live remix tricks. You usually put it on the main output. Two touch pads control filters, delays, and reverb as you drag them. Buttons add scratch, reverse, and tape-stop effects like a DJ.", "purpose_function": "It gathers common DJ and electronic performance effects into one hands-on panel so an engineer can add fills, transitions, and stutters in real time and record them as automation.", "practical_application": "A producer puts Remix FX on the output bus, then uses the XY pads and tape-stop button to build up filter sweeps, breakdowns, and transitions while performing or recording automation.", "category": "Multi-effect plug-in", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Step FX", "Phat FX", "Automation", "Gater", "Downsampler", "Smart Controls"], "common_mistakes": ["Leaving Remix FX active on the output bus during mixdown, which unintentionally processes the whole mix", "Forgetting the effects only sound while a control is engaged or automated", "Overusing scratch and tape-stop so transitions sound gimmicky"], "scenario_contexts": ["Performing live filter and delay sweeps over a dance track", "Recording a tape-stop transition between two song sections", "Adding a stutter or gater fill before a chorus drop"], "formula_symbolic": "", "formula_words": ""}, {"id": "bd3cab71-7afc-4a21-844f-f1cd13e4541a", "term": "Retro Synth", "definition": "Retro Synth is a subtractive software synthesizer in Apple's Logic Pro that offers four oscillator engines: Analog, Sync, Table (wavetable), and FM. The chosen oscillator feeds a filter, amplifier, envelopes, and LFOs to shape the tone, covering classic analog, hard-sync, wavetable, and frequency-modulation sounds in one instrument. Retro Synth is a proprietary Apple feature; its methods are standard subtractive, wavetable, and FM synthesis.", "plain_english": "Retro Synth is a synthesizer in Logic Pro from Apple. It makes sound with oscillators, then shapes it with a filter and envelopes. You can switch between four engines: analog, sync, wavetable, and FM. Each engine gives a different family of classic synth tones.", "purpose_function": "It gives an engineer several vintage synthesis styles in one easy instrument, so basses, leads, and pads can be built without a separate synth for each method.", "practical_application": "A technician loads Retro Synth on an instrument track, picks the Analog or FM engine, then adjusts the oscillators, filter cutoff, and envelopes to create a bass, lead, or pad patch.", "category": "Synthesizer instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Subtractive synthesis", "Wavetable synthesis", "FM synthesis", "Oscillator sync", "Filter cutoff", "ES2"], "common_mistakes": ["Assuming it is only an analog synth and overlooking the FM and wavetable engines", "Setting the filter cutoff so low that the patch loses brightness", "Confusing the Sync engine's oscillator sync with tempo sync"], "scenario_contexts": ["Programming a punchy analog-style bass for a track", "Creating a metallic FM electric-piano or bell tone", "Building an evolving wavetable pad"], "formula_symbolic": "", "formula_words": ""}, {"id": "0007f93e-c440-46bb-ba7e-41299401b57c", "term": "Rotor Cabinet", "definition": "Rotor Cabinet is an effect in Apple's Logic Pro, part of the Vintage B3 organ, that models a rotary-speaker cabinet of the type associated with the Leslie brand. It simulates a rotating treble horn and bass rotor whose motion creates the characteristic swirling, Doppler-based sound, and it lets you place virtual microphones to set the listening position. Motor speeds can switch between slow (chorale) and fast (tremolo). Rotor Cabinet is a proprietary Apple feature; the underlying method is generic rotary-speaker modeling (Leslie is a trademark of its owner).", "plain_english": "Rotor Cabinet is a Logic Pro effect from Apple. It copies the sound of a spinning speaker cabinet used with organs. Spinning speakers make a swirling, wobbling tone. You can set the speaker speed and where the microphones sit. It is part of the Vintage B3 organ.", "purpose_function": "It recreates the swirling, moving sound of a rotary speaker so organ and other sounds gain that classic movement without a real spinning-speaker cabinet.", "practical_application": "An engineer uses Rotor Cabinet on a Vintage B3 organ part, switching between slow and fast rotor speeds and adjusting mic placement to get the classic swirling tone.", "category": "Rotary-speaker effect", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Vintage B3", "Scanner Vibrato", "Leslie speaker", "Doppler effect", "Rotary speaker", "Tremolo"], "common_mistakes": ["Confusing the rotary-speaker swirl with a simple tremolo or chorus effect", "Forgetting to switch rotor speed for musical effect, leaving it static", "Assuming it only works on organ when it can process guitar and other sounds"], "scenario_contexts": ["Adding classic swirl to a Hammond-style organ solo", "Speeding up the rotor for the climax of an organ passage", "Running an electric guitar through the rotary effect for a psychedelic tone"], "formula_symbolic": "", "formula_words": ""}, {"id": "dc887059-3ceb-4316-b52a-f390e0ede2c1", "term": "Sample Alchemy", "definition": "Sample Alchemy is an instrument in Apple's Logic Pro that transforms a single audio sample into a playable synthesizer using resynthesis. It offers additive, spectral, and granular synthesis modes across independent sources, plus play modes (Classic, Loop, Scrub, Bow, and Arp) that determine how the sample is read. Sample Alchemy is a proprietary Apple feature; its methods are standard additive, spectral, and granular resynthesis.", "plain_english": "Sample Alchemy is a Logic Pro instrument from Apple. It takes one sound and turns it into a playable synth. It can rebuild the sound using additive, spectral, or granular methods. Play modes like Scrub and Bow change how it moves through the sample. You then play it on the keyboard.", "purpose_function": "It lets an engineer mine a single sample for new synth textures, reshaping and stretching the sound in ways a plain sampler cannot.", "practical_application": "A producer drags a sample into Sample Alchemy, picks granular or spectral mode, chooses a play mode such as Scrub or Bow, then plays evolving pads or textures from the keyboard.", "category": "Resynthesis instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Quick Sampler", "Alchemy", "Granular synthesis", "Additive synthesis", "Spectral synthesis", "Sample Alchemy Scrub Mode"], "common_mistakes": ["Expecting simple sample playback and being surprised by the resynthesis behavior", "Confusing Sample Alchemy with the larger Alchemy synthesizer", "Choosing a play mode that does not suit the source, so the result sounds unstable"], "scenario_contexts": ["Turning a field recording into an evolving pad", "Creating granular textures from a vocal sample", "Designing an ambient bed from a single instrument note"], "formula_symbolic": "", "formula_words": ""}, {"id": "0fcbfc07-4ddd-46ab-9bc8-6a2ceabf37c0", "term": "Sample Alchemy Bow Mode", "definition": "Bow mode is a play mode in Apple's Logic Pro Sample Alchemy that reads the sample with a back-and-forth motion, like bowing a string. The upward stroke plays the sample forward and the downward stroke plays it in reverse, and a Bow rate control sets the speed, which can sync to project tempo. Up to four sources can sound together. Bow mode is a proprietary Apple feature within Sample Alchemy.", "plain_english": "Bow mode is one way Sample Alchemy plays a sound in Logic Pro from Apple. It moves through the sample back and forth, like a bow on a violin string. One direction plays forward; the other plays backward. A Bow rate control sets how fast this happens, and it can lock to the song tempo.", "purpose_function": "It creates smooth, continuous, bowed-string-like motion from a sample, useful for sustained, expressive textures rather than one-shot playback.", "practical_application": "A sound designer selects Bow mode in Sample Alchemy and sets the Bow rate to tempo to get a steady, sweeping bowed texture from a static sample.", "category": "Sample play mode", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Sample Alchemy", "Sample Alchemy Scrub Mode", "Play mode", "Granular synthesis", "Tempo sync", "Reverse playback"], "common_mistakes": ["Confusing Bow mode with Scrub mode, which follows your touch rather than a steady stroke", "Setting the Bow rate too fast, which turns the smooth motion into a buzz", "Forgetting that the down-stroke reverses the sample"], "scenario_contexts": ["Creating a bowed, string-like pad from a sustained sample", "Adding slow rhythmic motion synced to tempo", "Designing an evolving cinematic drone"], "formula_symbolic": "", "formula_words": ""}, {"id": "7e737462-83f3-4136-b224-1c1c75f8d550", "term": "Sample Alchemy Scrub Mode", "definition": "Scrub mode is a play mode in Apple's Logic Pro Sample Alchemy that plays the sample at the position you touch or move to, similar to scrubbing tape. A Scrub Jitter control adds randomization to the playback position, and up to four sources can play in unison. Scrub mode is a proprietary Apple feature within Sample Alchemy.", "plain_english": "Scrub mode is one way Sample Alchemy plays sound in Logic Pro from Apple. It plays the sample at the exact spot you touch. Moving across the waveform is like scrubbing through tape by hand. A jitter control adds small random shifts for a richer sound.", "purpose_function": "It gives hands-on, position-based control over where the sample plays from, letting an engineer freeze on or sweep through parts of a sound for texture.", "practical_application": "A producer uses Scrub mode to hold on an interesting part of a sample or sweep through it, adding Scrub Jitter for a thicker, less static tone.", "category": "Sample play mode", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Sample Alchemy", "Sample Alchemy Bow Mode", "Play mode", "Granular synthesis", "Scrubbing", "Jitter"], "common_mistakes": ["Confusing Scrub mode with Bow mode, which uses a steady back-and-forth stroke", "Adding too much Scrub Jitter, which makes the pitch and timing unstable", "Expecting normal start-to-end playback instead of position-based playback"], "scenario_contexts": ["Freezing on a single grain of a vocal for a sustained texture", "Sweeping through a sample by hand for a filter-like effect", "Adding jitter to thicken a thin source sound"], "formula_symbolic": "", "formula_words": ""}, {"id": "961b2a19-8005-4546-978c-36b7c3ea300f", "term": "Scanner Vibrato", "definition": "Scanner Vibrato is a section of Apple's Logic Pro Vintage B3 organ that emulates the electromechanical scanner vibrato and chorus of a Hammond B3-type tonewheel organ. The original used a rotating scanner and a delay line to sweep the phase of the signal, creating pitch vibrato or, when mixed with the dry signal, a chorus. It offers three vibrato depths (V1, V2, V3) and three chorus settings (C1, C2, C3). Scanner Vibrato is a proprietary Apple emulation of a generic tonewheel-organ vibrato/chorus (Hammond is a trademark of its owner).", "plain_english": "Scanner Vibrato is part of the Vintage B3 organ in Logic Pro from Apple. It copies a wobble effect built into old tonewheel organs. The original used a spinning part and a delay to shift the pitch slightly up and down. Mixing that with the plain sound makes a chorus. You pick from three vibrato and three chorus settings.", "purpose_function": "It reproduces the built-in pitch-wobble and chorus of a classic tonewheel organ, a core part of that instrument's recognizable character.", "practical_application": "An engineer turns on Scanner Vibrato in Vintage B3 and selects a setting such as C3 to give an organ part its classic shimmering movement.", "category": "Organ modulation effect", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Vintage B3", "Rotor Cabinet", "Chorus", "Vibrato", "Tonewheel organ", "Delay line"], "common_mistakes": ["Confusing scanner vibrato with the rotary-speaker swirl of the Rotor Cabinet, which is a separate effect", "Mixing up the vibrato (V) settings with the chorus (C) settings", "Assuming it is a generic modern chorus rather than a modeled electromechanical effect"], "scenario_contexts": ["Adding classic chorus movement to a jazz organ part", "Switching to a deeper vibrato for a solo line", "Recreating a vintage soul or gospel organ tone"], "formula_symbolic": "", "formula_words": ""}, {"id": "b99a7c4c-aed0-4844-b9f6-1a8bc7900fa5", "term": "Sculpture", "definition": "Sculpture is a component-modeling (physical-modeling) synthesizer in Apple's Logic Pro that generates sound by simulating a vibrating string and the objects and body around it. You set the string's material, choose exciters such as a bow, pick, or mallet to stimulate it, and position two movable pickups that capture the vibration. The result is shaped by envelopes, a waveshaper, filters, and body EQ. Sculpture is a proprietary Apple feature; the underlying method is generic physical/component modeling synthesis.", "plain_english": "Sculpture is a synthesizer in Logic Pro from Apple. Instead of using normal oscillators, it copies the physics of a vibrating string. You set what the string is made of and how it is played, like plucking or bowing. Two pickups catch the sound, just like on a guitar. This makes both real-sounding and strange new tones.", "purpose_function": "It models how real instruments make sound, letting an engineer create organic, evolving tones and hybrid instruments that subtractive synths struggle to produce.", "practical_application": "A sound designer uses Sculpture to build a plucked or bowed string tone, adjusting the material and exciter, then moves the pickups and morphs settings for evolving pads and basses.", "category": "Synthesizer instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Physical modeling", "Sculpture Material Pad", "Sculpture Morph Pad", "Retro Synth", "Exciter", "Pickup"], "common_mistakes": ["Treating Sculpture like a subtractive synth and ignoring the string and exciter model", "Placing both pickups at the same spot, which thins the sound", "Expecting instant results instead of tweaking the many linked physical controls"], "scenario_contexts": ["Designing an organic plucked-string pad", "Creating an evolving, morphing bass tone", "Building an unusual hybrid instrument for film scoring"], "formula_symbolic": "", "formula_words": ""}]$ap$::jsonb)),
elig AS (SELECT r FROM p
  WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id=(r->>'id')::uuid)
    AND NOT EXISTS (SELECT 1 FROM glossary g WHERE g.term=r->>'term')),
g AS (
  INSERT INTO glossary (id, term, definition, plain_english, purpose_function, practical_application,
     category, difficulty, related_terms, common_mistakes, scenario_contexts, formula_symbolic, formula_words, achievement_id)
  SELECT (r->>'id')::uuid, r->>'term', r->>'definition',
     NULLIF(r->>'plain_english',''), NULLIF(r->>'purpose_function',''), NULLIF(r->>'practical_application',''),
     NULLIF(r->>'category',''), NULLIF(r->>'difficulty',''),
     ARRAY(SELECT jsonb_array_elements_text(r->'related_terms')),
     ARRAY(SELECT jsonb_array_elements_text(r->'common_mistakes')),
     ARRAY(SELECT jsonb_array_elements_text(r->'scenario_contexts')),
     NULLIF(r->>'formula_symbolic',''), NULLIF(r->>'formula_words',''), (r->>'achievement_id')::uuid
  FROM elig ON CONFLICT (id) DO NOTHING RETURNING 1
),
tp AS (
  INSERT INTO glossary_topics (glossary_id, achievement_id, is_primary, difficulty)
  SELECT (r->>'id')::uuid, (r->>'achievement_id')::uuid, true, NULLIF(r->>'difficulty','')
  FROM elig WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id=(r->>'id')::uuid AND gt.achievement_id=(r->>'achievement_id')::uuid)
  RETURNING 1
)
INSERT INTO glossary_topics (glossary_id, achievement_id, is_primary, difficulty)
SELECT (r->>'id')::uuid, ct::uuid, false, NULLIF(r->>'difficulty','')
FROM elig, jsonb_array_elements_text(r->'cross') ct
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id=(r->>'id')::uuid AND gt.achievement_id=ct::uuid);
COMMIT;
